values
  (5, 'S1', 1, '13일 코스피는 전날보다 234.30포인트(3.56%) 오른 6813.34에 마감했다.', '619ea4223bf3f5737b580c3b5c73fd764587bf63b2735b785e540dade6b44bb7', true, true),
  (5, 'S2', 2, '같은 날 코스닥은 2.46포인트(0.29%) 오른 1419.4에 마감했다.', '9c183bc349369bc70ae4b4a13015a59faf652d3b1eedf5ff34a24004e43f02c6', true, false),
  (5, 'S3', 3, '서울 외환시장에서 원·달러 환율은 7.7원 내린 1416.1원에 마감했다.', 'da54efe990b418152e78f8495f65130ffbce86b6e3a5e68f79262baa51053b6b', true, false),
  (6, 'S1', 1, '한국전력의 2026년 2분기 영업이익은 1조1286억원으로 지난해 같은 기간보다 47.2% 줄었다.', 'a63c24556451f92856a0ecfc7132b2de2e0cbf3dc765d7b8dab9b9c1ed3395ab', true, true),
  (6, 'S2', 2, '매출은 21조9189억원으로 0.1% 줄었고, 순이익은 2775억원으로 76.4% 줄었다.', '5bb163966f92387b99f7bf187fd7b218bba151ddeb2a973a9a9704294e4c855c', true, false),
  (6, 'S3', 3, '한국전력은 전기 판매량이 조금 줄고 연료비가 늘어난 점을 영업이익 감소 원인으로 들었다.', 'e39939f64057acbf7b9db70fac57042ea9c874e66ceee76291f31348510ad94f', true, false),
  (11, 'S1', 1, '[OSEN=고용준 기자] 해외 매출 뿐만 아니라 &lsquo;리니지 클래식&rsquo;의 실적이 반영되면서 영업이익에서는 전년 대비 1053% 상승이 이뤄졌다.', 'dff0fac920bfef3b2e0b2152627f4565c43f790ccae7270b212a373ea5d51fb9', true, false),
  (11, 'S2', 2, '엔씨가 2분기 연속 역대 최고 PC 매출 경신한 2026년 2분기 실적을 발표했다.', '221ecb4885a7333c9b410fcebe51bda564c24a797933374e2933731cc9be53ba', true, false),
  (11, 'S3', 3, '엔씨소프트는 지난 11일 2026년 2분기 실적 결산(연결기준) 결과 매출 7705억 원, 영업이익 1739억 원, 당기순이익 1312억 원을 기록했다고 밝혔다.', '8a35855a2c584112af4008d6f4a6d99f319f668edd8ca2d6e9ebff5ce6cf947b', true, true),
  (11, 'S4', 4, '매출과 영업이익은 전분기 대비 각각 38%, 53% 증가했으며, 전년 동기 대비로는 각각 101%, 1,053% 상승했다.', 'f869ba5ac57e5728d2f3e46be657a79f89031523b4557ec83cfc0d991b8f28c6', true, false),
  (11, 'S5', 5, '이번 분기 영업이익률은 23%로 집계됐다.', '01247b85a2ee08bdb875657ff5bbf70cf50f929cab05113488ac135493194937', true, false),
  (11, 'S6', 6, '지역별 매출 비중은 한국 48%, 아시아 25%, 북미&middot;유럽 등 27% 순이다.', 'c169a1944c2bb4988ce4f243a20ddb373aa49d92bdc9942443ec570374ead51e', true, false),
  (11, 'S7', 7, '엔씨소프트에 따르면 해외 매출 비중은 4분기 연속 증가세를 기록하고 있다.', '8871faac3988b6b11c07e2cd887efc7c357adb91d4fcb7f6446eba7c543d2013', true, false),
  (11, 'S8', 8, '이는 글로벌 모바일 게임 플랫폼 ''저스트플레이(JustPlay)''의 최초 연결 편입에 따른 결과로, 모바일 캐주얼 사업은 엔씨소프트 전체 분기 매출의 22%를 차지하게 됐다.', '0bdd7f558d10fa743c27473333d817492bceb2ab2632b25e97b577fe45964fd7', true, false),
  (11, 'S9', 9, '한편 엔씨소프트는 오는 8월 26일 독일 쾰른에서 개막하는 게임쇼 &lsquo;게임스컴 2026&rsquo;에 참가할 예정이다.', 'a43e9c75e13deec23c57b833869363e08a2eb61780bfed35b1611f98a17ee618', false, false),
  (11, 'S10', 10, '엔씨소프트는 해당 행사에서 아이온2, 신더시티, 프로젝트 본파이어 등 개발 중인 글로벌 신작 라인업을 공개할 계획이다.', 'd91c2f7ebf36c6ce449e3519b47fd996414bd2a3690abfe72e06e99cf7e2979b', false, false),
  (12, 'S1', 1, '전년 대비 매출 22.5%·영업이익 29% 증가…영업이익률 33.3%', '9ed3004bb296602c68bd2ad012121dea57b55ea54a8addc1f2a162e33546a3c6', false, false),
  (12, 'S2', 2, '팍시게임즈 매출 126% 급증…AI 기반 신작 비중 81%', 'a465bbf0b5121a7b5792e8fdc87403ac6830d362d8ddadf7f7b10dcc07a1562b', false, false),
  (12, 'S3', 3, '[서울=뉴시스]오동현 기자 = 더블유게임즈가 소셜카지노의 안정적인 성장과 캐주얼게임 사업 확대에 힘입어 2개 분기 연속 사상 최대 실적을 경신했다.', 'aa98d82c673a82287bff354c7c3b8e13fb336fe104002f3f88d997c08429f333', true, false),
  (12, 'S4', 4, '더블유게임즈는 올해 2분기 연결 기준 매출 2106억원, 영업이익 701억원을 기록했다고 12일 공시했다.', 'a9476e627b95448f8d856cf9aba3b774d86cd8ac998877ab4a356f0479f6b3d1', true, true),
  (12, 'S5', 5, '전년 동기 대비 매출은 22.5%, 영업이익은 29% 증가했다.', 'a132ae00afefecfd600e8ab04ca51aa436c93397ad69c6c3da087fed6b6b125a', true, false),
  (12, 'S6', 6, '매출은 7개 분기 연속 성장했다.', '5e43ae00fc221b8e21a87e934a3637e65153970e9a365049d98267d2e1b7a0bf', true, false),
  (12, 'S7', 7, '자체 결제 시스템을 이용하는 직접판매(DTC) 매출 비중이 47.5%까지 확대되면서 플랫폼 수수료 부담을 줄인 것이 수익성 개선으로 이어졌다.', 'e55eb11ee77fe248ad533f81cdab42a6290056880fb53283d12fbfad61e62bd7', true, false),
  (12, 'S8', 8, '상반기 누적 매출은 전년 동기 대비 24.5% 증가한 4156억원, 영업이익은 27% 늘어난 1385억원으로 집계됐다.', 'bbee514e721e9ddb7b6f782965da8df21ce34ad2d86f7c23f77a73359440a076', true, false),
  (12, 'S9', 9, '더블유카지노와 더블다운카지노 등 기존 게임의 안정적인 운영에 지난해 7월 인수한 와우게임즈의 실적이 더해졌다.', '8eaf7f93cd5d5c5ab6b9cd63ce096aec3551574253bb09b4dc7ebfd8b55670f2', true, false),
  (12, 'S10', 10, '더블유게임즈 관계자는 "소셜카지노의 안정적인 수익 기반 위에서 캐주얼게임과 아이게이밍 사업의 성장이 본격화하고 있다"며 "하반기에도 신규 성장동력의 성과를 확대해 실적 성장세를 이어갈 것"이라고 말했다.', 'fd2bbc23aaf716f01e3b79f14a89ef7cf855a95afe15271ea5bf90d8b65d83ac', false, false),
  (13, 'S1', 1, 'HMM 2만4000TEU급 컨테이너선 HMM헬싱키·르아브르 호 르포 /사진=김훈남 HMM이 올해 상반기 매출 6조1207억원을 기록해 전년 동기 대비 12% 증가했다고 13일 밝혔다.', '04d01a6063cf387a2779c97e19c8a5946910aebf09ca76f3523d5d3c4474ce74', true, false),
  (13, 'S2', 2, '다만 영업이익은 6232억원으로 같은 기간 26% 감소했다.', '0c9ccba30e6b4ecc9b0093239ba44f4c45bad685ebde2213a82e9c480cda32fa', true, false),
  (13, 'S3', 3, 'HMM의 지난 1분기 영업이익은 2691억원으로 전년 동기 대비 56% 감소했지만, 2분기에는 3541억원으로 전년 동기 대비 52% 증가했다.', 'dba89add542b6a6da2e8e38cb73c7e2ea52c40d9159e92450a9fd5a69f88750d', true, true),
  (13, 'S4', 4, '직전 분기와 비교해도 영업이익이 31.6% 늘었다.', '26787b74a05ec28fc884a0d48538591da5b03578ab2a2e5c7da513bf80aad88e', true, false),
  (13, 'S5', 5, '매출 역시 1분기 2조7187억원에서 2분기 3조4020억원으로 25.1% 증가했다.', '940921785cfc5537ea107286820d26b927d0a835968b18aa7e2a63f2e9602566', true, false),
  (13, 'S6', 6, '2분기 실적이 반등한 배경에는 5월 말부터 시작된 해상운임 상승이 있다.', '52ac3978650be0a3fd57c5478b37cafc16608f4ad61c729b35105da9b45ee7b4', true, false),
  (13, 'S7', 7, '지난 3월 중동 사태로 발생한 매출 손실과 연료비 등 원가 부담이 1분기 실적을 끌어내렸지만, 물류 성수기가 예년보다 일찍 시작되면서 2분기 수익성이 개선됐다.', '93b15f403d1ae951ac84dda1b179d459a04cffe62881f401c425a7fda7f48ad2', true, false),
  (13, 'S8', 8, '올해 상반기 상하이컨테이너운임지수(SCFI)는 평균 1957포인트로 지난해 같은 기간 평균 1701포인트보다 15% 상승했다.', 'd262bebbfdfa5a00c4a7181f7bec236a196ccc889900ae3a90bdea96874347d2', true, false),
  (13, 'S9', 9, '실제 올해 1분기 평균 SCFI는 1507포인트로 전년 동기보다 14% 낮았다.', '1860f61d2d4d0ff5c1993b07ebdf0178c9ff01c54ed50c3d8b2427df881d03e0', true, false),
  (13, 'S10', 10, 'HMM 관계자는 "상반기 영업이익률은 10.2%로 글로벌 선사 중 상위권을 유지했다"며 "중동 사태 이후 고유가에 대비한 연료비 최적화와 ''허브 앤 스포크'' 전략 등을 바탕으로 선대 운영 효율성을 극대화할 것"이라고 말했다.', 'c5680c0f666222d662d59a60b4bd4b0ba760d3486853ae48b5d5084148e6c496', false, false),
  (14, 'S1', 1, 'LG전자 소액주주 100만명 첫 돌파', '0d5bd14934050c9f2e5fd113d04c2f1d0412e371fc71c6830dd11903610b66d5', false, false),
  (14, 'S2', 2, '6월 장중 주가 43만 8000원까지 상승', '80a5ebeb223df57ff32211ef6e38b3a69097af489dab0be03a2c37a4ad56ae22', false, false),
  (14, 'S3', 3, '반도체·구리 가격 상승에 원재료 매입비 1조↑', '42de265699cd6dfa6b36415f36ceebc074e5c6727401b31818ffedf67e22392f', false, false),
  (14, 'S4', 4, '구광모 회장 상반기 보수 48억원 수령', 'dbf17d046d70520ee13cdf8001978fd9be7b0b2349cffaa53e0c7bb76678fd8b', false, false),
  (14, 'S5', 5, '로봇과 인공지능(AI) 신사업을 확장하며 기대를 모았던 LG전자의 소액주주 수가 올해 상반기 처음으로 100만명을 돌파했다.', '0121b98a750de2e46e1043e6ad1d8629ebaf054cc1cb0dbbf1f2f32efd487f40', true, false),
  (14, 'S6', 6, '14일 LG전자 반기보고서에 따르면 올해 6월 말 기준 소액주주 수는 122만 7359명으로 지난해 말(51만 1135명)보다 약 71만 6000명 증가했다.', '0aa8675cd9777ecce07ce191bbdfdc63a31dbb6af8e267a0b57b9257999c94fe', true, true),
  (14, 'S7', 7, '소액주주가 보유한 지분은 전체 발행주식의 58.43%다.', '66fcfab3a57f5db49337fda16f4d394717be3bf8b2c4598b0cd00f0167c27064', true, false),
  (14, 'S8', 8, '올해 초 8만~9만원대에 머물던 LG전자 주가는 실적 개선과 피지컬 AI·로보틱스 등 미래 사업 확대 기대감에 힘입어 상승세를 탔다.', '53c0e07723ae7b15cd7d154368c17aeb858c1fbbb61446b8a656d96c6d090643', false, false),
  (14, 'S9', 9, '한편 반도체와 구리 등 주요 원자재 가격 상승 여파로 LG전자의 올해 상반기 원재료 매입액은 지난해보다 1조원 이상 늘어났다.', 'c9d9a86a0a2c6b0c5f542122e68ae6b716aa6664a875804cd210111ede4d7bc1', false, false),
  (14, 'S10', 10, 'LG전자에서는 지난해 말 퇴임한 조주완 전 최고경영자(CEO)가 급여 5억 1000만원, 상여 6억 7300만원, 퇴직소득 41억 200만원을 포함해 총 52억 8500만원을 받았다.', 'daa2303f560cc09fba0d9f1ae659dcca6eb70071f11332c324487272c9dd2f52', false, false),
  (15, 'S1', 1, '삼양식품 삼양식품이 올 2분기 연결기준 매출액이 7703억원, 영업이익은 1762억원으로 집계됐다고 14일 공시했다.', '89df31df327e3ce002891e4420b0156b23b4b4e8a154f2e8f0dde7a4b0891c6d', true, true),
  (15, 'S2', 2, '지난해 같은 기간보다 각각 39.3%, 46.7% 늘어난 규모다.', 'a3772eb64cfb8db0624eca42bcfbe5da99f0d656d957346e991f76c715e643a9', true, false),
  (15, 'S3', 3, '실적 성장은 해외사업이 이끌었다.', '3012f0c1d8a693ceb2c3e0a0c5d8e7a8b74a6224efacbbf40ee27a0c9ba97e6d', true, false),
  (15, 'S4', 4, '2분기 해외매출은 6458억원으로 전년 동기 대비 46.7% 증가했다.', '3f2fc1ac43728f32432177fff1308d62d79ca4eb70acf61ef26f070933c3720d', true, false),
  (15, 'S5', 5, '분기 해외매출이 6000억원을 넘어선 것은 처음이다.', 'd1f0e3e4daf976941c8668602ccf484d274e99f99d33a06c21ae4922a19860fb', true, false),
  (15, 'S6', 6, '삼양식품 측은 미국 내 일반 유통채널과 아시아계 유통채널 입점 확대, 멕시코 등 중미지역의 판매 증가가 영향을 미쳤다고 설명했다.', '43f1cf186df186c24a391f96162b4822bcd7e7e627e8a1ff9c41d971d40b80da', true, false),
  (15, 'S7', 7, '독일·프랑스 등에서 판매가 늘고 진출국이 확대된 유럽에선 매출 806억원을 달성해 61% 성장률을 보였다.', '5223f957a15db95426adf98c38aa1578e26c721001d3944412e1fd03bb91efde', true, false),
  (15, 'S8', 8, '매출 증가에 힘입어 영업이익률은 23%를 기록했고, 지난해 1분기부터 6분기 연속 20%대 영업이익률을 유지했다.', '15c7dd02c33af50640c933ca64ef890fe0cbd3de33bd0c6b73dfc1844915767c', true, false),
  (15, 'S9', 9, '해외 유통망 확대에 따른 판매채널 개선과 생산 효율 증대, 고환율 효과 등이 수익성 향상에 영향을 준 것으로 분석됐다.', 'b566361f6dab55c3cb7c72d4c032055df690276b926730fbad3643aa908d17e6', true, false),
  (15, 'S10', 10, '삼양식품 관계자는 “해외사업을 중심으로 한 성장세가 이어지고 있다”며 “지역별 해외법인의 역할과 국내외 생산 기반을 강화해 글로벌 수요 증가에 대응하겠다”고 밝혔다.', '905f77ba1723ae9bb0db04708cb1384d87b5e5d61839a6ade720fbaee020693b', false, false),
  (16, 'S1', 1, '사계절 내내 원하는 식재료를 구할 수 있는 시대에 오히려 ''지금이 아니면 맛볼 수 없는 맛''을 찾는 소비자가 늘고 있다.', '1e6a236e9073566ebda54b9ea0a3fd2055a0ff639fbb16467939c77c4e186746', false, false),
  (16, 'S2', 2, '오리온은 매년 6월부터 국내산 햇감자가 수확되는 시기에 맞춰 ''포카칩''과 ''스윙칩''을 생산한다.', '58bcc3058bcb6ef5fac55fcc0026d88ee8b648fad42f1af1e36873097dd3dd94', true, false),
  (16, 'S3', 3, '지난해 6~11월 국내산 햇감자로 생산한 포카칩 매출은 ''제철 과자'' 열풍이 본격화하기 전인 2022년 같은 기간보다 36% 증가했다.', '539c48c71a4722cecb2be74663db600cb6f607417be102b99079c60dc7f59675', true, true),
  (16, 'S4', 4, '오리온은 1988년 국내 식품업계 최초로 감자연구소를 설립하고 감자칩에 적합한 품종과 재배 기술 등을 연구해왔다.', 'fb83ece89164743302c812a38c172d624bcd8019aacc984cb421f3ca0732edde', false, false),
  (16, 'S5', 5, '현재 오리온은 국내에서 300여 농가와 계약재배를 통해 연간 1만5000t 규모의 국산 감자를 조달하고 있다.', 'e125616a4f053d0ee2c804068fc2d3ce99e2c725e1e0797881559866abc364b5', true, false),
  (16, 'S6', 6, '해외에서도 베트남 현지 농가와 계약재배를 통해 연간 약 1만7000t의 감자를 확보하고 있으며, 중국에서는 내몽골 직영농장을 운영하는 동시에 감자 플레이크 공장을 구축해 원재료부터 제품 생산까지 이어지는 공급망을 갖췄다.', '7955be4b9d085b70d30e5912a15cb4089ace9121291088dce71277601e0a2742', false, false),
  (16, 'S7', 7, '오리온이 사용하는 감자는 국내외를 합쳐 연간 약 23만t에 달한다.', '86040ad11b2014d72146b2571cdeabe8f05a46e7c4488f894db74197f65e0c8c', false, false),
  (16, 'S8', 8, '지난해 오리온의 글로벌 감자스낵 매출은 8740억원으로 전년 대비 약 10% 증가했다.', '3308478329f3cb7e41dd03f8ad8304de75f5775af780da2c544a9c3d0efec054', true, false),
  (16, 'S9', 9, '오리온은 포카칩·오!감자·스윙칩·예감 등 감자스낵 4종을 중국과 베트남 등 해외 시장에서 성장시키고 있다.', '0edee8d572dc076849dd1064e9f52b7cc76b7d8167dfb9f73574b9375da20b0a', false, false),
  (16, 'S10', 10, '오리온은 감자스낵 사업 확대에 맞춰 생산능력을 늘리고 있다.', '776a6fffa9977e95f6f31239eb5c978d45c28b5fc8cc4b2c138aae831eec5cd2', true, false),
  (17, 'S1', 1, '상반기 매출 1조8901억…전년比 7.3%↑', 'dffba2eedc8d233d2976f45d519e2a4720ea4ea6edfb3f82914c572f18fec17a', false, false),
  (17, 'S2', 2, '영업이익도 1267억으로 31.7% 증가 농심이 해외사업 성장에 힘입어 올 2분기 매출과 영업이익을 모두 끌어올렸다.', 'b230166a62dfe8824b12e8e93491a676efd16d698cb67265501b7541e0894a53', false, false),
  (17, 'S3', 3, '미국과 중국 등 주요 해외법인이 성장한 데다 유럽 사업이 빠르게 확대되면서 국내 소비 둔화와 원가 부담을 상쇄했다.', 'd13debeef7e2822c2e4cceb26cf8a023664779dc3e4b22cc8f4d29f5e11f739a', true, false),
  (17, 'S4', 4, '농심은 올해 2분기 연결 기준 매출이 9561억원으로 지난해 같은 기간보다 10.2% 증가했다고 14일 공시했다.', 'b2bd0a178d7009d7d06f4f8e55e6e69552db3b87aa5bbb4ffdbdcf459ff46e2b', true, true),
  (17, 'S5', 5, '영업이익은 593억원으로 47.6% 늘었다.', 'a2e16bc74c228a2c42f49485d15e14cc34e73b6bdb756d6e0c0e0916fa48cf29', true, false),
  (17, 'S6', 6, '영업이익은 1267억원으로 31.7%, 당기순이익은 1153억원으로 30.2% 늘었다.', 'd51318a606b21d3230dde08cb8051737b58893d9d3a2e7ecba499b428ccd5266', false, false),
  (17, 'S7', 7, '국내 생산법인의 수출을 합친 해외사업 매출 비중은 40.2%로 높아졌다.', 'cd030f1b6b79467db962194c7f08d4c20efa603bce7645594542e2d5d4585c9e', true, false),
  (17, 'S8', 8, '농심의 상반기 매출총이익률은 지난해 28.2%에서 올해 30.4%로 2.2%포인트 상승했다.', '374808343ad43fed9cf976f3b7695b006bc1d273dfbb7e8df41609156a863498', false, false),
  (17, 'S9', 9, '농심의 2분기 별도 기준 매출은 7384억원으로 전년 동기보다 6.4%, 영업이익은 321억원으로 4.2% 증가했다.', 'd3922d01e92d5ad3a65db0760bddcde5eaf8007431ce83fc896dca819dbdbddb', false, false),
  (17, 'S10', 10, '전 분기와 비교하면 매출은 3.3% 늘었지만 영업이익은 32.0% 감소했다.', '86d806773ac515a166af8abfa70dcf655d9e3d68d363ee3c69b050569acd11e9', false, false),
  (18, 'S1', 1, '美 케머러 1호기·후속 상용 프로젝트 참여 확대', '6aa9d7f8d52fa0154da146224cb5c0620ff34cfef9caffa9624fded45990ed41', false, false),
  (18, 'S2', 2, '국내 원전 공급망 활용 검토…LNG·ESS·SMR 묶은 통합 에너지 사업 추진', 'a4aa9eccb0044a68ec4ce09569005e5b00932291af244599dd673d31239f11e0', false, false),
  (18, 'S3', 3, '뉴스1 SK이노베이션이 미국 원전기업 테라파워와 차세대 소형모듈원자로(SMR) ‘나트륨(Natrium)’ 사업 협력을 확대한다.', '60955c334995be544cae60259e00eebf24fea315693f463013e49b0fa50d4b34', true, false),
  (18, 'S4', 4, 'SK이노베이션은 14일 서울에서 추형욱 SK이노베이션 대표이사와 크리스 르베크 테라파워 최고경영자(CEO)가 만나 나트륨 SMR 사업 협력과 글로벌 시장 진출을 위한 사업협력 주요 조건 합의서를 체결했다고 밝혔다.', '07262843b2f8829a876bad0347a9331dc606fd2a95fa878882e116166d19f4a7', true, true),
  (18, 'S5', 5, 'SK이노베이션과 SK는 2022년 테라파워에 총 2억5000만달러(약 3534억 원)를 공동 투자해 2대 주주가 됐다.', '83cab9551546832d8a5a99cb5491ed49a4d003c362c8f43eae8c99bfa15310d8', true, false),
  (18, 'S6', 6, '합의서에는 테라파워가 미국에서 추진 중인 나트륨 SMR 실증로와 후속 상용 프로젝트에 대한 SK이노베이션의 참여 확대를 비롯해 국내 SMR 공급망 활용, 국내 나트륨 SMR 사업 개발, 글로벌 프로젝트 공동 발굴 등의 내용이 담겼다.', '6c0d2b2c102249c2e79036955284b0498f7dbae5a093cca740ef07d79067df4b', true, false),
  (18, 'S7', 7, 'SK이노베이션은 테라파워가 미국 와이오밍주에서 추진하고 있는 나트륨 SMR 프로젝트 ‘케머러 1호기’와 이후 진행될 상용 프로젝트에 참여를 확대할 계획이다.', 'f3afeaa8ad55376b8d548e1746f01f880e19c8b7aab9cf0b8967025425158cfb', true, false),
  (18, 'S8', 8, 'SK이노베이션은 미국 사업 참여를 통해 차세대 원전의 설계와 건설, 운영 과정에서 경험을 확보하고 이를 향후 국내 사업 검토와 해외 프로젝트 개발에 활용한다는 방침이다.', '03b8cc92ec4e4c01b163fa98551cdb0338bd1f2a5f98b4cddf6bcdafff30c6e5', false, false),
  (18, 'S9', 9, 'SK이노베이션은 이번 협력을 회사의 전기화 전략과도 연결한다.', 'd4d221d5d4508c021424aab4239a4f66cac0c3f21e627b28f77615b31aed431a', false, false),
  (18, 'S10', 10, 'SK이노베이션은 LNG 직도입과 LNG 발전, 전력사업 역량을 보유하고 있으며 SK온을 통해 배터리와 에너지저장장치(ESS) 사업도 확대하고 있다.', '6b69d643cb62662cd9477c43aee8544c75d2b99d1130445270ebc5c2b0541d0c', false, false),
  (19, 'S1', 1, '매출 3496억·영업익 529억…15.4%·11% 증가', '351e7553356935a7d151293082abce18966eab2716498ac25fab20ae3f791c9c', false, false),
  (19, 'S2', 2, '공연 규모 확대·광고 및 행사 매출 늘어', '7c44b5353a071466a7f47b15d1e8da6cb1afdb1a4a62ced92c07e7b01a6c859c', false, false),
  (19, 'S3', 3, '드림메이커·디어유 등 종속 법인도 실적 기여', '4fcf2c8343031da1e5c3574b2a7b6f2ce6ce5495e510924f9b11238fe4284d9e', false, false),
  (19, 'S4', 4, '에스엠 엔터테인먼트(SM, 041510)가 2026년 2분기 연결 기준 매출 3496억원, 영업이익 529억원을 기록했다.', 'a61394adfdda9150061c636875e30d5abcc2e864d3a0a534fb3a54f2ac617db1', true, true),
  (19, 'S5', 5, '별도 매출은 전년 동기 대비 9.2% 증가한 2406억원으로, 출연 매출 27.9%, 콘서트 매출 23.6%, MD·라이선싱 매출이 22% 증가하는 등 고른 성장세를 보였다.', 'dc894ff0e708474997079041d54e8a04e1ead4b603f9c9280b5b021dddd051b4', true, false),
  (19, 'S6', 6, '영업이익과 당기순이익은 전년 동기 대비 각각 4.6%와 18.1% 감소한 438억원과 241억원을 기록했다.', 'cfa16433c852356cd3e64e35d758d055f500f900756c05e9ade0e906653de797', false, false),
  (19, 'S7', 7, '레거시 IP의 공연 규모 확대에 따른 콘서트 매출 성장과 주요 종속 법인 매출 확대가 실적에 기여했다.', 'dc21b82bc8bee8a2029f81deffec3eee0d88ce5d4d696a516c64c516d70463c3', false, false),
  (19, 'S8', 8, '고연차 아티스트의 투어가 확대하면서 콘서트 매출이 늘었고, 광고 및 행사도 증가해 성장을 견인했다.', '3a003fb37d61e4744f30b2932f707743af4c59806d9793278ed662389fa1d9bc', true, false),
  (19, 'S9', 9, '동방신기(TVXQ!), 슈퍼주니어(SUPER JUNIOR), 엑소(EXO), 에스파(aespa), NCT 위시(WISH) 등 다양한 아티스트들이 글로벌 투어를 진행했고, 대규모 공연 MD 판매와 더불어 NCT 10주년 기념 팝업, 에스파, 라이즈(RIIZE), NCT 위시 신보 발매와 연계된 팝업 이벤트 등을 열었다.', '1f90f41731db9405e4c0268c455ebcade8553ab01834055436165e30a0332f95', false, false),
  (19, 'S10', 10, '주요 종속법인들 역시 각 사업 분야에서 견조한 실적을 보였다.', '3bb4fd3d0850aaff9412083e9f92a6cdcb3286d376a784f8066858b28cb6a39e', false, false),
  (20, 'S1', 1, '/사진제공=JYP엔터테인먼트 JYP엔터테인먼트(이하 JYP, JYP Ent.)는 글로벌 보이그룹 뻔푸소년CIIU(씨투유)가 현지 첫 미니 앨범을 발매한다고 24일 밝혔다.', 'e82bc07cff8cb89965a777cdda2aa42b20c0d24ca8ae49c9e56b6db057cb7ca0', true, true),
  (20, 'S2', 2, '뻔푸소년CIIU는 다음달 4일 첫 번째 미니 앨범 ''Closer To ''You''(?近·?)''(클로저 투 ''유''(카오진·니))와 타이틀곡 ''Closer''(클로저)로 중국에서 컴백한다.', 'f80c3c61cda1279606bd3f57b82f1618b37de776e0949c8f377d1f394ebae7a9', true, false),
  (20, 'S3', 3, '이 그룹은 지난 8일 앨범 포스터와 콘셉트 필름 공개를 시작으로 컴백 준비를 시작했다.', 'b545ba2bb1efe62b9c9cfae01d0763b72a3fa380716302e694f8543a0b31c4f6', false, false),
  (20, 'S4', 4, '새 앨범은 ''너에게 가까워지는 과정'' 속 청춘의 다양한 감정을 하나의 이야기로 풀어냈다.', 'f9c2d9c1505c55099eec4d19791fff8ebc129d215f638f858e142b369087bc72', false, false),
  (20, 'S5', 5, '지난 14일에는 수록곡 ''一步一步(Step By Step)''(이부이부(스텝 바이 스텝)) 음원과 뮤직비디오를 선공개했다.', '1940ddea9fa12b6e81372c77ebb20ea832beb94383cdae100a00145c6b04dbad', true, false),
  (20, 'S6', 6, '뻔푸소년CIIU는 중국에서 유명 브랜드와의 잇단 협업과 대형 무대를 누비며 음악계 유망주로서 영향력을 넓히고 있다.', '56a0fdecfe8890aa3df2375cced5f4cf4d66c0ce93032c65955c33a0e3ec5a32', false, false),
  (20, 'S7', 7, '다음달 22일에는 중화권 대형 음악 시상식 ''2026 TIMA''(TMELive International Music Awards)에 출격한다.', 'a9e2fd879cd7d1b8d5b4a401f85f3175483f66fc3f8219b67a6faab4f6ae4461', false, false),
  (20, 'S8', 8, '지난해 ''2025 TIMA''를 통해 정식 데뷔를 알린지 약 1년 만이다.', '90c591403d719e01911c238885a9ba974c34a8a4e5f366aee59516c63b05a2b8', false, false),
  (20, 'S9', 9, 'JYP의 현지화 전략 ''글로벌라이제이션 바이 로컬라이제이션''(Globalization by Localization)의 일환으로 탄생한 뻔푸소년CIIU는 2025년 8월 데뷔 앨범 타이틀곡 ''출발의 여름''으로 중국 최대 음악 플랫폼 QQ 뮤직 일간 인기 차트, 일간 트렌딩 차트 톱 10에 오르기도 했다.', '3473b62553265e2477989486cb641e08db9f5a76da0099ccd9e29686a752a0b5', false, false),
  (20, 'S10', 10, '한편 JYP는 박진영 대표 프로듀서를 필두로 트와이스, 스트레이 키즈, 데이식스 등 글로벌 탑티어 아티스트를 보유한 종합 엔터테인먼트 기업이다.', 'e9f5b144d202ccf9ad11668e2a9b0ab87595a05bc578aef70903e288ff31d65a', false, false),
  (21, 'S1', 1, '하반기 빅뱅 투어·신인 데뷔도 [이데일리 윤기백 기자] 와이지엔터테인먼트(122870)는 7일 올해 2분기 연결 기준 매출 1277억 원, 영업이익 110억 원을 기록했다고 공시했다.', 'cfb1680751c795daf594a770adcb587c9cac5e4a4b5b02214a3c72ee00717734', true, true),
  (21, 'S2', 2, '지난해 같은 기간보다 매출은 27.2%, 영업이익은 31.2% 증가했다.', '9ad2d2805e770c0182e1a42b0c104bb5927a0f6c4c565f832912690808eda8ed', true, false),
  (21, 'S3', 3, 'YG 측은 베이비몬스터와 트레저의 신보 발매와 연계한 MD(굿즈) 판매 호조, 디지털 콘텐츠 수요 확대 등이 실적 개선을 이끌었다고 설명했다.', '660bc70b18ab2eb33ae4c831d8ad76a522b4f3e02e7526437fa1333934f0154a', true, false),
  (21, 'S4', 4, '하반기에는 소속 아티스트들의 활동이 본격화되며 성장세를 이어간다는 계획이다.', '5faf79361647b37551ea468974822e5b8b837a78346492acdf6dac847f8e9285', false, false),
  (21, 'S5', 5, '빅뱅은 8월부터 총 19개 도시, 33회 규모의 월드투어를 시작하며, 베이비몬스터는 서울 공연을 시작으로 라틴아메리카와 오세아니아, 유럽까지 무대를 넓혀 두 번째 월드투어를 진행 중이다.', 'e30a827656dddf6bea2d453137850e0e4c1ff4a7ae5ea425632b91674a9ac7c4', false, false),
  (21, 'S6', 6, '트레저 역시 다양한 활동을 이어갈 예정이다.', '44850908ca861f350a6177c5053f6874e2d3030db0d2a470736994f4b5a35725', false, false),
  (21, 'S7', 7, '여기에 오는 9월 신규 보이그룹 데뷔도 예고했다.', '23162859942523a96a35ceb618f0802802fb3814b7dfd5e2c3141c10255526a3', false, false),
  (21, 'S8', 8, 'YG는 기존 아티스트의 글로벌 활동과 함께 신인 지식재산권(IP)을 확보하며 중장기 성장 동력을 강화한다는 방침이다.', 'c393032370e645225688c2fece4853a1ae98e5c8df27ae7eaba6435792241708', false, false),
  (22, 'S1', 1, 'LS증권이 12일 2분기 역대 최대 실적을 기록한 코웨이에 대해 하반기에도 해외 법인 호조에 힘입어 실적 성장을 이어갈 것으로 전망했다.', '2fb6f0e93a398775093b754920c124ee10bc21c0912baa6e11ae8715952084b2', false, false),
  (22, 'S2', 2, '투자의견 ‘매수(BUY)’를 유지하고 목표 주가를 기존 11만원에서 12만원으로 상향했다.', '49f1f49773f1ef0e98afe6786ccb516a47e7fdda93772e519df168fb690b41aa', false, false),
  (22, 'S3', 3, '전 거래일 코웨이 종가는 9만7600원이다.', '868680cdce54c807fd272eef59934a46d410ee82bc516317f0469f0fa820ad02', false, false),
  (22, 'S4', 4, '앞서 코웨이는 올해 2분기 연결 매출액 1조4422억원, 영업이익 2532억원을 기록했다고 밝혔다.', '30a051addfac0adb61b89b3a2b93945a40c809c4539a001bedc8ccca87953ae4', true, true),
  (22, 'S5', 5, '매출과 영업이익 모두 분기 기준 역대 최대 규모다.', '02fffdb5f2468110dd15a9e3282066152120e0e03b2a88bf7bd0ff74faabfe81', true, false),
  (22, 'S6', 6, '다만 “포천맑은물 사업 중단 영향으로 영업이익률은 전년 동기보다 1.7%포인트(P) 하락한 17.6%를 기록했다”고 설명했다.', '2798cac636fc21359cddb2c8944882574ee41ba4f14eda9358bdd756d8f64196', true, false),
  (22, 'S7', 7, '국내 부문 매출액은 7.7% 증가한 7868억원을 기록했다.', '0ca430fb7b10be526614368835d66347b9926a83f954f38c762ef841917e8a6e', true, false),
  (22, 'S8', 8, '렌털 판매량이 3.1% 증가한 49만6000대로 나타났고, 정수기와 BEREX 판매 호조로 렌털 계정도 51.6% 증가한 24만2000계정이 됐다.', '70a0d3e77aec316e82b36ff79ee5485317ded7c9c8fb779c13011c9056446669', true, false),
  (22, 'S9', 9, '말레이시아 매출액은 주요 제품 판매 호조와 신규 카테고리 출시 효과로 22.2% 증가한 4345억원을 기록했다.', 'f7ac2d79c4d05503eaa0e428e13f416a9a0040c53cc90702b689d896d2f01965', true, false),
  (22, 'S10', 10, '태국 매출액은 영업조직 확대와 마케팅 효과로 53.9% 증가했으며, 미국도 방문판매와 시판 실적 개선 및 관세 환급 효과로 영업이익이 83.0% 늘었다.', 'e4f2b01316ad3784e36c00bd17425c65d63daac510cd276beca10578fb2bbf86', true, false),
  (23, 'S1', 1, 'SK그룹의 투자 지주회사인 SK스퀘어가 올해 2분기에 사상 최대 수준의 영업이익을 거둔 것으로 나타났다.', 'b54ea3d34348d618c36e517bdbddf6fe1a143cc9a2c7fb6c0050b02757ca9efd', false, false),
  (23, 'S2', 2, 'SK하이닉스의 이익이 급증하면서 지분 약 20%를 보유한 최대 주주인 SK스퀘어 역시 실적이 큰 폭으로 개선된 것이다.', 'd6d1312ea0dceab55f6cd51660a10fefcefbad052520183a8c63d0ebf85fff27', true, false),
  (23, 'S3', 3, '14일 금융감독원에 따르면 SK스퀘어는 2분기 연결 기준 영업이익이 전년 동기 대비 1273.8% 급증한 19조2354억원을 기록했다.', 'fc0b2ac44519c335ab841cdc449c39cde904a21f2b9503e907a9091cf0b4086e', true, true),
  (23, 'S4', 4, '당기순이익도 1190.5% 늘어난 18조6750억원에 달했다.', 'a0e8675fe8110c87596a6b00592e392f0e49389edff9c8e5fb54955c60c4d34c', true, false),
  (23, 'S5', 5, '상반기 누적 영업이익은 27조5137억원, 누적 순이익은 27조498억원으로 각각 집계됐다.', '6bec85596a165856b9a8651b824697232279db2f2af90e36a295055db8411ffb', true, false),
  (23, 'S6', 6, 'SK스퀘어는 이 같은 실적 개선이 SK하이닉스의 실적 호조와 함께 인공지능(AI), 반도체 포트폴리오에 집중하고 꾸준히 주주 환원을 이어온 결과라고 설명했다.', '0f9183d81245ece76e1d1dce7c7943ac10a8d2936eda435f9e39548c01a54716', true, false),
  (23, 'S7', 7, 'SK스퀘어는 AI와 반도체 업종 투자에 집중하기 위해 지난 1월 디지털 광고 회사 인크로스를 SK네트웍스에 매각했다.', 'd17f5c30ed0607e0e3cd75b40fcd4e7d3efbd5a6d3bac4a6ac84feb21883bc03', false, false),
  (23, 'S8', 8, '올해 상반기에 취득한 자사주 400억원을 지난달 모두 소각한 데 이어, 내년 초까지 700억원의 자사주를 추가로 매입해 소각할 예정이다.', 'da15496892fe2447c887210cb352da386a7f148e7755691d927f1d2e16306c50', false, false),
  (23, 'S9', 9, 'SK스퀘어는 AI와 반도체 중심의 신규 투자를 이어가면서 AI 전환(AX)에도 속도를 낼 계획이라고 밝혔다.', '320d2c379130c4acc43b17efd58e5435841650ee5bccaccaf457f524370cab6c', false, false),
  (23, 'S10', 10, '김정규 SK스퀘어 사장은 “기업가치 제고를 위해 주주와 적극 소통하고 AX와 반도체 신규 투자를 준비해 나가겠다”고 말했다.', 'c7a2f6fe2c283c409caf12d8ac49f9efecdaa633eedf0c75657231c708515d0e', false, false),
  (24, 'S1', 1, '현대차 노조, 사측 교섭 재개 요청에 18일 파업 유보', '9360638b9b5a61aca08f33e61eed4c83ee284efc1a26071902f574e5578bb8dd', false, false),
  (24, 'S2', 2, '신차 효과 앞두고 노사 갈등 봉합 여부 주목 현대자동차 노사가 한 달여 만에 다시 협상 테이블에 앉는다.', '508b0bdb8e45e5e44ad78569e7c83218b33d5469b48dc1864963e36c2d21c8a7', false, false),
  (24, 'S3', 3, '여름휴가 이후 파업 수위를 높이던 현대자동차 노동조합이 사측의 교섭 재개 요청을 받아들이면서 오는 18일 오후 2시 본교섭을 재개하기로 했다.', '85f2f49646b1687568e6b8ddf480bfc6951bf7d77741ce8fbc6a88b4a6cf1de8', true, true),
  (24, 'S4', 4, '특히 올해 파업으로 이미 4만대가 넘는 생산 차질이 발생한 데다 하반기 신차 출시를 통한 실적 반등이 필요한 상황인 만큼 18일 교섭 결과가 현대차의 하반기 경영 성적을 좌우할 주요 분수령이 될 전망이다.', '4c32c36606f4244ebe31dc9f549207b31c3941567c7db9cdcec113b119ade0f4', true, false),
  (24, 'S5', 5, '12일 울산시 북구 현대자동차 울산공장 명촌정문에서 오전조 근무자들이 4시간 부분파업으로 일찍 퇴근하고 있다.', '2070a6ee42f41d5c6f8c2658f3e7094dd8e828dbbedc9377df4522b4d9373fa9', false, false),
  (24, 'S6', 6, '현대차 노조는 이날부터 18일까지 매일 4∼6시간 파업을 이어간다.', '9517ac4cb9f36cc429ef6fa6aae004702462da7c4cff821dcfe5b6a64381bd0e', true, false),
  (24, 'S7', 7, '현대차 노조는 지난달 13~15일 근무조별 매일 2시간씩 부분파업을 벌인 데 이어 20~22일과 29~31일에도 매일 4시간씩 파업했다.', 'be9c8b1cf3a7f9763afb0216c237a8aa2e91404188e3e60d9b74a1b3fe7609b3', false, false),
  (24, 'S8', 8, '현대차 입장에서는 하반기 실적 반등을 위해 생산 정상화가 어느 때보다 중요한 시점이다.', '602ecb3532c6d11bc150f5cc3343960c7b6bb78580df14f32f9662a942259cc1', false, false),
  (24, 'S9', 9, '상반기 부진을 만회하기 위해 하반기 신차 효과와 판매 확대에 기대를 걸고 있지만, 파업이 장기화하면 신차를 생산하고 적기에 공급하는 데 차질이 생길 수밖에 없다.', '796107f0c2aeda5b5445880879786e1ce23341570774231e425dae7276546fd8', false, false),
  (24, 'S10', 10, '현대차가 제시한 기본급 8만9000원과 성과금 350%+1000만원, 자사주 15주보다 높은 수준이다.', 'faaee4c11763e5f19d413f9e91d0ace6291fbbf2377ffc44252fb89b41280515', false, false),
  (25, 'S1', 1, '호텔롯데, 부산롯데호텔 보유 지분 61.17% 매각', '563059f081c0fdd4b1795bd60cdd74b6138bcfcf8228f0067ba7baddfe072d68', false, false),
  (25, 'S2', 2, '국내 렌터카 업체 1위 롯데렌탈이 미국계 사모펀드(PEF) 텍사스퍼시픽그룹(TPG) 품에 안겼다.', 'bccf0be11023aada384d894333550361c4878dd22c8cb92a123b902ce35f0899', true, false),
  (25, 'S3', 3, '[더팩트ㅣ장혜승 기자] 국내 렌터카 시장 점유율 1위 업체 롯데렌탈이 미국계 사모펀드(PEF) 텍사스퍼시픽그룹(TPG)에 매각됐다.', '6f4dae6add5a64028042eb4a171257e2a5d870569b543e2d41e297cce0cd4dff', false, false),
  (25, 'S4', 4, '15일 투자은행(IB) 업계에 따르면 롯데렌탈은 최근 호텔롯데와 부산롯데호텔이 보유 중인 롯데렌탈 지분 61.17%를 TPG에 매각했다.', 'c1683a61dbb05b5a33bc84b3e0031d59d2444fce1825c70072e831d424d96d90', true, true),
  (25, 'S5', 5, 'TPG는 롯데렌탈 인수 대금을 전액 자체 펀드를 통해 조달할 것으로 알려졌다.', '286287032b340aead83ce907c96e6a62385441a6a62961e4f06164e73d34e297', true, false),
  (25, 'S6', 6, '1989년 금호아시아나그룹 내 ''금호렌터카''로 출발한 롯데렌탈은 2010년 KT로 주인이 바뀌었고 2015년 또 한번 롯데그룹에 매각됐다.', 'c774a90c444103543cf91283aa7bc52981ebd8734d2b721034395d2e191957d6', false, false),
  (25, 'S7', 7, '롯데렌탈은 지난해 사모펀드인 어피니티에쿼티파트너스가 인수를 시도했으나 공정거래위원회가 올해 1월 독과점 우려를 들어 기업결합을 불허하면서 작업이 무산됐다.', '6af1913e1b7f857d5ed72e7fb204b25926fd2d451c319c0c8740484f66cfa77b', false, false),
  (25, 'S8', 8, '이후 한국앤컴퍼니도 롯데렌탈 인수에 관심을 보였으나 최종적으로는 TPG가 롯데렌탈을 품게 됐다.', '6cda611ebc237af8c56593758d0a9a0db1119bb165a386beeb2240448a273fcb', false, false),
  (25, 'S9', 9, '앞서 증권가에서는 TPG의 인수가 롯데렌탈 재평가로 이어질 수 있다는 분석이 나왔다.', '853c4e3f561b314e2a93e3855e6946e3b2c831768186702e2e5c4882678d9c1a', false, false),
  (25, 'S10', 10, '지난해 매출 약 1100억원, 상각전영업이익(EBITDA)은 240억원을 기록했다.', '2422a7db48490832e38a76fd614f9b55b26ce7f485cc296fafe93d02a5a8e535', false, false),
  (26, 'S1', 1, '노조 8월 25~27일 파업 찬반 투표 예정 "조선업 호황…기본급 상여금 대폭 인상을"', '51bf5c8460ba50e4ef2913c3986e9a316b9d51e157e968df477aecc26df3cb13', false, false),
  (26, 'S2', 2, 'HD현대중공업 노동조합이 올해 임금·단체협약 교섭 난항으로 파업 준비 수순에 들어갔다.', 'dcc202185040e9d464fd996e2419e6969882b03678c6abcdf3a333481cfb9c57', true, false),
  (26, 'S3', 3, '금속노조 현대중공업지부(이하 노조)는 14일 중앙노동위원회에 노동 쟁의 조정을 신청했다.', '36acfa540dd5443f119db05928c0ae4912b122ffbb0a8323c0d0d07ca2f68977', true, true),
  (26, 'S4', 4, '중앙노동위원회가 노사 입장 차가 크다고 판단해 ''조정 중지'' 결정을 내리고, 파업 찬반 투표에서 과반 찬성이 나오면 노조는 합법적인 파업권을 확보하게 된다.', '2813149929836ce00feee13ee8a0dc409072b8d454aa09cb40913d693d5a62fb', true, false),
  (26, 'S5', 5, '노조는 25일부터 27일까지 조합원을 대상으로 파업 찬반 투표를 진행할 예정이다.', 'd951a3ce4567b99fd7806ba3d459994e0dfa8da6400769d2b9418767b3dce0f7', true, false),
  (26, 'S6', 6, '앞서 HD현대중공업 노사는 6월 상견례 이후 15차례 교섭을 진행했으나 이견을 좁히지 못했다.', '011b531da25f9ac6829b1b726101eadb15a02be7056641a60577d1d8ba7efc30', true, false),
  (26, 'S7', 7, '월 기본급 14만 9600원 인상과 상여금 100% 인상을 요구안으로 제시했다.', '28959259eed80aa5da372e8fc2e39c488fd596d106f27209230303ab93bc7c91', true, false),
  (26, 'S8', 8, '또 영업이익의 30% 성과 공유와 휴가비 등을 통상임금 산입도 요구하고 있다.', 'be99ac1fef2b3dd6692472d03a03da65a820c4cfa4d0a61668bac2d1849c2b4a', true, false),
  (26, 'S9', 9, '각종 비리와 부당대우, 사건사고와 미담 등 모든 얘깃거리를 알려주세요.', '3be285ac4fe95202832d734b594fbded3b8808d5c2b5142dc5456282f43cf9b0', false, false),
  (26, 'S10', 10, '사이트 : https://url.kr/b71afn', '55e76e8a534c4081371586b203bcd33f0538535e8be9cd98889f3c44b4c31703', false, false),
  (27, 'S1', 1, '트럼프, 해군·조선 재건 각서 서명', '3f61c8004b3e0bbd72636df6db57fcc96ce859a878afef467357d23f34669a10', false, false),
  (27, 'S2', 2, '수상전투함·유조선·로로선 등 제한', '9dfb29642042b5e24d18d1900cb1210139e803bd39986c1507e5d63a2dcb4d8e', false, false),
  (27, 'S3', 3, '신규 조선소도 건설, 韓 수혜 기대', '1afc65d05a0d10b502a863c0ec2d7c09cb67e6c2a1112e632cc2ce6e44a17722', false, false),
  (27, 'S4', 4, '이태규 특파원 도널드 트럼프 미국 대통령이 외국 조선소에서 군함을 2척까지 건조하는 방안을 조건부로 허용했다.', 'fb3f707274f9c5ee9a018ce3fed48692d8fef006fcfe49ac92226ce33a271252', true, false),
  (27, 'S5', 5, '한화오션의 거제 조선소에서 미국 군함을 건조할 수 있는 길이 열릴 수 있다는 기대와 함께 의회가 변수가 될 수 있다는 신중론도 나온다.', '704672069b32aeffd946a034cd48c56d2a7726f03cb5e93fa43ee65b277487bb', false, false),
  (27, 'S6', 6, '트럼프 대통령은 13일(현지 시간) ‘미 해군과 조선산업 기반 재건’이라는 각서에 서명하고 “미국에 조선소를 건설하거나 기존 조선소의 소유권 또는 과반 지분을 확보한 외국 조선업체가 대상”이라고 밝혔다.', '9f673b1f996538420ad9c3d9e80039707711870490838be9c42039d61c6efdfa', true, true),
  (27, 'S7', 7, '미국 필라델피아 필리조선소를 인수한 한화가 이 조건에 부합한다.', 'cde5c5c6b1d7046facce11f585669d3f8bf99d2c7470da3769cc83387e28d607', true, false),
  (27, 'S8', 8, '한화오션과 한화시스템 컨소시엄은 2024년 지분 100%를 인수했다.', 'c7fbee39ac74807bb6b68c7d17184b627d09ee3264d66b5304887e76e30f09e6', true, false),
  (27, 'S9', 9, '또 최초 2척 이후 미국 조선소에서 이뤄지는 모든 선박의 건조와 유지·보수에 미국 내 공급망을 활용해야 한다는 조건도 달았다.', '9b1291917e82b416f3e50e2ab80c9bb851cec9c276435f06e3325d77524b6bb0', true, false),
  (27, 'S10', 10, '향후 행정부와 상하원 간 의견 조율이 우리 업체의 최종 계약에 변수가 될 것으로 보인다.', '8172af24da7f003eb7f84e5ae7091a3cf892def22cb5ebe7cb33d28e0e686229', false, false),
  (28, 'S1', 1, '양사 이사회 및 주총서 합병안 최종 가결…5년9개월 절차 마무리', 'e135d2d74c7d59fe46a51b590d0e188d8c7a8e22c0014ec69f67335fce6f042d', false, false),
  (28, 'S2', 2, '매출 23조원·항공기 230대…여객 15위·화물 5위 재탄생', 'e639bb61d7fa4bba158228a6a51cfebe4beafc14d90def2db321e3dfa3bc1d27', false, false),
  (28, 'S3', 3, '[서울=뉴시스]남주현 기자 = 조원태 한진그룹 회장이 추진해 온 대한항공과 아시아나항공의 인수·합병(M&A) 절차가 이사회 및 주주총회를 통과하며 막바지 단계에 진입했다.', 'b1d7b107acfd40a8575770a4b61cbcbb1a6f9e8aedc2ff57e2981a158c94bc94', false, false),
  (28, 'S4', 4, '두 회사는 남은 행정 절차를 거쳐 오는 12월 17일 통합 법인을 공식 출범해 2020년 11월 인수 결정 발표 이후 5년 9개월 만에 합병 절차를 마무리 지을 예정이다.', 'e7d060adb04b8c0c32f2e81b4276e46882d6ceca0ca6a83a5797fed0d5e1ea45', true, false),
  (28, 'S5', 5, '15일 항공업계에 따르면 대한항공과 아시아나항공은 연말까지 합병 등기 등 남은 절차를 차질 없이 완료할 계획이다.', 'c4833ff61bbfb16c678c001f4fd14fe7751cc32a7ed9ece351f254f63c5cd3f3', false, false),
  (28, 'S6', 6, '존속법인인 대한항공은 서울 중구 서소문 빌딩에서 정기 이사회를 열고 ''합병 승인의 건''을 가결했다.', '9f2210b8b5138353ed667c518efa525a2089ea4ab8bf30a706ddee762191d6f7', true, true),
  (28, 'S7', 7, '아시아나항공도 서울 강서구 본사에서 임시 주주총회를 열고 지난 5월 대한항공과 체결한 ''합병계약 체결 승인의 건''을 통과시켰다.', 'a6956e677222a4927a6a9b30912bc2c219843a36cbeb600b8ba200cbcef0a3da', true, false),
  (28, 'S8', 8, '새로 출범하는 통합 대한항공은 연 매출 23조 원 이상, 보유 항공기 230여 대, 임직원 2만8000명 규모를 갖추게 된다.', '2c6ce4a2a40665c0be3fceae4491d762f6dc12d68b8133f563a0920591789ed7', true, false),
  (28, 'S9', 9, '[인천공항=뉴시스] 박주성 기자 = 아시아나항공이 임시주주총회를 열고 대한항공과 합병 체결을 가결한 12일 인천국제공항 제2여객터미널 활주로에 대한항공과 아시아나 항공기가 이동하고 있다.', '2f59d53c4453b04228fe1d6804581eb5fe20adc5c3415f931549deb3f5fabbd6', false, false),
  (28, 'S10', 10, '특히 대한항공과 델타항공이 맺은 조인트벤처(JV) 판매망에 아시아나항공 노선을 편입해 미주 노선 경쟁력을 높일 계획이다.', 'd35d24b3ed51a6fbfe7dc1dc74426389115ec2ba5154a2ea01f972c4dfb95619', true, false),
  (29, 'S1', 1, '한진칼, 특수관계자 지분 0.01%p 확대', '1f19a69a1adb17a9f013b44cfde40ad3a4d86040ed624864d0700ef67a7bd290', false, false),
  (29, 'S2', 2, '공익법인은 주식 사고 이명희 고문은 팔고', 'cd82a094bc38dc9782bebf5234e8612abe779b0c71cc6419d2277e797714b874', false, false),
  (29, 'S3', 3, '이명희, 지분 1.83%...5년간 1088억 매각 한진그룹 공익법인이 예고한 대로 지주사 한진칼 지분을 사들였다.', '9b9ba6e6402a07c452226d08916f390ef5680e79ac38ff3ff30310266f05d1b9', true, false),
  (29, 'S4', 4, '조원태 한진칼 회장(사진)의 모친 이명희 정석기업 고문이 일부 지분을 매각하면서다.', '822db18bf250d2adea8e1b8f14eac8b5448e7bca1fd166e8073475880dc41975', true, false),
  (29, 'S5', 5, '호반그룹이 한진칼 지분을 사들이며 한진칼 경영진을 압박하는 가운데 한진칼의 소규모 지분변동도 민감해지는 분위기다.', 'c0b4de6bfc8596000e474454312abb05d3e4ec4625efd8fddeb5407d921e9def', false, false),
  (29, 'S6', 6, '한진칼은 지난 11일 조 회장 등 특수관계자 지분이 기존 31.15%(2079만6274주)로 기존보다 6280주(0.01%) 늘었다고 공시했다.', '3756e85abd43a5adfe044f5f87f627bfbb6e029c2412eb28a089f338063b6071', true, true),
  (29, 'S7', 7, '이 공익법인은 지난 6~7월 ''올 연말까지 한진칼 지분을 취득하겠다''고 공시했고, 이번에 예고대로 한진칼 지분 매입에 나선 것이다.', '24fab50e0f7b3f0e155120969b25196813a4703dae086b27f2d33c1036e5ccae', false, false),
  (29, 'S8', 8, '1023억원 규모 한진칼 지분을 취득하겠다고 밝힌 정석물류학술재단은 연말까지 추가로 930억원 규모 지분 매입에 나설 것으로 보인다.', '00c31d0cd3318b66e6f2bb5edae2ee40b7e77f7019f80bf653d5ce539dd9efaa', false, false),
  (29, 'S9', 9, '지난달 기준 호반그룹은 한진칼 지분 20.15%를 보유하고 있다.', '1b24a2d195567fcad9f4fbf3713eeb7f1d8704938ea86048fc999276f2883251', true, false),
  (29, 'S10', 10, '한진칼 지분 보유 현황을 보면 △호반건설 11.5% △호반호텔앤리조트 8.34% △호반산업 0.17% △호반 0.15% 등으로 2022년부터 한진칼 주식 매입에 총 8782억원을 투입했다.', '452461b8f7512066fcacbc557f983cabc092f6b3b559725777f4b7a3a2dc5bff', false, false),
  (30, 'S1', 1, '한국콜마·코스맥스·코스메카코리아 매출 사상 최대', 'b4a46da43c5f584216691fa0096edb41eb56e2acd47b3885efee89369a729e06', false, false),
  (30, 'S2', 2, '에이피알·달바글로벌·애경산업 등도 합류해', '1a58540459f0174204afe5e602e9426769a9cc0e35d09e3a46f325ecd9af690c', false, false),
  (30, 'S3', 3, '수출 지역 다변화에 하반기에도 호실적 기대', '240672db48c3bb3a9575851f3a8a97d3683c40af60eb4ee42db1a7cee728461f', false, false),
  (30, 'S4', 4, '사진제공=에이피알 K뷰티의 인기가 글로벌 시장으로 빠르게 확산되면서 국내 화장품 브랜드사에서부터 제조업자개발생산(ODM) 업체까지 모두 잇달아 최대 실적을 경신했다.', '31c2354a820d1b193d201a1d0cb825f95cf532ed27ceee9cd9bdc49470939705', false, false),
  (30, 'S5', 5, '코스맥스의 2분기 매출액과 영업이익은 각각 7949억 원과 737억 원으로 전년 동기 대비 27.5%, 21.2%의 증가율을 보였다.', '48c87efd9cf6278ecee91dd1e1e67cae0863225fcf6a5315b921177409c73aab', false, false),
  (30, 'S6', 6, '특히 한국법인의 매출액은 전년 동기 대비 23% 증가한 5184억 원을 기록하며 분기 기준 처음으로 5000억 원을 넘어섰고, 부진했던 미국 법인은 창사 이래 처음으로 흑자 전환에 성공했다.', '14cee8226757b3435fe7205e717ad0deb4b19087ce09cd23ae6cdca3f7dd2b73', false, false),
  (30, 'S7', 7, '코스메카코리아도 매출액 2261억 원(+39.8%)과 영업이익 321억 원(+39.3%)을 기록하며 분기 기준 역대 최대 실적을 기록했다.', '7401a98facf1ae96d75345658bcaee991b94638a8911a50cfc09a9ba40d48759', false, false),
  (30, 'S8', 8, '대표적으로 에이피알은 북미와 유럽 시장에서 가파르게 성장하며 분기 기준 역대 최대인 매출액 7675억 원(+ 134.2%)과 영업이익 1906억 원(+134.5%)을 기록했다.', 'cc568f0945b42b1f527e51c5b34eb6634474bfeca49171c91b85824ee4687877', true, true),
  (30, 'S9', 9, '이로써 에이피알이 거둔 올 상반기 매출액은 1조 3609억 원으로, 지난해 연간 매출액(1조 5273억 원)에 맞먹는다.', 'fb47da5f88eca55db33b732b8ec9c6b5058720a6f2ab98ea94d9487919e6bd2c', true, false),
  (30, 'S10', 10, '달바글로벌 역시 올 2분기 매출액 1869억 원(+46%)과 영업이익 472억 원(+62%)을 기록하며 분기 기준 역대 최대 실적 행렬에 합류했다.', '5dd5be0213b0f76b1535e0245d1c03631865dcbda3c66176d5ccc700195e7e75', true, false),
  (31, 'S1', 1, '매출도 1869억으로 최대…북미·유럽 판매 확대', 'f3ebcc49223add1b34f66e701c75901036bc6d21eb58cec6e448b750d3eae721', false, false),
  (31, 'S2', 2, '달바글로벌 제품 (달바글로벌 제공)', '7324a65cad9b01afbe4f981f7b7fef8dd6b6baf3bde959401b245cb6b7b06b35', false, false),
  (31, 'S3', 3, '(서울=뉴스1) 정윤영 기자 = 달바글로벌이 해외 화장품 판매 확대에 힘입어 올해 2분기 역대 최대 분기 매출과 영업이익을 기록했다.', '8fb60d6dfd71a03f02aea5c50a389ae2ac194a88aea7bcb185b385e831fe1c11', true, false),
  (31, 'S4', 4, '13일 달바글로벌은 금융감독원 전자공시시스템(DART)을 통해 올해 2분기 연결 기준 영업이익이 472억 4100만원으로 전년 동기 대비 61.6% 증가했다고 공시했다.', '068b0d8dde82da32bc0bc9a05cc16042470822d1c60ff70f08cda8c06702c340', true, true),
  (31, 'S5', 5, '같은 기간 매출은 1868억 6100만 원으로 45.6% 늘었으며 당기순이익은 380억 6000만 원으로 92.2% 증가했다.', '20b84f5e15ddb7e3a7d69542c4adcae32498e956b6da74a2c78831b6c02a7bd1', true, false),
  (31, 'S6', 6, '직전 분기와 비교하면 매출은 9.1%, 영업이익은 4.8%, 당기순이익은 4.7% 각각 늘었다.', 'c4b8a62212825b1a78476db20784ea1c8e39bb6a25eaa5649887fadbe3075c83', false, false),
  (31, 'S7', 7, '2분기 영업이익률은 25.3%로 전년 동기보다 2.5%포인트(p) 상승했다.', '9b9938bfbbee2583c232663408b019adab09fee6518fbe9f0a46fb7a4f3421be', false, false),
  (31, 'S8', 8, '영업이익은 923억 3100만 원으로 55.8%, 당기순이익은 743억 9700만 원으로 67.0% 각각 늘었다.', '58a38c8f8d111761a95cad10b1b1602b0296ffac14f454517157de807ec182bc', false, false),
  (31, 'S9', 9, '달바글로벌이 이날 공개한 실적 자료에 따르면 2분기 해외 매출은 1415억 원으로 전년 동기보다 74% 증가했다.', '8b7ac54a5f1512d587476a01aa349546c5bf8ee11f01c9c34f4c950d35d86513', true, false),
  (31, 'S10', 10, '달바글로벌은 화이트 트러플을 핵심 원료로 사용하는 프리미엄 비건 스킨케어 브랜드 ''달바''를 운영하는 화장품 기업이다.', 'dcac9527135f4d2f4c1757f5e280ea619d9097eb9b4b3d9c352ee3e1e9264b1b', true, false),
  (32, 'S1', 1, '중국과 면세점 부진에 짓눌려 ‘만년 저평가주’ 취급을 받던 LG생활건강이다.', '598e78be98dbbe69e6c46f5a964a3c980fa052b604f559cb5f5aaf13b4ae184d', false, false),
  (32, 'S2', 2, '2분기 실적 발표 직후인 7월 30일 하루에만 주가가 11% 급등했고, 8월 초에도 15% 넘게 뛰며 코스피 대형주 가운데 가장 높은 상승률을 기록했다.', '0767bba5d7e4d3f7853211d70f12470051e85232c6e53f487ff02679b11bbab9', false, false),
  (32, 'S3', 3, '그는 LG생활건강 영업이익이 올해 3940억원으로 전년보다 130% 늘고, 내년에는 6230억원까지 불어날 것으로 내다봤다.', '17ca7628969f41fad6b97b551025ae3852830b10c3e0039a740c0ba31955ca02', false, false),
  (32, 'S4', 4, '2005년부터 17년간 회사를 이끈 차석용 전 부회장은 코카콜라음료, 더페이스샵, 해태음료, 피지오겔 등 20건 넘는 인수합병(M&A)을 성사시키며 매 분기 사상 최대 실적을 갈아치웠다.', '3bfc8ce55bfa58eeb8dc9653655be1e709d9ebed508b03b164389da82b2231ad', false, false),
  (32, 'S5', 5, '‘두피도 피부처럼 관리한다’는 스키니피케이션 트렌드에 올라타 아마존 프라임데이에서 전년 대비 46% 매출 성장을 기록했고, 8월부터 미국 세포라 400여개 매장으로 판매를 확대한다.', '28534f591bb6519f63156df10d886bd0bf44db3aeb5b7e2b76ed2e594e45031a', false, false),
  (32, 'S6', 6, '2분기 연결 매출 1조6574억원(3.3% 증가), 영업이익 1028억원(87.5% 증가)으로 시장 전망치를 37% 웃돌았다.', '9e403d1d7020c1673d075ba0512554c1784edcb25d4a4a15c71cee7f067d29a2', true, true),
  (32, 'S7', 7, '화장품·생활용품·음료 전 사업부문 매출이 성장세로 돌아선 가운데, 적자에 시달리던 화장품 부문이 영업이익 444억원으로 흑자전환했다.', 'ce032132baeab403a707f980534f1486be10390625549c5b19765aa5f3943277', true, false),
  (32, 'S8', 8, '마케팅비를 늘리고도 북미 법인이 분기 흑자를 냈고, 북미 매출에서 자체 브랜드 비중은 50%까지 높아졌다.', '2a4a9da8fbccc5b34071596de514319204f87203510ca1594c9a55ba367d471b', true, false),
  (32, 'S9', 9, '박현진 애널리스트는 “일회성 수익인 미국 관세 환급 150억원을 제거하고 봐도 호실적”이라며 2026년 순이익 추정치를 20% 상향했다.', 'b7954918445efa22f35b992368d3079ec40ba9df6018b4587999b638dedce29d', false, false),
  (32, 'S10', 10, '폭락장에서 실적의 힘으로 역주행한 LG생활건강이 단기 반등을 넘어 본격적인 재평가로 나아갈지, 하반기 북미 사업 성과가 시금석이다.', 'e72f60f18d63a24002e3ca0a7853c60f0286c07277e52ffa30cfe71fa3fbc279', false, false),
  (34, 'S1', 1, '크래프톤이 2026년 상반기 연결 기준 매출 2조 6616억 원, 영업이익 9725억 원을 기록하며 반기 기준 역대 최대 실적을 작성했다.', '06aa2db5f641ef2ac4201c90a24c7546363762bf142f9e8197624c03b99ba133', true, false),
  (34, 'S2', 2, '전년 동기 대비 매출은 73.3%, 영업이익은 38.3% 증가했다.', '5403517f08ae682c81ef1787456cb87b66c4505241a9afd7930ad546343741e9', true, false),
  (34, 'S3', 3, '2분기 매출과 영업이익도 각각 1조 2902억 원과 4109억 원을 거두며 역대 2분기 중 최고치를 기록했다.', '47e55fe2bd4600d918af90b54f380ded21bbe08e0470fe1e4ed4dd58b9d4fa3b', true, true),
  (34, 'S4', 4, 'PUBG IP 상반기 매출은 전년 대비 25% 늘어났으며, 지난 5월 얼리 액세스로 선보인 서브노티카 2는 출시 22일 만에 누적 판매량 500만 장을 넘어섰다.', 'e11d3602f7ccc582ee0c5bf5c9e68f538c61379a3f67fb8788b249af8be0d6ec', true, false),
  (34, 'S5', 5, '플랫폼별 상반기 매출은 모바일 1조 1,537억 원, PC 9,242억 원, 기타 5,460억 원, 콘솔 377억 원 순으로 집계됐다.', '4f7bc405d7ff754a48cb09a8d31365c36158832bfa968b092a95058e94c3816b', true, false),
  (35, 'S1', 1, '넷마블은 2026년 2분기 연결기준 매출 7492억원, 영업이익 801억원을 기록했다고 5일 밝혔다.', 'fb2cb2b6379df9871213e9e962cc86af97cb0b1186a80c96956210ee6a019b16', true, true),
  (35, 'S2', 2, '전년 동기 대비 매출은 4.4% 늘었으나 영업이익은 20.8% 감소했다.', '4061b6608195e38dad7a5b38845baf7db45911c1411442595c660f6ddbc98649', true, false),
  (35, 'S3', 3, '전 분기와 비교하면 매출은 15.0%, 영업이익은 50.8% 상승하며 완연한 실적 개선을 이뤄냈다.', '64719bd5c60839b80496ffcb1b04db28a134a1e4cbf45283e2682a964bde0411', true, false),
  (35, 'S4', 4, '상각전 영업이익(EBITDA)은 1120억원, 당기순이익은 2039억원으로 집계됐다.', '11952839262f32a6748807ef8965ef44a006597ce464bb8be60a8a387e8b1c0f', true, false),
  (35, 'S5', 5, '이에 따른 올해 상반기 누적 매출은 1조 4009억원, 누적 영업이익은 1332억원이다.', '43700c80a047be81fbdfd581643de9ecdb8026a887690bb30f30916ff167411f', true, false),
  (35, 'S6', 6, '2분기 해외 매출은 5808억원으로 전체 매출의 78%를 차지하며 전 분기 대비 13.4% 상승했다.', '4a05eacfaf904249344c2afdafd53a76c9fb9a577ee596a5d8b6d6866ec6e8de', true, false),
  (36, 'S1', 1, '올해 2분기 연결 기준 매출은 3조3800억원으로 전년 동기 대비 10.9% 증가했다.', 'ba582dec3bb3b80c97cd0ed08b99a24afc374726bff54cbead04c857ce677374', true, true),
  (36, 'S2', 2, '영업이익은 1016억원으로 같은 기간 11.9% 감소했다.', '360a4182d2aabb9e60f02adb2d875665cf59d396a83d15ecc5c55d76179702b0', true, false),
  (36, 'S3', 3, '영업이익률은 지난해 2분기 3.8%에서 올해 2분기 3%로 0.8%포인트 하락했다.', 'b86e34fdf53d42fdf4fc482fbb1841063053e4e5b756235aeb6a66927a4c6f90', true, false),
  (36, 'S4', 4, '2분기 순이익은 368억원으로 전년 동기보다 36.8% 줄었다.', '58e01eaf124feadc39f2e16dc92b349fe26fc258a233e0c0713db68d188a5ec2', true, false),
  (36, 'S5', 5, '오네부문의 2분기 매출은 9848억원으로 전년 동기 대비 8.5% 증가했지만 영업이익은 409억원으로 10.7% 감소했다.', '09bc857e558024f1b7684d07dada79f09d915c11c6e195b364743bc0ce588561', true, false),
  (36, 'S6', 6, 'CL부문의 2분기 매출은 9001억원으로 전년 동기 대비 8% 증가했다.', '136fcbd310a048ca28a62bee2123bf585f5810b18063d7d3592515ec1d31e8e4', true, false),
  (36, 'S7', 7, '건설부문의 2분기 매출은 2891억원으로 전년 동기 대비 41.2% 증가했으나 영업이익은 5억원에 그치며 86.8% 급감했다.', 'b9bfd315601564297ac7f7052dfd88a2ac642607eece9f338c8a8c451fc0592d', true, false),
  (37, 'S1', 1, '현대글로비스는 최대 1만800대의 소형차를 수송할 수 있는 초대형 자동차 운반선 ''글로비스 리더(Glovis Leader)호''를 글로벌 오션 노선에 본격 투입하고 명명식을 거쳐 상업 운항을 개시했다.', 'bdcf0f27b1cb79a36433f458580ddead09fee5885496eb0c5e1096e2c27712c0', true, true),
  (37, 'S2', 2, '선체 길이 230m, 너비 40m, 총톤수 10만2590톤에 달하며 내부에는 총 14개 층의 차량 적재 데크를 갖추고 있다.', 'ad44ff93e2848b758ccb212af93e93d00ac865ca4aec540da39e297b1c136ba2', true, false),
  (37, 'S3', 3, '기존 세계 기록이었던 노르웨이 회그 오토라이너스(Höegh Autoliners)사 ''회그 오로라호''의 수송 용량(9100대)을 약 19% 이상 전격 경신 한 수치다.', '592b05e0d46411d7f91da1a315f7327141e2bdc0db569008ff6f163da315c0c9', true, false),
  (37, 'S4', 4, '글로비스 리더호는 세계적인 국영 조선 그룹인 중국선박집단(CSSC) 산하 ''광저우 조선소(Guangzhou Shipyard International·GSI)''가 건조를 맡았다.', 'fac2edbc5ba67e7c1162b4b5e2e4ab972f893a65e0123ac2c575b040a8049379', true, false),
  (37, 'S5', 5, '이 선박의 핵심 심장부는 액화천연가스(LNG)와 기존 선박유를 모두 사용할 수 있는 친환경 이중연료(Dual-Fuel) 추진 엔진 이다.', '17f47e5bc7392bd9e30505398198ac4fda1d3424997599f6df4f8dec733c2713', true, false),
  (37, 'S6', 6, '현대글로비스는 이번 호를 시작으로 오는 2027년까지 동급의 자매선들을 순차적으로 추가 투입해, 2030년까지 총 128척의 대규모 카캐리어 선단을 구축하겠다는 공격적인 로드맵을 확정했다.', '65cacbd00ec5c4d6fe419426966107e6126e60842df50cc661c0bc2a207cd6ba', true, false),
  (38, 'S1', 1, '삼성전자가 연결기준으로 매출 171조원, 영업이익 89.4조원의 2026년 2분기 잠정 실적을 발표했다.', '10aa2b34fa30284574fa0a390804e5182727d4772498e213360df4c43c53c07f', true, true),
  (38, 'S2', 2, '2분기 실적의 경우 전기 대비 매출은 27.74%, 영업이익은 56.21% 증가했고, 전년 동기 대비 매출은 129.31%, 영업이익은 1810.26% 증가했다.', '9101ff6532c21ed68bf7c8f07e6b8f38d6baa4450a6fa2c6c3293c2b6206f62e', true, false),
  (38, 'S3', 3, '잠정 실적은 한국채택 국제회계기준(IFRS)에 의거해 추정한 결과이며, 아직 결산이 종료되지 않은 가운데 투자자들의 편의를 돕는 차원에서 제공되는 것이다.', 'a17ba2dc5acafe96e8ad757f47f72bfb495670e110bf4e0a4e578678798bdc63', true, false),
  (39, 'S1', 1, 'SK하이닉스가 올해 2분기 매출액 79조 3,187억 원, 영업이익 60조 5,426억 원(영업이익률76%), 순이익 93조 9,226억 원(순이익률 118%)의 분기 사상 최대 경영실적을 기록했다고 29일 밝혔다.', '97f637e53d7087ff7d3ae5b85d741aca83e948a5a68c0d3065f6c9b50aaf09ae', true, true),
  (39, 'S2', 2, '이로써 상반기 누적 매출은 사상 처음으로 100조 원대에 올라섰다.', 'c75278922c291b51ab89e85f8f17685db37ad9ceb074a55cb6146c3ad4e4ab65', true, false),
  (39, 'S3', 3, '전년 동기와 비교하면 매출과 영업이익은 각 257%, 557% 증가했다.', '0f093f36b15e82260c96b1940a81c1d263a47872a9be2aa11acfeab72b5fc967', true, false),
  (39, 'S4', 4, '이 같은 실적 호조에 힘입어 2분기 말 회사의 현금성 자산은 전분기 말 대비 33.6조 원 늘어난 88조 원을 기록했다.', '553566ee86fa00ca24618785250e94f58e9fdbbc800bc2cd04fcba8fd5dc9482', true, false),
  (39, 'S5', 5, '반면, 차입금은 0.7조 원 줄어든 18.6조 원에 그치며 순현금은 69.4조 원으로 확대됐다.', '8cca3561dd4f64d2a43d2c73c4f67725a2b12872c75a44810b85d23459c3aded', true, false),
  (40, 'S1', 1, 'LG전자는 올해 2분기 영업이익이 전년 동기 대비 147% 증가한 1조5791억원을 기록했다고 30일 공시했습니다.', '3da8620114834ad1ab88ef2df82b5a82b9ef73df85d5a06d9d1957f4ae7f888a', true, true),
  (40, 'S2', 2, '매출액은 23조8265억원으로 전년 동기 대비 14.9% 증가했습니다.', '6956beb9a0488ef1f2eb7a4d00af9f19e89fc498a4fe998cba53d5cf82745d96', true, false),
  (40, 'S3', 3, '2분기 B2B 매출은 6조5000억원으로 전년 동기 대비 5% 늘었습니다.', '9f2dcb21f2213d3fe4391d267951c68be7378e5973c076523163f2763093c4e8', true, false),
  (40, 'S4', 4, '생활가전을 담당하는 HS 사업본부는 매출 7조757억원, 영업이익 6859억원을 기록했습니다.', '01879afbbccd5e94a0b0fae2f5e7fd70fb4e673abcaa314751b7452daad169ed', true, false),
  (40, 'S5', 5, 'TV를 담당하는 MS 사업본부는 매출 5조1146억원, 영업이익 2194억원을 기록했습니다.', '81293c9b110de42ba3479756742981503e02d0957e2f078c9fe6a717f7e36437', true, false),
  (40, 'S6', 6, '전장 사업을 담당하는 VS 사업본부는 매출 3조259억원, 영업이익 1912억원을 기록했습니다.', 'cd90c9ce8a3a057e0bc3dd1843312e8c3f02c9d995e6253ae956911822b421ed', true, false),
  (42, 'S1', 1, '현대로템은 24일 2026년 2분기 연결 기준 매출 1조6060억원, 영업이익 2324억원을 기록했다고 밝혔다.', '8674f5c0b2bdce188dbf5b53669f3c83947259a07c93af924920c0c0e8382b33', true, false),
  (42, 'S2', 2, '지난해 같은 기간보다 매출은 13.3% 증가했지만 영업이익은 9.7% 감소했다.', 'c9783cf2c60b8e6e6a63958522d87056e2651a1fd983766bbb1f60355a49fce7', true, false),
  (42, 'S3', 3, '상반기 누적 매출은 3조635억원으로 전년 동기 대비 18.1% 늘었다.', '87e9ab20e2bbb70a056bb9f8c8a13634bdb82af6b8528102389d000ad898fd7b', true, false),
  (42, 'S4', 4, '2분기 말 기준 수주잔고는 30조4046억원으로 집계됐다.', '7d8a5ab2dbdeae383c4493ee1c3c4b138664ad728d345802f7991f0aa1d204fe', true, true),
  (42, 'S5', 5, '창사 이후 처음으로 30조원을 넘어선 최대 규모다.', '954577a4efe6b94b7a425e1d7e9a390c7b8bdf31535baeef1caee3255ae3444e', true, false),
  (42, 'S6', 6, '사업 부문별 수주잔고는 AD&RH(Aero·Defense·Robot·Hydrogen) 부문이 9조8197억원, 철도(Rail System) 부문이 19조8670억원이다.', 'd86b270a061871b549c87ce74d40c606ce1ad0935b08028f019e079033654f2e', true, false),
  (43, 'S1', 1, '한화에어로스페이스가 올해 2분기 연결 기준 영업이익 1조3655억원을 기록했다고 31일 공시했다.', 'fc0cc4a54eaa8da189f1404f49f6a32778c2d4316eb86d2614c817d30e84c709', true, true),
  (43, 'S2', 2, '지난해 같은 기간보다 58.5% 증가한 수준이다.', '973b5b62584c6e462684939ee988ec2178efc82fd4e7806352f17a0cfb899202', true, false),
  (43, 'S3', 3, '같은 기간 매출은 9조2929억원으로 전년 동기 대비 47.2% 늘었다.', '6c2bb0d29d236f5b3554c465a1851f1992793e4b1c0e58442bf40d22fce83d42', true, false),
  (43, 'S4', 4, '당기순이익은 1조805억원으로 277.5% 급증했다.', '0afd5a4533be6d848050b65aaa06850e61a11ae88c2fe8a4351c25c3648a5d08', true, false),
  (43, 'S5', 5, '지배기업 소유주지분 순이익은 6364억원으로 253.2% 증가했다.', '9edf520902e15cf0b319cc029cbb10fe571e7d112152e18c15b69d02d701c344', true, false),
  (43, 'S6', 6, '직전 분기와 비교하면 매출은 61.6%, 영업이익은 113.7% 늘었다.', '7304d43ab20efe98cb8ed4e00d8118fd8135f2c82e13eac4f0f4a96300ed98bc', true, false),
  (43, 'S7', 7, '올해 상반기 누적 매출은 15조439억원으로 전년 동기 대비 27.5% 증가했다.', '42378d66578751aa95bfcbba6366862578d1ae8031d9883e9aca5abfd75f5fd0', true, false),
  (44, 'S1', 1, '2분기 매출은 1조1101억원으로 전 분기(1조1679억원) 대비 4.9% 감소했지만, 전년 동기(9454억원) 대비 17.4% 증가했다.', '03ed27e69b04c4aa74bbd9bb80a02330edd2fe8211d0f410abf050517986eba7', true, true),
  (44, 'S2', 2, '같은 기간 영업이익은 1057억원으로 전 분기(1711억원) 대비 38.2% 감소했으나, 전년 동기(816억원)와 비교하면 29.5% 증가했다.', 'a02319f7efc5b603593918de98b73f3ae7116c480961dff32398a7e4c333a911', true, false),
  (44, 'S3', 3, '당기순이익은 782억원으로 전 분기보다 42.3%, 전년 동기보다 24.5% 감소했다.', '903fe945e484f0415a3a0d7c40fd7152d3ff46e55467ff60e458bc651703bba2', true, false),
  (44, 'S4', 4, '상반기 누적 기준으로는 매출 2조2780억원, 영업이익 2768억원을 기록했다.', 'e53390e6318bc76d39211588bcea3dbe77f90d1668304066ee00dd9803673c22', true, false),
  (44, 'S5', 5, '회사 측은 2026년 2분기 말 기준 수주잔액이 24조5700억원이라고 밝혔다.', '373af772a1c0f7112e29ed3a3df95af8c292e53d28d28a68fa1b28d46a60ba1d', true, false),
  (45, 'S1', 1, '한국항공우주(KAI)는 2026년 2분기 연결 기준 잠정 실적을 공시하고 매출 1조1,679억원, 영업이익 484억원을 기록했다고 29일 밝혔다.', '4daa46d0041dd0daca4b2aa859a2f7efd60834d5841886d27e92cdaf7348a043', true, true),
  (45, 'S2', 2, '2분기 매출은 전분기(1조927억원) 대비 6.9%, 전년 동기(8,283억원) 대비 41.0% 증가했다.', '1b0944533c58f1074c86976881816bf369e0f485e825f12c3e573374801fa48c', true, false),
  (45, 'S3', 3, '반면 영업이익은 전분기(671억원) 대비 27.9%, 전년 동기(852억원) 대비 43.1% 감소했다.', '6e2f15a0f868febb12bfab5b5f250ae5a7ee554158227d3899118f361be5aa05', true, false),
  (45, 'S4', 4, '상반기(1~6월) 누적 기준으로는 매출 2조2,606억원, 영업이익 1,156억원을 기록했다.', '71375f1725ddb830aa0101919917d27092c4fad3c709d895cd48767756f0d8a6', true, false),
  (45, 'S5', 5, '이는 전년 동기 대비 매출은 48.0% 증가했지만 영업이익은 12.4% 감소한 수준이다.', 'ffc561f347c04eeb8c2190bc7fdaff742a8d6df214067805ca1851f8caabe887', true, false),
  (45, 'S6', 6, '당기순이익은 370억원으로 전분기 대비 10.4%, 전년 동기 대비 35.2% 줄었으며, 지배기업 소유주지분 순이익도 359억원으로 전분기 대비 14.6%, 전년 동기 대비 36.4% 감소했다.', 'ba8001cab0cfbcda68a53573f7fbdc25fbef1ac30b6bef97cece3ae199225714', true, false),
  (46, 'S1', 1, '올해 2분기 CJ대한통운을 제외한 연결 기준 매출 4조1950억원, 영업이익 1619억원을 기록했다.', '40db60174d40a72cb363afc1ac79ee3a1261f047f3c0211f27128c0a3894882c', true, true),
  (46, 'S2', 2, '전년 동기와 비교하면 매출은 10.2% 증가했지만 영업이익은 18.4% 감소했다.', '48fcb79dd40e7fc2c92263abe82382c04e6f36ad9d7046966199a33df722c76b', true, false),
  (46, 'S3', 3, '당기순손실은 239억원으로 집계됐다.', '0689fda5f27cc307c36909532696bc40b6a8323110f895ec3c44c026bd46dd01', true, false),
  (46, 'S4', 4, '식품사업부문 매출은 2조8441억원으로 지난해 같은 기간보다 5.8% 증가했다.', '0edf766fb2ec403f18072f321477977d4a092415ba62a6dcb3114cbb3e004052', true, false),
  (46, 'S5', 5, '반면 영업이익은 21.3% 감소한 709억원에 그쳤다.', '42016ba33805415a49997715c32c5450afbfc5a69dd91393ac5a055693cb8437', true, false),
  (46, 'S6', 6, '바이오사업부문은 매출 성장 폭이 더 컸다. 매출은 20.8% 증가한 1조3509억원을 기록했다.', '04fa0d613be3b4fc84f67fc0f591c4b4cd61baa88b1e28b9ecf55d342138bb4b', true, false),
  (46, 'S7', 7, '그러나 영업이익은 15.9% 감소한 910억원으로 집계됐다.', 'de42cd47944bf7e305f135ec9331dbf5196229980e8c546450f70755105ff810', true, false),
  (47, 'S1', 1, '에쓰오일(S-OIL)이 2026년 2분기 매출액 11조 3435억 원, 영업이익 9650억 원, 당기순이익 5146억 원을 기록했다고 발표했다.', 'f25f8a87de95d82dac87e795161f327c54dec65c61ab2828c4cfa689570621f7', true, true),
  (47, 'S2', 2, '사업부문별로 살펴보면 정유부문은 매출액 9조 293억 원, 영업이익 5,324억 원을 기록했다.', '4b98b0866a3654f7b2bac54f5a82f701715878afb185b34276ae078fc4b44401', true, false),
  (47, 'S3', 3, '석유화학부문은 매출액 1조 125억 원, 영업손실 448억 원으로 적자 전환했으며, 윤활부문은 매출액 1조 3017억 원, 영업이익 4774억 원의 뛰어난 성과를 냈다.', '1197fd7130eff0bedfa14a53772f44d5a13cfeec7d828167c32489235391cd1c', true, false),
  (47, 'S4', 4, '영업이익은 정제마진 강세에도 불구하고 전분기에 반영됐던 일회성 재고 관련 이익이 소멸하면서 정유부문을 중심으로 전분기 대비 소폭 감소했으나, 윤활부문이 역대 최고 수준의 분기 영업이익을 올리며 전체 실적을 견인했다.', '7d75ec2300856bf0aa6e30e2b10c6f900b3370405ced2a9c1c99d5e00eede60f', true, false),
  (48, 'S1', 1, '㈜GS는 올해 2분기 연결 기준 매출 7조4131억원, 영업이익 1조7174억원, 당기순이익 1조1320억원을 기록했다고 11일 밝혔다.', '654362d4ab7a92ab192a5e68d773015d88e8576c1d60ee0ca2759bc57a1c7b22', true, true),
  (48, 'S2', 2, '전년 동기 대비 매출은 24.9%, 영업이익은 253.4%, 당기순이익은 1180.5% 증가했다.', '223e26dc485c4c9666e9d91513a3165500de2f9e493978b98029de54f87ce061', true, false),
  (48, 'S3', 3, '이에 따라 ㈜GS의 상반기 연결 기준 매출은 14조2555억원, 영업이익은 2조9760억원, 당기순이익은 1조9587억원으로 집계됐다.', 'b82ece3195354ba6dcef0046a1327e75ee7835a516b7245388909f79f4892f64', true, false),
  (48, 'S4', 4, 'GS칼텍스는 2분기 매출 16조6724억원, 영업이익 2조5507억원을 기록했다.', '3a8904e9fb92e1910aec96103482a1b683f55c9f0e34f491f3ad0a094b6dbadd', true, false),
  (48, 'S5', 5, '2분기 매출은 2조4219억원으로 전년 동기 대비 105% 증가했고, 영업이익은 1조5341억원으로 347% 급증했다.', '4f950a81353bc232f32a035d471dc652ab0592fbce664afc5f84561b0c3dcb86', true, false),
  (48, 'S6', 6, 'GS리테일은 2분기 매출 3조1751억원, 영업이익 1094억원을 기록해 전년 동기 대비 각각 7%, 28% 증가했다.', '648c3f1a5d210c31df027a8ebcbbdabb17577c0337c128c7cb0d92c42120f74d', true, false),
  (49, 'S1', 1, '2026년 2분기(4월 1일부터 6월 30일까지) 당해실적 기준 연결 매출액은 9조6232억원으로 전년동기 8조1288억원 대비 18.4% 증가했다.', '254d884c8f257f3adc460581cce287a5d96dec266b7259d0a32b755028b1f916', true, false),
  (49, 'S2', 2, '영업이익은 4290억원으로 전년동기 3381억원 대비 26.9% 늘었다.', 'be392fcac2e4bf1f79bf408171f8382f561c5531a0b0025b10a653da5b21a472', true, false),
  (49, 'S3', 3, '당기순이익은 2473억원으로 전년동기 905억원 대비 173.3% 급증했다.', '04fd03dc29429c9d5148709e867082c7b49445494b972744ccf990eb82eedef4', true, true),
  (49, 'S4', 4, '지배기업소유주지분순이익은 2384억원으로 전년동기 898억원 대비 165.5% 증가했다.', 'fdfda303efc563823b7667ba254c683b6c58092eab5a58c72fcf69623765a666', true, false),
  (49, 'S5', 5, '2026년 상반기(1월 1일부터 6월 30일까지) 누계실적은 매출액 18조336억원, 영업이익 7865억원, 당기순이익 5246억원이다.', '3b4508345376733e6ab1be7f581f4d8887c522ae5e2fb712619206b96fa2e674', true, false),
  (50, 'S1', 1, '하이브가 2분기 매출 1조 4500억, 영업이익 1709억을 각각 돌파하며 사상 최대의 분기 실적을 달성했다.', '72f2f4f7be6fb4ce8d1a5277447c9ba43e00c68a5268264e54fd2c93881e3d8a', true, false),
  (50, 'S2', 2, '하이브는 2026년 2분기 매출액이 1조 4500억 원, 영업이익이 1709억 원이라고 28일 밝혔다.', '0929f38628a7970259d7aff4612bc2b7a93e71811816b665e0538edb92ca81e0', true, true),
  (50, 'S3', 3, '분기 기준 매출액이 1조 원을, 분기 영업이익이 1천억을 넘어선 것은 모두 최초다.', 'a285413f12faee86a75a17fde92e43783736e46a724e685c16ece19c54604609', true, false),
  (50, 'S4', 4, '공연 부문 6477억 원, 음반·음원 3268억 원을 각각 기록했다.', '26f46f8c80f957071dd693ad654637a77387a12bbec81441d85f0215d3bf9b9f', true, false),
  (50, 'S5', 5, 'MD(기획 상품) 및 라이선싱도 공연과 동반 상승효과를 내 3106억 원에 이르렀다.', '3e974e88ef42f3aeb491f42c22dba1176c226a3a835db6bea364c8a74e16fd5e', true, false),
  (50, 'S6', 6, '전년 동기와 비교했을 때 매출이 2배 이상 성장한 데 이어, 두 자릿수(11.8%) 영업이익률까지 달성해 내실도 다졌다는 게 하이브의 설명이다.', 'c2befef725f92debe147113f14c2160ec3524621d70127360e987d8c3c572058', true, false),
  (51, 'S1', 1, 'JYP엔터테인먼트는 2분기 연결기준 매출 1831억 원, 영업이익 310억 원을 낸 것으로 잠정집계했다고 12일 밝혔다.', '9b8f74e1fa7c3635447af1ec96b1ca157130f52eba6926f66f68b35ee38e8783', true, true),
  (51, 'S2', 2, '2025년 2분기보다 매출은 15.1%, 영업이익은 41.4% 줄었다.', '690906d3cc066dabaf03c1166272f176cf8aa5f09e36dce190a93b7ba54d9d62', true, false),
  (51, 'S3', 3, '같은 기간 순이익은 40.3% 감소한 217억 원을 기록했다.', 'c3ad6d51abcd0bebbf05f2cc70e530ce04fb4f1fae8eee1e4033db794b38b38d', true, false),
  (51, 'S4', 4, '영업이익 또한 매출 감소와 판매관리비성 지급수수료 증가에 따라 감소한 것으로 분석됐다.', '31ff86e71eed27e1ee4e50989947eed009f91919242195560e787b0db772061a', true, false),
  (52, 'S1', 1, '신세계는 올해 2분기 연결 기준 총매출 3조1414억원, 영업이익 1671억원을 기록해 전년 동기 대비 각각 8.5%, 121.9% 증가했다고 11일 밝혔다.', '6ae87c0ec9da6375043c30819807a781b02adfbf2f348b17fc0f730d3234569a', true, true),
