  (57, 'S6', 6, '하나생명은 전년 동기보다 약 223.8% 증가한 68억원을 기록했다.', 'bcb20704dfda2d441c8a79265f55ffd59c7d87db6d9328d0b575f9bbca5d860f', true, false),
  (58, 'S1', 1, '상반기 당기순익은 1조6090억원으로 전년 대비 3.5% 증가했다고 밝혔다.', 'de788fb00b35fdf45a519441eac28bee3f79dc8aaec0ca1dc710e82823a5d597', true, false),
  (58, 'S2', 2, '2분기 순이익은 1조46억원으로 1조원 이상으로 회복, 실적 턴어라운드를 달성했다', '845c25ce9bfd377da5e795d2dc097134edfe7219c77b38dbef31ab4f6d56858c', true, true),
  (58, 'S3', 3, '상반기 순영업이익은 5조7227억원으로 역대 최고치를 달성했다.', '13a9437593f3bf72dd5220a0fcd05cd1f81ef20f70b76a147b801be687b90173', true, false),
  (58, 'S4', 4, '이자이익은 4조6597억원으로 전년 동기 대비 3% 이상 증가했으며, 비이자이익은 1조630억원으로 전년 동기 대비 20% 늘었다.', 'b6861b91a8eaf374ed572f1660573b8462c42831c75e7cfd15955951ad9348a4', true, false),
  (58, 'S5', 5, '우리은행의 상반기 당기순이익은 1조3730억원으로 전년 대비 13.5% 감소했다.', '7b645e287937c60f2a48df9b58a00d07b5d0b735282c2683999f8fdff5beabfb', true, false),
  (59, 'S1', 1, '기아는 24일 2026년 2분기 연결 기준 매출액 33조3037억원, 영업이익 2조6290억원을 기록했다고 밝혔습니다.', 'b42c89f038ebbfa7ba24c8e9af4bc0725678bf81fc3dd6350b6d1810d3e8fc83', true, true),
  (59, 'S2', 2, '지난해 같은 기간과 비교해 매출은 12.6% 증가했지만 영업이익은 4.9% 감소했습니다.', '5c05c91ab45d5d0615a55a58b298e02bfb00cae44cc2d6c86515d52f73f79e2a', true, false),
  (59, 'S3', 3, '연결 매출대수는 80만3985대로 4.3% 증가했으며 원·달러 평균 환율은 1502원으로 7.0% 상승했습니다.', 'fa3ba49cbc6e7d3ad976c2835bc48da7fc4afac58002ec1debef89197c251dfd', true, false),
  (59, 'S4', 4, '글로벌 현지 판매는 83만9000대로 5.8% 증가했습니다.', 'dd904eba9f316d325b028a8e73121a0941c1d70ca98975e80cf542ca6a0f9bb7', true, false),
  (59, 'S5', 5, '기아의 2분기 글로벌 전동화 판매량은 29만6000대로 전년 동기 18만5000대보다 60.0% 늘었습니다.', '660f975b2448105735fefc507039b80f96ff49ee009115907e95041fe6e10ca8', true, false),
  (59, 'S6', 6, '2분기 연결 평균판매가격은 4110만원으로 전년 동기 3810만원보다 7.9% 상승했습니다.', 'e2f1cadd148dd4768e8e020e933bfdaaedc0c7b23938a57ce36a42631d8de183', true, false),
  (60, 'S1', 1, '현대자동차가 올해 2분기 하이브리드 차량 판매 확대와 환율 효과에 힘입어 역대 최대 분기 매출을 기록했습니다.', '53fb22a38b34e1ae5a9fa0123fbeb1745a06653b8b74348c5c7690bd42886ea3', true, false),
  (60, 'S2', 2, '현대차는 23일 경영실적 콘퍼런스콜을 열고 2026년 2분기 연결 기준 매출액 49조2153억원, 영업이익 2조8509억원을 기록했다고 밝혔습니다.', '063285b026e19687d980449ec1bdee4c04e792dff67fdd0a9af9e4e5523e1d7f', true, true),
  (60, 'S3', 3, '매출은 지난해 같은 기간보다 1.9% 증가하며 종전 최대였던 2025년 2분기 48조2867억원을 넘어섰습니다.', 'a7611d5669087048a92761e44252b6221ab1b24b80a0c3d7a569bbf7717bcf08', true, false),
  (60, 'S4', 4, '반면 글로벌 도매 판매는 99만1885대로 전년 동기보다 6.9% 감소했습니다.', '5841cdabe3e12b2b4f35b66ff8abf29ef1dcdff6f3c50a803d98885409cd7e55', true, false),
  (60, 'S5', 5, '국내 판매는 부품사 화재에 따른 공급 차질로 16.4% 감소한 15만7647대에 그쳤습니다.', '82555b8344912c5acb029a7109f02ef7a0146a185410eec9c88760509e94a32c', true, false),
  (60, 'S6', 6, '2분기 글로벌 전동화 차량 판매는 26만6627대로 전년 동기보다 1.7% 증가했습니다.', 'fee99db53d4c0ef075d2785ba22d368c946ab898cda1182f0bc318ceebd38c22', true, false),
  (61, 'S1', 1, '현대모비스가 올해 2분기 연결기준 매출 16조3247억 원, 영업이익 9752억 원을 낸 것으로 잠정 집계했다고 24일 공시했다.', '7c1eb598e75d78170011c291082b2e9825bfc009cae4314d71290642757abf51', true, true),
  (61, 'S2', 2, '2025년 2분기와 비교해 매출은 2.4%, 영업이익은 12.1% 늘었다.', 'b07b8db66250d8118f2e6dc987bf8600ae077dcac36d835f2704f35ae0e50217', true, false),
  (61, 'S3', 3, '부문별로 보면 모듈과 핵심부품 사업에서 매출 12조8942억 원, 영업이익 218억 원을 기록했다.', '71ef9974c872f7962a364afd8d7f4399bb12539cc33caecd3756ad27051e9bf3', true, false),
  (61, 'S4', 4, 'A/S부품 사업에서는 매출 3조4304억 원, 영업이익 9534억 원을 냈다.', '1df163aa7bcd6c3236ce09295eebac40e2f9779859429f4e4ad0bebb89b6cc7f', true, false),
  (61, 'S5', 5, '현대모비스는 상반기 누적 연구개발(R&D)비 9508억 원을 집행했다.', '461a6531d0340efb8231303143f02c502d5c824bfec6c595585d0eec708c762e', true, false),
  (62, 'S1', 1, '종합 조선 기업 HD현대중공업(329180)이 5월 4일 공시를 통해 KSS해운과의 VLGC 3척 건조 계약 체결을 발표했다.', '076e4dccc5d61fd402f92b74e0bf1a02d34ccaa2a912a24c186701de0ccb11d7', true, true),
  (62, 'S2', 2, '계약금액은 5048억원이며, 이는 최근 결산 기준 매출액 17조5806억원 대비 2.87%에 해당한다.', '209ca78019602ebfaafcc5e8ff10a5109d693b4d8e950bb2e22c3f47512cf072', true, false),
  (62, 'S3', 3, '계약은 2026년 4월 30일 시작되어 2029년 8월 31일에 종료될 예정이다.', 'af35c1f1ab1e7dd32014dc1d1335dd712ade2ec80da88de1b937593b1c1478b9', true, false),
  (62, 'S4', 4, '주요 계약 조건으로는 계약금 및 선급금이 있으며, 대금은 공사진척에 따라 지급된다.', 'b6129d8ed0973a4efd2369106b5ee73dfccc488d26e951b474b0e4db2f98a733', true, false),
  (62, 'S5', 5, 'HD현대중공업은 2019년 6월 3일 코스피 시장에 상장된 선박 및 보트 건조업체다.', '4a2862c47612736ed7e2e3dc729749708233d2a86a758eb64d3d5b3f219b6dad', true, false),
  (63, 'S1', 1, '29일 HD한국조선해양에 따르면 2026년 2분기 연결기준 매출액 8조9270억원, 영업이익 1조6451억원의 잠정실적을 기록했다.', 'a191816d7460a88695e47119da37a42301c7a64eeab4585168a19ff1c68af069', true, true),
  (63, 'S2', 2, '전년 동기 대비 각각 20.2%, 72.5% 증가한 수치다.', 'b29b70facb57b402ef384a55760f71e8467c4710f3eb301256f75c19d3be7a0f', true, false),
  (63, 'S3', 3, '조선 계열사인 HD현대중공업은 매출 6조3322억원과 영업이익 1조399억원을 기록했다.', 'f47b4badcd0111a38b1d7a612574ef26d4ac8a44ba022fe3444d6efefec19247', true, false),
  (63, 'S4', 4, '통합에 따른 시너지 효과가 본격적으로 나타나면서 전년 동기 대비 각각 52.7%, 120.6% 증가했다.', '697a322f744598d7ac74fe4cf9be7ad66785409b6552650e3b7c06b563b4d39a', true, false),
  (63, 'S5', 5, 'HD현대삼호의 매출은 2조3714억원, 영업이익은 5341억원으로 집계됐다.', 'e59128ab29fe2fd25bbdd51192c2be636dd18ffbb0c36772dc2d441568416029', true, false),
  (63, 'S6', 6, '선박 엔진 계열사인 HD현대마린엔진은 매출 1281억원과 영업이익 313억원을 기록했다.', '880190fd99308af32185065383ed302a74870b5e046d878f7db351fd4e7da159', true, false),
  (63, 'S7', 7, '사업 부문별로 보면 조선 부문의 매출은 7조4510억원, 영업이익은 1조3986억원으로 나타났다.', 'dd9ab65525c4e019b51abd60a264b76c21d3af2ce6316cb7576864ba0f45a4a0', true, false),
  (64, 'S1', 1, '삼성중공업은 2026년 2분기 잠정 매출액 3조2307억원, 영업이익 3250억원을 기록했다고 24일 공시했습니다.', 'fda1fca9fd0c9f681f5b20f6d40b2bfd3bd57c82046a45a2c5bae3ab10586a16', true, true),
  (64, 'S2', 2, '지난해 같은 기간과 비교해 매출은 20%, 영업이익은 59% 증가했습니다.', 'd71c289e9766a1ecda45e4abec0134ed45eeb186b6b6a73f3f8e70d482ab75df', true, false),
  (64, 'S3', 3, '상반기 누적 매출은 6조1330억원, 영업이익은 5981억원으로 집계됐습니다.', 'badde2548958e7285c21205026f48b193adc6eb86704c082d63333299a17fdd4', true, false),
  (64, 'S4', 4, '전년 동기 매출 5조1733억원, 영업이익 3279억원과 비교하면 각각 19%, 82% 증가한 규모입니다.', '01f0f5b83be6cd0788b8e7ec210431378b154c2d01bb555300bf155a24182b1d', true, false),
  (64, 'S5', 5, '삼성중공업의 올해 1월부터 7월까지 누적 신규 수주는 100억달러입니다.', 'd0aa56694fefcc6315e842b7974056f2cd8516f2028eced2125e86669cdbfdab', true, false),
  (65, 'S1', 1, '아시아나항공은 올해 2분기 매출액 1조5470억원과 영업손실 2951억원을 기록했다고 13일 밝혔다.', 'ee30c349c0d96698d6c7245290d35430a7153e3aa221617ec44f17482e09c5bc', true, true),
  (65, 'S2', 2, '매출은 화물기 사업 매각 영향으로 전년 동기 대비 1286억원 줄었다.', '3e87a4b66db4324a2d1c3349ac2209e2214ae87997feaa8a6315fccd9444136c', true, false),
  (65, 'S3', 3, '여객사업 매출은 1조2809억원을 기록해 전년 대비 1633억원(15%) 증가했다.', '7f410458cf786e7b59f69429f2d9a21e59c2d12de0efaa38e3dd4ca694e4e5e2', true, false),
  (65, 'S4', 4, '화물사업 매출은 작년 8월 화물기 사업부 매각 영향으로 전년 대비 2565억원 감소한 1147억원을 기록했다.', '5997c5ce317dc729f29067e2b0dee83bbcc79343d227c98320585f8836bde6ba', true, false),
  (66, 'S1', 1, '아모레퍼시픽 그룹은 2026년 2분기 연결 기준으로 매출액 1조 2543억원, 영업이익 1228억원을 올렸다.', '77784c049fcc399f11a0f771191ded3a2071e16cd784154e98f42d33598a8d0d', true, true),
  (66, 'S2', 2, '이는 2025년 동기 대비 매출은 14.6%, 영업이익은 53.3% 늘어난 수치다.', '91a841b56226f9b47cec01f5397c4d5e0c23bd7d193e8b0c3bfcdb1b70cff745', true, false),
  (66, 'S3', 3, '올 2분기 동안 아모레퍼시픽의 국내 사업은 10%의 영업이익률을 나타냈고, 해외 사업 부문 역시 두 자릿수 영업이익률을 기록하며 수익성 개선을 이끌었다.', '0df47d871327499cf3cf61933b28b19675fed0ca1e5137a1f13af763ae01c03c', true, false),
  (66, 'S4', 4, '그룹의 핵심 계열사인 아모레퍼시픽은 전년 대비 매출이 17%, 영업이익이 59% 늘어나며 전체 실적 상승을 주도했다.', '78914510d0895944488b65ddeee5d4613dd5896ccec36bf214a9372bd59dd8d8', true, false),
  (66, 'S5', 5, '국내 사업 매출은 10%, 영업이익은 48% 증가해 안정적인 실적 기반을 다졌다.', '234349cec0da6c43a66019f26736898e2a97f4e00eb7098168a519020f61ccc1', true, false),
  (66, 'S6', 6, '해외 사업은 매출이 28% 증가하고 영업이익은 99% 늘어났다.', 'c1beeec9f9acdde86161378bb94235b7f05b3a2ee13eae2ff68304953dc4766c', true, false),
  (67, 'S1', 1, '기아(KIA)가 멕시코 누에보레온주 페스케리아 공장에 총 6억 4,900만 달러(약 9,380억 원)를 투입해 브랜드의 멕시코 첫 전기차 생산 라인과 대규모 폐수 재활용 시설을 구축한다.', '22a38af334173be786fee0e51d4c59bb8a45eb190728b03217d78607372e1b0b', true, true),
  (67, 'S2', 2, '이번 대규모 투자를 통해 지금까지 한국에서만 전량 조립되어 온 기아의 전공간 전기차 모델 ''EV3''가 멕시코 페스케리아 공장에서 생산된다.', '8280fa58d73c276cce5a5111a4ad8d17314e6313b07b8c19f5ce1c6587290a14', true, false),
  (67, 'S3', 3, '첫 신차 양산 개시일은 오는 2026년 8월 4일로 확정되었다.', '394ed589719375475411d98ddfa203882a04d32cbdf3eacfc417a464a554f239', true, false),
  (67, 'S4', 4, '기아는 EV3 생산 초기 멕시코 현지 부품 구성 비율을 약 27%로 확보한 뒤 프로젝트 진행에 맞춰 점진적으로 확대할 계획이다.', 'ac9a997b88bdf44aec3c82467240a44c316e41fcb16bc4602aa76ec64ae140af', true, false),
  (67, 'S5', 5, '고용 측면에서는 2026년 1단계 사업에서 500명의 직접 일자리를 창출하고, 2027년부터 2030년 사이 1,500명의 인력을 추가로 채용해 생산 인프라를 대폭 늘린다.', '52d7ee5e7836c70834b6236150b127fed43acc0ccf969b3011e2792d02167d62', true, false),
  (67, 'S6', 6, '페스케리아 산업단지 내에 2메가와트(MW) 규모의 태양광 발전 단지를 먼저 조성한 후 2030년까지 8MW 규모로 대폭 확장한다.', '8a5f5d3e61d9e072b486d8453c710188e34d835e7ef2bf03e7c42066421d11a5', true, false),
  (68, 'S1', 1, 'SK하이닉스는 주요 고객사를 대상으로 올해 2분기부터 HBM4 양산 공급을 시작했다.', 'f537ddcb8c0a4c5c8f17db57547f6d4f3e0038ba7863f835b3b01b98f2d50795', true, false),
  (68, 'S2', 2, '현재까지 핵심 고객을 포함한 11개 고객사와 장기공급계약(LTA)을 마무리했다.', '2449f097bb75cc132181663a1a0d17967105aa539086153c42fc9fc20358cffa', true, true),
  (68, 'S3', 3, '계약 기간은 통상 5년을 기본으로 하되 고객과 제품 특성에 따라 달라질 수 있다.', '60c8e5f28a88a1890050da39e184d83d37e380ca9f7820c9827bf16e6c30636c', true, false),
  (68, 'S4', 4, 'HBM4의 양산 수율과 품질은 이미 성숙 단계에 진입한 HBM3E에 근접한 수준까지 올라왔다.', 'beb373fb4793dce903293cce6c24fa3843ceb64a6ef4dd7ae0574523096431b2', true, false),
  (68, 'S5', 5, 'SK하이닉스는 HBM4E의 주요 고객사 대상 샘플 공급을 완료했다.', '4a8ef2c02bd4b1bc4e622590a6c11be921a76e586b6e67aec8f2b2393df0e5e6', true, false),
  (69, 'S1', 1, '올해 3월부터 선보인 브랜드 IP 활용 제품은 누적 약 700만개, 판매액 약 150억원을 기록했다.', 'b954bb177a99ef46d125ac3e480d108525ac93e041394c4fecabfe4133c61bde', true, true),
  (69, 'S2', 2, '비비고 김의 풍미를 활용한 ''김 나쵸''와 ''김 팝콘'', 다시다의 맛을 접목한 스낵 등이 대표적이다.', '69b1b8d86a97755deee629a224fe0666acb7c709d3c54bc2633ee945ed3a9fec', true, false),
  (69, 'S3', 3, '이달 말까지 편의점에서 판매하는 브랜드 IP 활용 제품도 기존 13종에서 16종으로 늘릴 예정이다.', 'd4d9ae4f2bb24791da5437bbcde43394e9f4b6b48671a9af85288fddaded2304', true, false),
  (69, 'S4', 4, '지난 4일에는 ''햇반 라이스크림'' 3종을 출시했으며, 이달 중 ''햇반 라이스라떼''와 ''맛밤 밀크티라떼''도 선보인다.', '4016cd381e38357ec22bf147d9a698ed52b8f5aa9ec2c6dfc3d75533e3765550', true, false),
  (69, 'S5', 5, 'CJ제일제당은 국내에서 판매 반응을 확인한 제품을 해외로 확대할 계획이다.', '768cf89b018f1d26226bf4d8595ac2d6762a45bdb1560f58cce7f84bf6c8c5c5', true, false),
  (69, 'S6', 6, '특히 ''김 나쵸''와 ''김 팝콘''의 미국 시장 진출을 추진하고 다른 브랜드 IP 제품의 해외 진출도 순차적으로 검토할 방침이다.', '742e19b9e5f8465a30da963509cfd3f9df97f93814c33206e32884d82189fcbb', true, false),
  (70, 'S1', 1, '크래프톤의 기대작 ''서브노티카 2''가 출시 5일 만에 글로벌 판매 400만장을 돌파했다.', 'b53e0defd6ba0b3465b22d479ac87b8f5361591182047ea26c8e849e15c3b71b', true, true),
  (70, 'S2', 2, '출시와 동시에 판매 100만장을 기록한 데 이어, 12시간 만에 200만장을 돌파했다.', '5e0599fb6a45b96090c40d2e168c38e29c7ebaac85ec4aebe2f8dc5c02c45924', true, false),
  (70, 'S3', 3, '스팀 기준 최고 동시접속자 수는 46만7000명을 기록했다.', '3d7cdc8d5248dd034a1561ec81052a31e96662530a016df9ea0a04c65a27afe2', true, false),
  (70, 'S4', 4, '일평균 활성 이용자 수는 130만명에 달했다.', '76ceff496b005bfbd20365d6d2cadd4cab8f074974e2b2eb706d4a4afaa52485', true, false),
  (70, 'S5', 5, '누적 플레이 시간은 2857만시간으로 집계됐다.', 'a69f1c5222a37b8cd5240191d71264380b54a562a9fa80ff4fc90c892173682e', true, false),
  (70, 'S6', 6, '시리즈 최초로 최대 4인 협동(Co-op) 모드도 도입했다.', 'cb3681a1e9ec92a39f2b5808cc39fd558b2c682b02aad42bc4ba5661137c87b9', true, false),
  (71, 'S1', 1, 'BGF리테일이 운영하는 CU는 3월 말 기준 몽골 556점, 말레이시아 176점, 카자흐스탄 56점, 미국 하와이 2점 등 총 790점을 운영 중이다.', 'c98ad5fde2e13df1dac274dc7841b55e442dc02149c9c6d11b35b186ea2258db', true, true),
  (71, 'S2', 2, 'CU는 해외에서 △차별화 △현지화 △콜라보 3가지 콘셉트로 현지 고객에게 매력을 선보이고 있다.', '204f718738a7db99b0436786ce6b6ae78d8b3314a2219ae71070c32267d03717', true, false),
  (71, 'S3', 3, '2018년 진출한 몽골에서는 수도인 울란바토르를 넘어 몽골 제2의 도시인 다르항(Darkhan) 등에도 다수의 점포를 개점하면서 몽골 전역으로 출점 범위를 확대하고 있다.', 'bc2108d3483cadf2266982f6994878b0c46cff6679f16cf618cb9efb1d93a8f2', true, false),
  (71, 'S4', 4, 'CU는 현지 출점 속도를 감안할 때 1~2개월 내 해외 800호점 돌파가 가능할 것으로 보고 있다.', '4b8dcfeabd0168bdfd7b94d3061a1bb22265b513d880d86eb2a7c79e252ea49c', true, false),
  (71, 'S5', 5, '앞서 2028년까지 해외 진출 국가를 5개 이상으로 늘리고, 점포 수를 최대 1200개까지 확대하겠다는 목표도 제시한 바 있다.', 'c5fd93ff2f0f632040d0902800e42fc12b33f58d1b60427f95fbb39541d3b4c5', true, false),
  (72, 'S1', 1, 'BTS 멤버들은 23일 오전 인천국제공항 제2여객터미널을 통해 미국 애틀란타로 출국했다.', '577c78e6d56b685ae953d8013b93ee035f5379d6cc5d408634a72e8aadf5a57e', true, false),
  (72, 'S2', 2, '이번 출국으로 BTS는 오는 25일부터 북미에서 월드투어를 이어간다.', 'aaef4214f4e08410261380d2fc23f4b52af77d3dce46c15273de68c58fb8e937', true, false),
  (72, 'S3', 3, '이번 BTS 월드투어는 ''아리랑''은 전 세계 23개국 34개 도시에서 82회 이상 공연이 예정돼 있으며 K-팝 사상 최대 규모의 월드투어다.', '03942bdb2701644b357749cc6e938bc9ab8afadeb935d10e97524fe597352417', true, true),
  (72, 'S4', 4, '지난 9일 경기 고양종합운동장을 시작으로 월드투어에 나서며 본격적인 완전체 활동에 돌입했다.', 'f2bb96a5c9efee0140305544744c95af9d8f1bc6d4e62e2cddc99844dcd85641', true, false),
  (72, 'S5', 5, '지난 18일에는 일본 도쿄돔에서 팬들을 만났다.', '0f158a6884dd139048ee8eab72032492dc28bdfe6026ef8008559ad6ecccad05', true, false),
  (73, 'S1', 1, '삼양식품 말레이시아 법인은 지난 5일(현지시간) 불닭 스와이시를 출시했다.', 'e12055507ee44767f0c8a34a36d539a09941eeb2e14f2acd932cdd8b4d7f94a1', true, true),
  (73, 'S2', 2, '''달콤한(Sweet)''과 ''매운(Spicy)''의 합성어인 스와이시는 지난해 12월 미국 시장을 겨냥해 처음 선보인 해외 전용 라인업이다.', 'b031bf9a2e4dee1088d0a5a65f9d933119add4da4180e92f8d4accf9f9517851', true, false),
  (73, 'S3', 3, '자체 기준 5단계의 매운맛 중 가장 낮은 1단계로 개발, 현재 불닭 라인업 중 가장 순한 맛을 구현했다.', '6946248cc3a580f080c83d9cc6328846351dea9348660778d6e8e248cc43813e', true, false),
  (73, 'S4', 4, '기존 소스의 단맛을 강화하고 단맛을 더하는 스프링클을 별도로 담아 매운맛과 달콤한 풍미가 조화를 이루도록 설계했다는 게 회사 측 설명이다.', '8d44bd3850668caa27749324eee3be468864076df7c271be27962d2d70b4306b', true, false),
  (73, 'S5', 5, '미국에 이어 말레이시아를 두 번째 출시국으로 선택한 것은 현지의 높은 K-푸드 선호도와 글로벌 소비 트렌드를 반영한 결과로 풀이된다.', '9508333c6f41de4429b969181a1778905ad33c3128ed2c97ec8c9327df827c9c', true, false),
  (74, 'S1', 1, '농심은 2024년 8월 부산 강서구 녹산국가산업단지에 수출 전용 라면공장을 짓겠다고 발표했다.', '4e0d883631ea6efd7f1f0b158c32b8bffdcd1339f0dcc49f083eaf6f8e0f8e83', true, true),
  (74, 'S2', 2, '올해 하반기 완공되면 연 5억 개를 생산할 수 있다.', '4f7502835a63d9aa15cea308700f15942a2ff8ede9509b678b89e2c9dd9273ff', true, false),
  (74, 'S3', 3, '농심은 유럽과 북미, 중남미 등으로 늘어나는 수출 물량을 전담하는 생산기지로 활용할 계획이다.', '13cbeb5c387ddedba7d4ccbdaaa1e338e4206e8e57a11b97ba1c13256402e960', true, false),
  (74, 'S4', 4, '삼양식품의 해외 매출 비중은 80%, 농심은 40%에 이른다.', 'a1ddfcd832689bfbc8fe89df19b3d716df8c9c6cd47a48e523f555e6a343c3b2', true, false),
  (75, 'S1', 1, 'HMM이 2030년까지 총 29조원을 투자해 컨테이너선과 벌크선 선대를 276척 규모로 확대한다.', '3a31a19b1b6201e5681f24a1dcde5a7bbd0f57c05c22a61bbf9cf921ca550c7b', true, true),
  (75, 'S2', 2, '투자 기간은 올해부터 2030년 말까지이며, 예상 투자금액은 약 29조원이다.', 'c781e1a949919839ab187cee376dc1ceb4baf356e7320fb4b48bbd5e4201c59e', true, false),
  (75, 'S3', 3, 'HMM은 이번 투자를 통해 컨테이너선 선대를 166척, 147만TEU 규모로 확대할 계획이다.', 'dc49714381db5bf5acbe8984c1881e86ddf8bdd99e0276d74933640051581598', true, false),
  (75, 'S4', 4, '벌크선은 110척, 1352만DWT 규모로 늘린다.', 'ab357fd291421df40cfa0d46745ce55c67c91439253692c23e30739369989218', true, false),
  (75, 'S5', 5, '계획대로 투자가 이뤄지면 컨테이너선과 벌크선을 합친 전체 선대는 276척으로 확대된다.', 'd724b6c217a9347405dab64c2c0b7ae73c9c00a079e273a6ccd3c37674b8de82', true, false),
  (75, 'S6', 6, '이번 중장기 전략의 투자 규모는 2024년 발표한 계획보다 8조 2000억원 늘어난 수준이다.', '0d173e18cc51eb29beb5a853ba9274e958d58f9f1798f2b429380b0fec96d537', true, false),
  (76, 'S1', 1, '코웨이는 정수기를 기반으로 2023년 에어컨, 2024년 매트리스 및 안마의자 등 신규 제품을 확대했고, 해당 제품들이 시장에 안착하면서 성장세를 견인 중이다.', '3991431b61e78900d670fa6058a89af89718c5e0e463b0be55020b6d33352fcb', true, false),
  (76, 'S2', 2, '벽걸이형 에어컨과 세탁건조기는 삼성·LG를 제치고 판매량 1위를 기록할 만큼 브랜드 파워가 강력해지고 있다', '9ab9ee2352a7896745df8aa7ae21deb0064a777b1d19b1e426daa07436ddf337', true, true),
  (76, 'S3', 3, '매트리스 신규 렌탈 판매가 분기당 3만5000개를 넘고, 에어컨은 1분기 2만대에서 2분기 3만5000대로 크게 뛰었다', '226f023b83a19d075ea94773d9917853731a79e95fe7f1f60288ce8c04041ba1', true, false),
  (76, 'S4', 4, '올해 1분기 처음으로 분기 매출 4000억원 시대를 연 말레이시아 법인이 2분기에도 20%(전년 대비)대의 매출 증가율을 보이며 비슷한 성장세를 이어갈 것으로 추정하고 있다.', 'ec2fa250872e62b95f8ce1c7bd592acbf27774b546e13ddca2b2bde538fa34e9', true, false),
  (76, 'S5', 5, '앞서 코웨이는 1분기 태국에서 전년 동기 대비 30% 가까이 증가한 554억원의 매출을 올렸다.', '3e04748850663a73c44b808d45c18c4381920c37f8c368b3d3aee773caccba2a', true, false),
  (77, 'S1', 1, '엔씨(공동대표 김택진, 박병무)의 MMORPG(다중접속역할수행게임) ''아이온2''가 글로벌 출시 일정을 올해 하반기로 확정했다.', '1ef3d7440806bc768395ebe104ba6413f5154e91ae18bc9005ff4921b1335116', true, true),
  (77, 'S2', 2, '아이온2 글로벌 버전은 스팀(Steam)과 퍼플(PURPLE)을 통한 PC 전용 플랫폼으로 개발 중이다.', 'edbdf04eeeeb2e827fdce0ed2228a6b9b512a4def9a2757a2a8bf769cca2fa04', true, false),
  (77, 'S3', 3, '엔씨는 북미, 남미, 유럽, 일본 각 지역별 서버를 구축해 운영할 계획이다.', 'a2818d8936fe63d5f4a85e53d6c30eb6599e984bf2145e9d511cab234f904421', true, false),
  (77, 'S4', 4, '영어, 독일어, 프랑스어, 스페인어, 포르투갈어, 일본어, 한국어, 러시아어, 중국어(간체·번체) 등 총 10개 언어를 지원한다.', '6d6c6df87fab25045fefbf4cb4f051468cdffb84ddd85d09fa7666c071453e4e', true, false),
  (78, 'S1', 1, 'LG전자는 이달 출시할 차세대 로봇청소기 신제품에 ''홈봇''이라는 새로운 브랜드를 적용하는 방안을 추진하고 있다.', '1e15c74395d1774406401d795eeb032be48839e734757c196da0c2d21d9f6123', true, true),
  (78, 'S2', 2, '기존 ''LG 코드제로 로보킹'' 대신 ''LG 홈봇''을 앞세워 로봇청소기 제품군을 별도 카테고리로 분리한다.', '188ea91d93b65c50223aba7bbe886910be4ffab4a462b27b168d59d763b54551', true, false),
  (78, 'S3', 3, '기존 ''코드제로''가 무선 청소기 중심의 브랜드였다면 ''홈봇''은 청소 기능을 넘어 집 안 공간을 인식하고 이동하며 가전·앱·보안 서비스와 연결되는 로봇형 가전의 성격을 강조한 명칭이다.', 'd8f302242e5d715d442be774ce21c104938d5e59c729c03a131bb3fad1df8e3e', true, false),
  (78, 'S4', 4, 'LG전자 로봇청소기 신제품에는 2way 스팀, AI 사물인식 기반 자율주행, LG쉴드 보안 체계 등이 적용될 것으로 알려졌다.', 'ebea1fd0a5d4b5e1a3bb78f7a2a97bb11ebc144551dfec664bcfebd7d5cfb32b', true, false),
  (78, 'S5', 5, '일부 히든형 제품은 싱크대 걸레받이에 들어가 외부에서 보이지 않도록 설계돼 별도 거치 공간 부담을 줄였다.', '19f9dfadb68c33002040e99895b988edd12babc54ea26673258d2479594f2593', true, false),
  (79, 'S1', 1, '기존에 발표했던 신작들 중 ''나 혼자만 레벨업: 카르마'', ''샹그릴라 프론티어: 일곱 최강종'', ''프로젝트 이지스'' 3종만 출시하기로 한 것이다.', '216ac6811dc5772186dc24fb2f3ff13e2720313c9704ad7abfcf79923ec6a2ba', true, true),
  (79, 'S2', 2, '이중 ''나 혼자만 레벨업: 카르마''와 ''샹그릴라 프론티어: 일곱 최강종''은 오는 9월 열리는 도쿄 게임쇼에서 내년 출시 목표로 개발 중인 서브컬처 수집형 RPG ''펄 인 블루''와 함께 공개될 예정이다.', '75d7026fde4d7cec31a80623e48b90b1207f34850fc9ceb41891ba46799dfb4d', true, false),
  (79, 'S3', 3, '당초 넷마블은 하반기 이들 신작 외에도 프로젝트 옥토퍼스, 이블베인 등의 신작을 출시하기로 밝힌 바 있다.', 'c2d96b11148ccd4aa039ef1fdbbf9052d8f177644b1f1a3a299088a16a6bfbd8', true, false),
  (79, 'S4', 4, '하반기 라인업을 조정한 이유는 보다 엄격한 런칭의 기준을 마련할 필요성을 느꼈기 때문', '99d51faf51fdb7c021953d6536962d62a3a22e0fababddcae17b6acd82db3365', true, false),
  (80, 'S1', 1, 'HD한국조선해양은 유럽 선주와 초대형 암모니아 운반선 3척에 대한 건조 계약을 체결했다고 13일 밝혔다. 계약 금액은 총 5456억원이다.', '2b90a065b0bc422da08113519b4c50ac0f5fa5ecab4d72557893ce41c268c06c', true, true),
  (80, 'S2', 2, '이번 선박은 HD현대삼호에서 건조되며, 2030년 상반기까지 순차적으로 선주사에 인도될 예정이다.', 'f3712921d3950d66a12aa4729830688e1d0f3ba572f29455be0ddc9a5b0b2f54', true, false),
  (80, 'S3', 3, '초대형 암모니아 운반선은 암모니아를 대량으로 운송하는 선박이다.', '0a2be63d95112394997a2bb27f6486ac1a38324545175f226fda3fd6c896abad', true, false),
  (80, 'S4', 4, 'HD한국조선해양은 이번 계약을 포함해 올해 총 9척의 초대형 암모니아 운반선을 수주했다.', 'e741d7afe3bcd5d8a65d1456f76b8fae7e8430f53d80d1c68f20655fefa1776f', true, false),
  (80, 'S5', 5, '올해 누적 수주량은 142척, 금액으로는 163억9000만달러다.', 'c407dee52476793839672def2eac5396ccc6c7fcd3737d65939482323c1efa88', true, false),
  (81, 'S1', 1, '삼성중공업은 버뮤다 지역 선사로부터 원유운반선 2척을 총 2849억원에 수주했다고 8일 공시했다.', 'e72c5d4032e8a7b7ce852e1e4c03ce7f0efdf36b758ccf59e0d89a01dd3dbdc6', true, true),
  (81, 'S2', 2, '해당 선박은 2029년 5월까지 순차적으로 인도할 예정이다.', 'c7df1eab89a541ce53395e72bcd15669a4ca6ac4966a123e98bc1a520f5a0196', true, false),
  (81, 'S3', 3, '이번 계약으로 삼성중공업의 올해 누적 수주 실적은 상선 32척과 FLNG 2기 등 총 100억달러로 늘었다.', '0bdc82cbaf884f6a44023cc50264f97155a33293b89b4fcd5ddbd5c37b27e6db', true, false),
  (81, 'S4', 4, '삼성중공업이 연간 수주액 100억달러를 달성한 것은 글로벌 경기 회복에 힘입어 상선 발주가 크게 늘었던 2021년 이후 5년 만이다.', '27ca6d462721c4af329d14c9d01a6a5068a11b05e2961989f152d76d6030c9bc', true, false),
  (81, 'S5', 5, '삼성중공업은 이번 계약까지 상선 32척, 56억달러를 수주했다.', '96045a0ef6b316f165a097cb2e3c50914afe8b6b362d6764ca67e4130189a6ae', true, false),
  (82, 'S1', 1, '한화에어로스페이스가 이달 3일(현지시각) 창원 공장에서 폴란드 수출용 K9PL 자주포 첫 배치를 선적했다고 지난 4일 보도했다.', '554f63a12c2134df611c2ecd117a6c8f34ba667c8d4a285a3b6a47e4a3859921', true, true),
  (82, 'S2', 2, '이번 인도 물량은 2023년 12월 1일 체결한 3조 4474억 원 규모의 2차 실행 계약에 따른 것이다.', 'af947a87c7f1dc235b9e02d724f86cf80e97cce9e8f5779e648f0b6f725fbcf6', true, false),
  (82, 'S3', 3, '총 152문 계약 규모 중 지난해 11월 인도를 마친 K9A1 6문을 제외한 나머지 146문이 내년까지 순차 공급된다.', '32cc6a2d3da2a27114d98d6f5ebb3f57bb055b05c97ccbf482b6dcd39823ffea', true, false),
  (82, 'S4', 4, '폴란드가 두 차례 실행 계약으로 확정한 K9 자주포 누적 주문량은 총 364문이다.', '92200bea1c1b40b816b0da1794fea24798ccabac9d4355bce43949cc59257f0e', true, false),
  (82, 'S5', 5, '지난해 말 기준 약 37조 2000억 원까지 축적된 회사 전체 수주잔고 가운데 지상 방산 비중이 큰 만큼, 이번 인도가 수주잔고 실적 전환 구간 진입을 알리는 신호탄으로 평가받는다.', '594d1129c2a26d95aaee8073d77fe2f85512081ccdec4757e7e4a30dba14625b', true, false),
  (83, 'S1', 1, '이번 분기 해외 매출은 전년 동기 대비 178% 증가해 7000억원을 돌파하며 전체 매출의 92%를 차지했다.', '3b4eef2214397ca5aee9c15ba9192a3a8a680bd35c6ea5156c03aa436d7b4d8d', true, true),
  (83, 'S2', 2, '북미·유럽 비중이 지난해 같은 기간 40%에서 올해 68%까지 확대되며', 'cba524a795b4fcace7cccc4c19680e3bcddd412389e8549c3fa09ae5023efe86', true, false),
  (83, 'S3', 3, '유럽은 영국, 프랑스, 독일, 이탈리아, 스페인 등 5개국을 중심으로 아마존, 틱톡샵 등 온라인 채널 입점을 빠르게 확대하며', '43772ea78421cdbf32783049f1fd6c12b1b472d4e8f015fa55a1beb2a6f3a4d9', true, false),
  (83, 'S4', 4, '북미 매출은 전년 동기 대비 264.6% 증가한 3763억원을 기록했다.', '414693aa69a91942931d9cdadfce91e69846c841275210f7b94207dbc6f86a82', true, false),
  (83, 'S5', 5, '유럽은 전년 동기 대비 380.3% 증가한 1451억원의 매출을 기록했다.', '8792852736a258521d849c615032f771b39b15fdc4af655f78e7822736b0a5b9', true, false),
  (83, 'S6', 6, '아시아는 안정적인 수요를 바탕으로 전년 동기 대비 14.5% 증가한 1211억원을 기록', '549056204bfa6b36e727574b964f24b27b88fd48fbf373cb6708afd0018ad6a4', true, false),
  (84, 'S1', 1, '올해부터 내년 초까지 총 3100억원의 주주환원을 실행할 예정이다.', '39d5a295a1113356e21a9658e2149412e7d52c30d5d5a973498c34bef46e294d', true, true),
  (84, 'S2', 2, '지난해 2000억원을 자사주 매입에 투입한데 이어 올해는 더 많은 금액을 주주들을 위해 투입한다는 방침이다.', '0c33c41401f8a11a908205b6bc7b9f2375d26729d312367b03f8c601f9b15973', true, false),
  (84, 'S3', 3, '향후 3년간 경상 배당수입 30% 이상과 투자성과 일부를 자사주 매입 및 소각 또는 현금배당 방식으로 주주에게 환원할 예정이다.', 'fc9599624d1547bb93eb8cc46df62b3cae509b3b9112ce13efa0d8022ce5dd05', true, false),
  (84, 'S4', 4, '또 자본준비금 5.89조원을 이익잉여금으로 전입하기로 했다.', '0d15218e8c2ec234260fccb1b78c52dfcc5b9fde765076c56e91046dd022ca9a', true, false),
  (85, 'S1', 1, 'CJ대한통운은 지난 27일 군포복합물류터미널에서 대신택배와 ''이형 상품 배송서비스 확대 및 협업모델 구축을 위한 업무협약''(MOU)을 체결했다고 28일 밝혔다.', '0d547dac72a60be48cb098750ada0fa9dbe6e4f3ab06f4febba8d2b26b2a3aa9', true, true),
  (85, 'S2', 2, '이형화물은 일반 택배 기준(가로·세로·높이의 합 160cm, 무게 25kg 이하)을 넘어서는 크기나 무게, 또는 일정하지 않은 형태로 인해 별도의 운송·취급 역량이 필요한 상품을 말한다.', '8109cea6cea2241df9646bd0fe792806132a869a6f79e9f5daceff42decee021', true, false),
  (85, 'S3', 3, '최근 캠핑·낚시·골프용품 등 대형 상품의 온라인 거래가 늘고 1인 가구 증가에 따른 셀프 인테리어 수요도 확대되면서 이형화물 배송 수요는 꾸준히 증가하는 추세다.', 'a19596de7c81993b36f15630bceb773b222d8855b9a47585efbbd3fb931e0ac8', true, false),
  (85, 'S4', 4, '지난해에는 주 7일 배송 서비스인 ''매일오네''를 선보였다.', 'a1df2f0ae787fc2a87b52a8d0a09c2324fd6760b97c6c7b952573c9d9003a508', true, false),
  (85, 'S5', 5, '올해 4월에는 개인 간(C2C) 배송 서비스인 ''보내오네''를 출시했고, 이번에는 대형·이형화물 배송까지 추가하며 포트폴리오를 확장했다.', '5f2d43b70169325a5b5d1e9556a8c7866a06f5520f7d0bb73b84b29830b42ed8', true, false),
  (86, 'S1', 1, '샤힌 프로젝트는 온산국가산업단지 내 약 88만㎡ 부지에 총 9조2580억원이 투입되는 초대형 사업이다.', '2ce91ab0ea944f4452b45def5ab4be833384daa6e539c5df91426744ca98c46c', true, true),
  (86, 'S2', 2, '2023년 3월 착공해 올해 6월 말 기계적 준공을 목표로 추진 중이며, 이후 연말까지 시운전을 거쳐 내년 1월 상업 운전에 들어갈 예정이다.', '904cc40f4b95f2ea291b3779ac429dd0e0f320c8c30decf4d80277515348703a', true, false),
  (86, 'S3', 3, '상업 가동이 시작되면 에틸렌 180만t, 프로필렌 77만t, 부타디엔 20만t, 벤젠 28만t 등 기초유분을 생산하게 된다.', '1584bdef770544025a895f1d09a67b7518245439186ba92111253483c50a0d00', true, false),
  (86, 'S4', 4, 'LLDPE(선형저밀도폴리에틸렌) 88만t, HDPE(고밀도폴리에틸렌) 44만t 규모다.', '9fafefaba5e66d6cd7d3c1b4a8c2f23047e4279c2d9bb142be8b7807e134fcb1', true, false),
  (87, 'S1', 1, '현대모비스는 지난 3월 헝가리 중부 케치케메트에 건설한 모듈 공장의 가동을 시작했다.', 'cfe03d0eb2a09e208d111cd9e1c7f56329f7a919b6047e310d80e0ca33ff3c44', true, true),
  (87, 'S2', 2, '헝가리 공장에서는 메르세데스-벤츠 전동화 모델에 들어가는 섀시 모듈을 생산한다.', 'a8cc09b11539a96e05b6c16e42c2273bbd0813e1bc26fbbfe3e973eb264b6a39', true, false),
  (87, 'S3', 3, '스페인 나바라 지역에 건설한 배터리시스템어셈블리(BSA) 공장도 가동에 들어간다.', 'bcf6f4845edcdf766bc35bee52fd5ee0a458c5013d6ed9c3e903c8e4988af6a1', true, false),
  (87, 'S4', 4, '이 공장에서는 폭스바겐 전기차에 탑재되는 배터리시스템을 생산한다.', '2830d85828a7694c7a6fd4cd522ed8df52ea9535b07125211a3127623a905ff3', true, false),
  (87, 'S5', 5, '현대모비스는 지난해 글로벌 완성차 업체를 대상으로 91억7000만달러, 약 13조2000억원 규모의 핵심 부품을 수주했다.', '7703f81bcd5103dbc23ea489dc9000a799fdeb1efeedb783fd876c8897ec0627', true, false),
  (87, 'S6', 6, '슬로바키아 공장에서는 구동모터와 감속기, 인버터를 하나로 통합한 전기차용 파워일렉트릭(PE) 시스템 양산을 추진하고 있다.', '13e2084d8738a0461677383f26bfe7deb491c7231dd3aa85c5bdc030b2a41f3b', true, false),
  (88, 'S1', 1, '포스코인터내셔널이 북미·동남아 천연가스 생산자산 인수를 추진하면서 올해 투자 규모를 2조2000억원으로 확대했다.', '34f9c4c03d7ad777f056d0c0ddbe41af9d5aa48dc159c4d01e8542d85f710372', true, true),
  (88, 'S2', 2, '올해 미국과 동남아에서 생산 및 개발 자산 인수를 추진하고 있다', '6c0d6474ec94b52ab2903ed9bafe40267322c91e9551ac5983d4f20d0ecf2912', true, false),
  (88, 'S3', 3, '포스코인터내셔널은 현재 미국에서 LNG 공급원 확보와 트레이딩 수익 창출이 가능한 생산 자산의 인수를 검토 중이다.', '680a740df17f3df9d236a5f212748da248b875b1dded1f31db81559c1b1b6084', true, false),
  (88, 'S4', 4, '포스코인터내셔널은 에너지 투자 확대에 따라 올해 설비투자비용(CAPEX) 계획을 기존 1조8000억원에서 2조2000억원으로 4000억원 상향 조정했다.', '061771148d13547e6288ed6780fdc80aaebf07e9dc0687e9f59a8408399a2305', true, false),
  (89, 'S1', 1, '신한금융그룹이 상반기 7000억원 규모의 자사주 매입 목표를 조기 달성했다.', '98992216cabe81f53c0b25e531aec18672be8fe3af593392b9340a1b7587ad19', true, true),
  (89, 'S2', 2, '신한금융은 1~6월에 걸쳐 7001억원 규모의 자사주를 매입했다.', 'c22f305be7035aa0bea3912aec4bccc7914ae0e392b4143362adf827c59391a1', true, false),
  (89, 'S3', 3, '신한금융은 절차에 따라 소각을 진행할 예정이다.', '9dc0d31a0c6b367c1f840e052f334dd534daf5fc429ef3125a6c30455c400cdd', true, false),
  (89, 'S4', 4, '신한금융은 상반기 자사주 매입은 공시한 계획에 따라 진행됐고, 취득한 자기주식은 절차에 맞춰 소각할 예정', '1e7c0aab5c2b222ea0d71dca317d18a1639a3be7f0e4c3fb165c7515b77507f7', true, false),
  (90, 'S1', 1, '그룹은 상반기 총 4000억원 규모의 자사주 매입·소각을 추진 중이며 이 가운데 2000억원을 추가로 결의했다.', '31e23b83f4277611dfde4b2d418754ea2dbe3fc2586f919a066a1ee2661db92b', true, true),
  (90, 'S2', 2, '1분기 주당배당금(DPS)은 1145원으로 전년 평균 분기배당 대비 11.6%, 전년 동기 대비 24.6% 증가했다.', '17a5dcea35af767c2ce1a35611823e2635df19eda984100c5e0eef037fcd1552', true, false),
  (90, 'S3', 3, '1분기 기준 주주환원 총액은 5560억원으로, 이 가운데 현금배당 3070억원, 자사주 매입 2490억원이 반영됐다.', 'c14d70c3a8ae1ba2fc4570d1e586e609b6c08aa9cc8877d1b5fec3d3dbaf2cfb', true, false),
  (90, 'S4', 4, '실제로 주식 수 감소 효과가 반영되면서 1분기 주당순이익(EPS)은 전년 동기 대비 11.4% 증가했다.', 'f44ce25eaeb9f507c74e7b6bdcbf81b21f7df2271e0973c14db9a4ba6ed71b45', true, false),
  (91, 'S1', 1, 'KB금융지주가 지난달 23일 이사회에서 7000억원 규모 자사주 매입·소각과 4000억원 한도 신종자본증권(영구채) 발행을 함께 결의했다.', 'b393d527a5b2db5546c065e122a08a53af79f327ef04a3d119ad79d780556eef', true, true),
  (91, 'S2', 2, '소각 대상은 보통주 399만7715주로 발행주식총수 3억5468만7734주의 1.13% 수준이다.', 'f50be479c7ad7be34fae92613c5e52e93fdff938a2489e487882b575649cc151', true, false),
  (91, 'S3', 3, '이사회 결의 전날 종가 17만5100원을 기준으로 산정했으며 주가 변동에 따라 실제 수량은 달라질 수 있다.', 'f33311660e3517751afa170dd0d9a91e1fb74b60b919a2ea16ddf210361adde6', true, false),
  (91, 'S4', 4, '자기주식 취득은 지난달 24일부터 오는 12월 16일까지 삼성증권에 위탁해 장내매수로 진행한다.', 'dc0b1a15c9f2d24e6c8e87c7bd1ef49a723feb3ba852f30024bf7bf50f2d2175', true, false),
  (92, 'S1', 1, '우리금융과의 포괄적 주식교환을 추진하고 100% 완전자회사로 편입될 예정', '299626e1f45c67a0fde136cee46486a710ab02698ebee455252773a8945486dc', true, true),
  (92, 'S2', 2, '주식교환비율은 동양생명 보통주 1주당 우리금융 보통주 0.2521주', 'f5659abc5f8e8114c67d21b2ee96cb834478761469ceeb0498bddf501f635060', true, false),
  (92, 'S3', 3, '7월 24일 임시주주총회에서 특별결의를 거친 뒤 8월 중 주식교환을 완료하고 상장폐지 절차를 밟을 예정', '8dc5a91d084a6ca46b7120c645629b861c7a073cea1a3331cbca7f13885fe2d3', true, false),
  (92, 'S4', 4, '2009년 유가증권시장 상장 이후 17년 만이다', '08fef7e578c3b3aaee5554364c65c85377e1e3a2861bfe279761b6aec97f16db', true, false),
  (92, 'S5', 5, '완전자회사 전환 이후에는 ABL생명과의 통합 작업도 본격화될 수 있다는 관측이 나온다', '281837a2500a94b265d40ad10540734acd22318283dc30f217b1a359bd0fc94c', true, false),
  (93, 'S1', 1, '아이오페는 이달부터 세포라 온·오프라인 채널에 입점해 고기능성 피부 설루션(솔루션)을 제안하는 ''클리니컬 그레이드'' 스킨케어 제품을 선보인다.', '674afc3b3f6cdd16ae7139eeef72dc7188403457cc21aa7ee01e9661a294e12c', true, true),
  (93, 'S2', 2, '주력 판매 제품은 ''XMD 스템3 클리니컬 리커버리 세럼'', ''레티놀 레티젝션 세럼'' 등이다.', 'c9a79a67e724fc2a4470d44bea921378010f6a17593543e9a67dcf3eff282284', true, false),
  (93, 'S3', 3, '인체적용시험을 통해 모공 축소, 탄력·주름 개선 등의 효과를 확인했다고 회사 측은 설명했다.', '6885e7af79966f6692f741b0ef50b70ba5f5aea7a90b64090a3b73d23d307206', true, false),
  (93, 'S4', 4, '아모레퍼시픽은 이번 입점을 계기로 북미 시장에서 기술력 중심의 고효능 안티에이징 브랜드로 자리매김해 관련 시장을 공략할 계획이다.', '96d87a6f71d1abae4b53f16c65c3439cec48816aae6f702f03125cdbf2184d84', true, false),
  (94, 'S1', 1, '보유 라인업 55종 가운데 40여 종을 올해 출시했으며, 캐주얼 게임 누적 다운로드는 4월 말 기준 5710만 건을 넘어섰다.', '2ec51fa6ed01ee1c2014975465f6b424d5c76751116dcf1bd99a9535742d6899', true, true),
  (94, 'S2', 2, '1분기 캐주얼 부문 매출은 247억원으로 전년 동기 107억원의 두 배를 넘어섰다.', 'f519023e1d07ca13db6dc644f6a816b3314ee79ffe1664974c3193eb952a0433', true, false),
  (94, 'S3', 3, '지난해 인수한 퍼즐 캐주얼 스튜디오 ''팍시게임즈''에서 나온다.', '59ee0cf390613a99acd8eb23413b5aadd463cebad38e622b58f3fbcdcde32fcb', true, false),
  (94, 'S4', 4, '여전히 매출의 75.7%(1551억원)는 본업인 소셜카지노에서 나온다.', '33e42e8cd9817890962c1acc7bb1ac79a17850e806ee380baa9d1e1f81e5426c', true, false),
  (95, 'S1', 1, '삼성전자가 오는 22일(한국시간), 영국 런던에서 ''갤럭시 언팩 2026(Galaxy Unpacked July 2026)''을 개최한다고 8일 밝혔다.', '234c193fc37414deeae7437ff21cb7a698823d7140c935ccf55a2720625bf78e', true, true),
  (95, 'S2', 2, '이번에는 차세대 폴더블 스마트폰 ''갤럭시 Z8'' 시리즈를 선보인다.', '6f8abc658717b8239e59e592e95c320dd12b7bf55fec6e7f2db23336b8eeb05e', true, false),
  (95, 'S3', 3, '갤럭시 언팩 2026은 한국시간으로 22일 오후 10시(현지시간 7월 22일 오후 2시)에 삼성닷컴과 삼성전자 뉴스룸, 삼성전자 유튜브 채널을 통해 온라인으로 생중계될 예정이다.', '69ac6ec5c022b2bd20c7a098bc7a3441adba9a522366b506da92f4b15d907d37', true, false),
  (95, 'S4', 4, '삼성전자는 이번에 선보일 폴더블 라인업 재편을 공식화했다.', '23f16526643d29f187ee25eab13e87d55233a2297d98bce2e2529dc968d82900', true, false),
  (96, 'S1', 1, '닥터그루트는 최근 미국 세포라 핵심 매장 90여 곳에 전용 진열 공간인 ''헤어타워''를 설치하고 대표 제품인 SRS 라인 제품을 선보였다.', '8ce12c385266dc9a2a5d2d2b43f73eeaf19d296c4de5649df99be5a1113f405c', true, true),
  (96, 'S2', 2, '오는 8월 미국 전역 400여 개 세포라 매장 정식 입점을 앞두고 시장 반응과 판매 데이터를 사전에 확보하기 위한 전략이다.', '975ee661fd7e3316e72009e37531d20327033c7f588e5fc13330c9b9d26227dd', true, false),
  (96, 'S3', 3, '매장에서는 샴푸와 컨디셔너, 롤온 세럼 등 SRS 라인 핵심 제품을 직접 체험할 수 있도록 구성해 소비자 접점을 확대했다.', '2b622cfdf7b4bb98dff272b801ab1e96245fd22345c4197d03d5acca03ca02ac', true, false),
  (96, 'S4', 4, '닥터그루트는 현재 아마존과 틱톡숍 등 북미 주요 유통 채널에서 성장세를 이어가고 있으며, 올해 1분기에는 전년 동기 대비 세 자릿수 매출 성장률을 기록했다.', '92f18210357fd2158258dc959d64bf7aeab634f358ff11d2d8221b11c587c01e', true, false),
  (97, 'S1', 1, '현대차그룹은 아틀라스를 미국 조지아주 현대차·기아 공장에 우선 투입할 예정이다.', '6f10c17cbbc3fbbcce181fa64b27d69e06dd53c0355290795c0199419b4ee954', true, true),
  (97, 'S2', 2, '현대차그룹은 지난 5월 해외 기관투자가 기업설명회에서 현대차·기아 자동차 생산라인에 아틀라스를 2만5000대 이상 투입할 계획이라고 밝힌 바 있다.', 'c07615e3807481ab93c0ef89830a77db6f91365180ac355797e997e48e9aa948', true, false),
  (97, 'S3', 3, '아틀라스의 실제 가격은 양산이 시작되는 2028년 전후에 확정될 전망이다.', '5644c0f39281c9c90ca0fe95fbc05b576ae0b47a9fc5c7d6360f52277091bbe9', true, false),
  (97, 'S4', 4, '재코우스키 CPTO가 아틀라스의 ROI를 2년으로 제시하며 강조한 ''비용 효율성''은 글로벌 자동차 업계 최대 화두 중 하나다.', '78c9d29b6d200341342f3013012680cabc9e4664468f91d98d909ed927be8392', true, false),
  (98, 'S1', 1, '현재 월 3대 수준인 생산 능력은 추가 투자 시 연 30~40대까지 끌어올려 향후 KF-21 수출 물량까지 뒷받침할 수 있다', '554a4af593076254d2774c26727a370db556c17a01d6dbc8c970c75e27e366a9', true, false),
  (98, 'S2', 2, 'KAI와 방사청은 내년과 2028년에 각각 20대씩을 넘겨 KF-5E/F ''제공호''와 F-5E/F 등 F-5 계열 3세대 전투기 50여대를 순차적으로 대체한다는 계획이다.', '7ea8388541bbd6d4cbe55a38b2346f526062052ae17a728c09dd44b3cac17ad5', true, false),
  (98, 'S3', 3, '양산 1호기는 이미 공군 시험비행에 들어갔고, 올 하반기부터 공군 정식 인도가 시작된다.', '2cf9ef289189cc34a34230868ac5635cbe7f2e0df3248c4009fa85bbcf384c80', true, true),
  (98, 'S4', 4, '현재 각국과 협의 중인 KF-21 잠재 수출 물량은 ''200대+알파'' 수준', '30d3480cba4fb64c84a94fa3de07f4a5c32a01f24544381497eed4e22a3b39d6', true, false),
  (99, 'S1', 1, 'GS는 동해 지역에 1.2GW 규모의 데이터센터 건설을 추진 중이며, 현재 인허가 절차와 함께 잠재 테넌트들과 계약 협의를 진행하고 있다.', 'cf0ba85257b62314062ae72c274b6b3dfcb662abaa436b0ba11c5a663af783c5', true, true),
  (99, 'S2', 2, '총 투자비는 15조원으로, 이 중 11~12조원은 차입금으로 조달하고, 나머지 3~4조원 중에 절반 이상의 지분 확보를 목표로 하고 있다.', 'bfda6a5121b52e1f6288a02ee43e7d31073cd3af6b598c977d2d49e397da80db', true, false),
  (99, 'S3', 3, 'GS의 최종적인 Equity 투입은 1조5000억~2조원 수준이 될 전망이다.', '8e7b64f82047a1b59b09b260141e31775282b25d592a799a512275e4adf42e3d', true, false),
  (99, 'S4', 4, 'AI 데이터센터(DC) 투자도 본격 추진된다.', '037fc910c641e4080b3b90f2519ad2d1fc033d8f691585fdbe0a4033339be2e1', true, false),
  (100, 'S1', 1, '스트레이키즈는 8월 7일 ''THIS & THAT''을 발매한다.', 'f4e361ecc2e725bba754082206aa53ed5f29b8758a3ecf965e8c74d2034de1be', true, true),
  (100, 'S2', 2, '25일부터 26일, 29일, 8월 1일부터 2일까지 총 5회에 걸쳐 KSPO DOME에서 서울 월드투어 공연이 예정됐다.', '88548d2d83d3d97d561af73162db076c40f96e36ff634db8260d2bab6c2746d5', true, false),
  (100, 'S3', 3, '8월 1일은 공식 팬클럽 창단 8주년이 되는 날로, 스트레이키즈는 컴백과 함께 서울 콘서트 등 다채로운 이벤트로 팬들과 특별한 시간을 마련할 계획이다.', '5a186638fc369e18f1ff8326bf6e6771e14d2c5e32a3b05eba927a234c2ee5d1', true, false),
  (100, 'S4', 4, '9월에는 글로벌 음악 페스티벌 ''록 인 리오'' 무대에 출연한다.', '873aa55ffe5fac701a3f0c43d4b976a9f49e41d5b68df56f91149142b93a14c8', true, false),
  (100, 'S5', 5, '스트레이키즈의 미니 앨범 ''THIS & THAT''은 8월 7일 오후 1시 공식 발매된다.', '5a5bc2e1cd4335fb7296a80e410ea814529eaaee88ecca5ea12228b8b117cae1', true, false),
  (101, 'S1', 1, '베이비몬스터가 6월 26일부터 28일까지 서울 잠실실내체육관에서 ''2026-27 BABYMONSTER WORLD TOUR [춤 (CHOOM)] IN SEOUL''을 개최하고 두 번째 월드투어의 포문을 연다.', '54244c861c314aa614d14043a933252c1faa3f0e03bd588a3d3e6c249c7429bb', true, true),
  (101, 'S2', 2, '현재까지 공개된 일정만 18개 도시·29회 공연으로, 첫 번째 월드투어 ''HELLO MONSTERS''보다 규모를 확장했다.', '4032171b48f5b64458db18c300e953b1a3722a217b3ef7166946febdfbf048cc', true, false),
  (101, 'S3', 3, '이번 투어는 아시아, 북미, 오세아니아, 유럽, 남미 등 5개 대륙을 아우른다.', '4022a514bacb59f469b571041af3919121c3ff83bd0bef0d3d7ff9237fb25316', true, false),
  (101, 'S4', 4, '특히 미니 3집 [춤 (CHOOM)] 수록곡과 투어 전용 무대가 준비돼 기대를 모은다.', '7cc03a218a42ba3c10a95f964d0a36e21b227c8b4f67e80b9d97fd8976a602e0', true, false),
  (102, 'S1', 1, '강남점은 2023년 국내 단일 점포 최초로 연 매출 3조 원을 돌파한 데 이어 2024년(약 3조2,000억 원)과 지난해(약 3조6,700억 원)까지 3년 연속 3조 원을 넘었다.', 'af325426ee1907733408fd096545603cc19147734e16b96712ca1dde7e57e5a5', true, true),
  (102, 'S2', 2, '3조 원 달성 시기는 12월 20일(2023년)→11월 28일(2024년)→11월 7일(2025년)로 매년 단축됐다.', '9d465c37ff719a53f2683f1074ed4579e41a5395c98890a7a3aeafc152f81855', true, false),
  (102, 'S3', 3, '이외 연 매출이 3조 원 이상인 곳은 롯데백화점 잠실점(지난해 약 3조3,000억 원)뿐이다.', '5bc2db279dd5798b188279a4933701be45aec31d91ab9e3beb500291d72a30a7', true, false),
  (102, 'S4', 4, '신세계 강남점은 올해 매출 4조 원을 노리고 있다.', 'd8a06f32d3e6d73480bb90bc24ae51aa041d8eb9bd29dbb22d95b2c610f4d737', true, false),
  (102, 'S5', 5, '연 매출 4조 원대인 일본의 이세탄백화점, 영국 해러즈백화점과 어깨를 나란히 하는 글로벌 톱3 등극이다.', '7d01fe34565ea31a24b7add18c47b02a47fdb4bb26bd5064efd17445fa16a55e', true, false),
  (103, 'S1', 1, 'LIG D&A는 지난 2024년 9월 이라크 국방부와 약 3조7000억원 규모 천궁-II 공급 계약을 체결했다.', '122536b2597de1635800397ec1980b77f68f5e152fd3627a6f43b992f3abe99a', true, true),
  (103, 'S2', 2, '8개 포대 규모를 인도하기로 하며 현지 정부와 협력을 이어오고 있다.', 'ef2351337eb0acead3c4c28eaea3474358ecced2d377a9f8e710b45a6ad13d85', true, false),
  (103, 'S3', 3, 'LIG D&A는 7일 ''이라크 수출 사업은 정상적으로 진행되고 있다''며 ''계약에 따른 선급금은 정상적으로 지급됐으며, 사업 진행에 따라 후속 절차를 밟아나갈 예정이다''라고 밝혔다.', 'f02825dbf649ddbd1b415d9c8ad5d2c523ad10bbef9f12fd6dbb23aa35fd9aa5', true, false),
  (103, 'S4', 4, 'LIG D&A는 이라크를 비롯해 아랍에미리트(UAE)와 사우디아라비아에 천궁-II를 총 12조6000억원 규모로 수출했다.', 'e72e712088c6d16e36be01bd45bf812ea25526c49b8769c24b6c49d4fe55e184', true, false),
  (104, 'S1', 1, '한전은 28일 서울 양재동 한전 아트센터에서 미국 에너지기업 PSEG와 765kV 초고압 송전망 사업 협력을 위한 계약을 체결했다고 밝혔다.', '9ff47e59fc8cb349caf48e63d003acd859ac604163b8d634532c6348e2a9ac90', true, true),
  (104, 'S2', 2, '이번 계약은 한전이 보유한 765kV급 초고압 송전망의 설계·조달·시공(EPC) 역량과 안정적인 계통 운영능력을 국제적으로 입증한 중요한 성과로 평가된다', 'aaee8803234eaa1da32f1f9016c8dd29dc4af943ad8568ec376f5adf6ae3a0e4', true, false),
  (104, 'S3', 3, '한전은 이번 협력을 계기로 단순 기술 자문을 넘어 사업개발 및 수행 전반에 보다 적극적으로 참여할 계획이다.', 'b468a77887bde050358bfa990bc213924b01f370c28a5b9d537aaef8fef4a98b', true, false),
  (104, 'S4', 4, '한전은 국내 기자재 기업들과 함께 ''팀 코리아'' 체계를 구축해 미국 765kV 송전망 시장 진출을 추진할 예정이다.', 'a217d559f2ea5694bb3472b518490f88f85af615faa0d3409220649b77dd8dcb', true, false),
  (105, 'S1', 1, '키움증권 커뮤니티는 모바일트레이딩시스템(MTS) 내 실시간 채팅형 서비스다.', 'a964645ecdc68c02f773ae50a081bc8ad5f1e3c31d08c78ef4dd9f3dec834146', true, true),
  (105, 'S2', 2, '서비스 내 정보 제공 역량 제고를 위해서는 AI 기반 뉴스·공시 정보 요약 및 해당 이슈에 대한 긍·부정 투표 시스템이 도입됐다.', '6e10d6f2644b5d1e281dd99fdd7566a5ff7519f910af63f08716e0368302c3fb', true, false),
  (105, 'S3', 3, '건전한 투자환경 조성을 위해서는 AI 기반 모더레이션 시스템과 전문 인력을 결합한 2중 모니터링 운영체계를 마련했다.', 'ddbda39ef77962f13615514414b0f533194ebfc9cf48d8aad18095398693ea3c', true, false),
  (105, 'S4', 4, '키움증권은 해당 서비스가 출시 약 4개월 만에 이용자 수 150만명을 넘어섰다.', 'f1c2b9c39bb2c2f7fc2149956ba233fb4ae81929c5adf0dc0d3e16f4c73ff438', true, false),
  (106, 'S1', 1, '대한항공은 올해 2분기 별도 기준 매출이 5조 199억원으로 전년 동기 대비 25.9% 증가했다고 13일 밝혔다.', '12a8f2143d3b63594a110791f3c7f25523a1fb4e853e58aabb651c7cbb4da741', true, true),
  (106, 'S2', 2, '역대 2분기 기준 최대 매출이다.', '964ccac8f6b2c30513a056d9b30e5a796b18d774b479df3899051ba7e92254c2', true, false),
  (106, 'S3', 3, '2분기 영업이익은 유가 상승에 따른 연료비 증가 등으로 인해 전년 동기 대비 34.4% 감소한 2618억원을 기록했다.', '3a2b5279eaed3d99c2ced01012f1bb11c4567e991148229b70f150f967ac4321', true, false),
  (106, 'S4', 4, '2분기 여객사업 매출은 2조 8479억원으로 전년 동기 대비 4514억원 증가했다.', 'dd845c3661009e26351342a23e2f496211679f9499e38b64829e1450de7c07f5', true, false),
  (106, 'S5', 5, '화물사업 매출은 1조 5419억원으로 전년 동기 대비 4865억원 증가했다.', '334a2ebc71de970f7d0e3ac26a0ca551f035ed6021c9d48f9cf325c3215419f1', true, false),
  (107, 'S1', 1, '에스파(카리나, 윈터, 지젤, 닝닝)는 지난 7일부터 8일까지 서울 고척스카이돔에서 ''2026-27 에스파 라이브 투어 싱크 : 컴플랙시티''(2026-27 aespa LIVE TOUR - SYNK : COMPLaeXITY)를 개최했다.', '4e762e9fc331b8dbd2065bf6c25536b32592d8ae3cfecbd68a6636831a0d1867', true, false),
  (107, 'S2', 2, '이틀간 총 3만5000명의 관객을 동원하며 강력한 티켓 파워를 입증했다.', '7f6440173a64040fc07084324c622f2e5a1001a4746b98a640aca762f0d801d5', true, false),
  (107, 'S3', 3, '에스파는 북미, 남미, 유럽 등 총 25개 지역을 순회하는 네 번째 월드투어 일정을 본격적으로 이어갈 예정이다.', '7134f3695ac04f85b420ae5f0551c598609d9598ae91fa3e1a1b04b6d5bc1055', true, true),
  (107, 'S4', 4, '이번 공연은 에스파의 첫 고척스카이돔 입성이자 새로운 월드투어의 시작을 알리는 자리였다.', '7b180bd380ae2478587c5ac6ec887d473f163a72a237fb38a90c91250ff764cb', true, false),
  (108, 'S1', 1, '조선·플랜트 기업 한화오션(042660)이 2026년 2분기 당기순이익 6926억원을 기록하며 전년동기 대비 366.4% 증가했다고 27일 공시했다.', '8010baaee10a1841b30f1befd7571bceaf7b3303dbb603a8ec8418f03e17d7c2', true, false),
  (108, 'S2', 2, '매출액은 5조4432억원으로 전년동기 3만2941억원보다 65.2% 증가했다.', '1f7f3da913330631dab22a5983f1a5dbd3f417908e8217fd5c476ce6642a31dc', true, false),
  (108, 'S3', 3, '영업이익은 7361억원으로 전년동기 3717억원 대비 98.0% 늘었다.', '7e15014cf3de680109c0ad1c0d459a7b8a8a508eb943f7d96c6245aba5ffbc3d', true, true),
  (108, 'S4', 4, '상반기 누계 실적을 보면 매출액은 8조6531억원으로 전년동기 누계 6조4372억원보다 34.4% 증가했다.', 'ed26747a0e870e8532d52f525bd7cc234476b3dc3111980b9140d01d3725ab4b', true, false),
  (108, 'S5', 5, '당기순이익 누계는 1조1926억원으로 전년동기 누계 3642억원보다 227.5% 증가했다.', '9444933756b608d698f009585d831c5af5656ca96d56537da38c70338d44ac5e', true, false),
  (109, 'S1', 1, '현대로템이 베트남 호찌민 2호선 전동차 현지화 사업과 관련해 총 2건의 공급 계약을 체결했다고 23일 공시했다.', 'f7406dbe70a0c3559e0ec97f962dd768ac959992e425705c406892c985db0206', true, true),
  (109, 'S2', 2, '1단계 사업의 계약금은 1566억원으로 이는 지난해 매출의 2.7%에 해당한다.', '61e324e6dccece2db5b4b7a6be4b843260b9aaf80442a5d52309b8a0187d4ad9', true, false),
  (109, 'S3', 3, '2·3단계 사업의 계약금은 3345억원으로 지난해 매출 대비 5.7% 수준이다.', '3088e348a446b4f1c2cd42f271507967741412bc01ae914d4e4a96dbe4bdce92', true, false),
  (109, 'S4', 4, '계약기간은 2032년 12월31일까지다.', '8ddd277893ebfda6340d04ce3dbe0f21238c5454aeb70ffa7b3202f7047d0051', true, false),
  (109, 'S5', 5, '두 계약을 합산한 총계약금은 4911억원이다.', 'cb9bd2b7d02b2f79a1e25486b7ede605b68830152d996cfc43a5a63e1a3980f5', true, false),
  (110, 'S1', 1, '현대글로비스가 2분기 역대 최대 매출을 기록했지만 유가 상승, 운임 하락 영향으로 영업이익은 감소했다.', '1de00840d7dd06f5b96ad536238df1975227e78a9cf9cffc7ae149184d175577', true, false),
  (110, 'S2', 2, '현대글로비스는 올해 2분기 매출액이 8조7054억원으로 전년동기대비 15.8% 증가해 분기 역대 최대치를 기록했다고 23일 밝혔다.', '9afe183f7b74298e0d2c88ba9117bd3fad661052cb751a2b9729b6e4b68d6424', true, true),
  (110, 'S3', 3, '다만 영업이익은 8.1% 감소한 4950억원에 머물러 영업이익률은 5.7%를 보였다.', '104f57bdb30bd20c2fc9c91872e3ee2e2de082a9df7f29e4045ad840d6c273c8', true, false),
  (110, 'S4', 4, '비계열 영업과 북미 내륙 운송 물량이 늘면서 매출액은 지난해 같은 기간 대비 10.3% 늘었다.', '10ef96e8e4690379c7fbcf5e4b00c906d78d7d52b0513dbda4ffd4201851b70b', true, false),
  (110, 'S5', 5, '중동 지역 지정학적 리스크에 따른 유가 상승으로 수익성에 제한이 있었다.', 'a628f2c272057807176f250362d0c9d1cd0d05716fe4beadfa06a0001f1469f4', true, false),
  (110, 'S6', 6, '회사가 제시한 2026년 실적 가이던스는 매출액 31조원 이상, 영업이익 2조1000억원 이상이다.', 'afe89606db7ed1dc8356320523186792351dd40b82229c61fef145dc0066a8c6', true, false),
  (111, 'S1', 1, '롯데렌탈은 5일 연결 기준 2분기 매출 7658억원, 영업이익 846억원을 기록했다고 공시했다.', '56559a1d011764b38bbb35ca6aa1aebac37522dce4feb24d3014ce22a03a3be8', true, true),
  (111, 'S2', 2, '오토장기렌탈은 매출 4215억원, 영업이익 453억원으로 각각 5.1%, 25.6% 늘었다.', 'ba8a868d8d67e33ed357f7aab21e3b0f7c92368cd07c4d5abe35820022d53445', true, false),
  (111, 'S3', 3, '특히 중고차 장기렌터카 비중은 지난해 2분기 17.9%에서 올해 20.6%로 확대되며 수익성 개선을 이끌었다.', '1f1c106ac2369a07c17e612e4d5b0afd22b47e6139d2e81e1c96e3aa66d740fd', true, false),
  (111, 'S4', 4, '오토단기렌탈은 방한 외국인 관광객 증가에 힘입어 매출 525억원, 영업이익 99억원을 기록했다.', '45fb1f86bb67dfce0fad5537513c26574ac1978adc373977436273ce4894ece3', true, false),
  (111, 'S5', 5, '영업이익은 전년 동기 대비 76.2% 급증했다.', 'df5b702305b3640c3494533a6f6061029b252428f7b4f9059f84e6b0a1e9d964', true, false),
  (111, 'S6', 6, '회사는 우량 중고차를 낮은 가격에 처분하기보다 장기렌터카와 단기렌탈 자산으로 활용하는 전략을 선택했다.', '31783591925a90591cee55230e11db6235b490753272fc2070a1d775805ac8d1', true, false),
  (112, 'S1', 1, 'SK이노베이션은 2026년 2분기 매출액 29조1572억원, 영업이익 3조4873억원을 달성했다고 30일 공시했다.', 'ce32c8d063ba09148e5e6ea6206f41e707962ee17d5252b77fe2b1b4aecbc6d6', true, true),
  (112, 'S2', 2, '2분기 영업이익 호조는 윤활유 및 배터리 사업에서의 실적 개선 영향이 컸다.', 'fac9d6c6bb3cf26d4a2c84546871cb3b064b47ce152fa62daa95c4c73d63d316', true, false),
  (112, 'S3', 3, 'SK엔무브의 영업이익이 전분기 대비 5034억원 증가한 6919억원을 기록했다.', '6ea0f79ec05eccd1ddea5e854d6c278f271a3fbeb32359a8f735150ac659770d', true, false),
  (112, 'S4', 4, 'SK온 배터리 사업 영업이익은 8218억원으로, 전분기 대비 영업손익이 1조1710억원 개선되며 흑자 전환이라는 쾌거를 이뤘다.', '43fcefd865b00074450c144639170dba945c20a251f310ca3832cb7943a294a8', true, false),
  (112, 'S5', 5, 'SK에너지의 2분기 영업이익은 6512억원으로, 이 가운데 재고 관련 이익은 약 5600억원이다.', '43241868e6e322a6f5c1d673dcb29934c953e8e38ea1c3c54c42521d7ece4815', true, false),
  (113, 'S1', 1, '한진칼은 13일 이사회를 열고 보통주 4주와 우선주 6469주를 소각하기로 결정했다고 공시했다.', 'c2ba2babde60ede04fc435fd82577015dc5b896ddac6233c22092a2b96edb862', true, true),
  (113, 'S2', 2, '소각 예정일은 오는 25일이다.', 'ad9c0d3de1a64406d7ed8784c2de6cd890bf6d7a896a82a9e5b40a4cdf723c7d', true, false),
  (113, 'S3', 3, '소각 예정금액은 장부가액 기준 5442만7477원이다.', '6b8cea60ed93d3cddbf5d20ccb4dbeaaac0889aac62531aa1d188a4ed26ddf74', true, false),
  (113, 'S4', 4, '소각 대상은 한진칼이 회사 설립 과정에서 취득해 보유해온 자기주식이다.', '65c7601a68f65ed09b1fa0c4de258d7d9efc6062c9d5a3f66b66b7bc6b2defd8', true, false),
  (113, 'S5', 5, '이번 소각으로 발행주식총수는 감소하지만 자본금에는 변동이 없다.', 'da05ef6df70106a88ee140138feff4c6a9549638f859750ef88ea238ee623dd7', true, false),
  (114, 'S1', 1, '오리온의 2026년 상반기 연결기준 매출은 전년 대비 15.5% 성장한 1조 8239억 원, 영업이익은 17.9% 증가한 2980억 원으로 집계됐다.', 'c3949ac0c1a6a11f85b9280ab03d6203cf1530cdab85843c7cfd8f23848f670d', true, true),
  (114, 'S2', 2, '중동 전쟁 장기화에 따른 에너지비용과 물류비, 원부자재 가격 상승 등 어려운 경영환경 속에서도 한국 법인을 제외한 해외 법인들이 현지화 제품 확대와 성장채널 영업력 집중을 통해 두 자릿수 성장을 이끌었다.', 'c4d6348dbe25e8d3f67861de674915ffece7c52e8496f233a631ed9255cde30d', true, false),
  (114, 'S3', 3, '한국 법인은 거래처 감소에도 매출이 5834억 원으로 1.7% 성장했다.', 'ced1ee9ca7f0ad4b796029c4d33eead4f5474964861209ef7c9b2a918f6d4b54', true, false),
  (114, 'S4', 4, '중국 법인은 최대 성수기인 ''춘절'' 이후에도 판매량이 늘어난 가운데, 간식점 등 고성장 채널의 전용 제품 확대와 감자스낵 판매량 증가에 힘입어 매출 7877억 원(24.4% 성장), 영업이익 1447억 원(33.7% 증가)을 기록했다.', 'b038a7ec9390c961f84a9206f6d64f2d93642207d68ed821e3b69a9b75726995', true, false),
  (114, 'S5', 5, '러시아 법인은 초코파이 외에도 수박파이, 후레쉬파이, 참붕어빵, 초코송이, 젤리 등 다제품 체제가 한층 강화되며 매출 1955억 원(32.1% 성장), 영업이익 296억 원(62.2% 증가)으로 전 법인 중 가장 높은 영업이익 증가율을 보였다.', 'c2435db76c49bc16f06d4e67a2922794718e401c20bbeba950c5ae7f07d45b9d', true, false),
  (114, 'S6', 6, '오리온은 창사 이래 처음으로 분기배당을 실시하는 등 주주환원도 지속적으로 확대하고 있으며, 배당률은 향후에도 계속 늘려간다는 방침이다.', '46f1530e24bb6246165e97f12776d6ad9249efc1bf949073e76f468f75218a93', true, false),
  (115, 'S1', 1, 'HD현대중공업은 최근 공시를 통해 오세아니아 및 아시아 소재 선사로부터 총 8척의 선박 건조 계약을 체결했다고 밝혔다.', 'e43e5026f3fcddd2d453b669c41e088b228e08fcd98cd2a3581a8a0f236f3d0f', true, true),
  (115, 'S2', 2, '이번에 수주한 금액은 총 2조 1500억 원 규모로, 이는 지난해 HD현대중공업 매출액의 12.12%에 달하는 수치다.', 'ca1dfa45d423bf278e1cb035eba21d72a4fc534f4f13182162835c6e4bf053cd', true, false),
  (115, 'S3', 3, '오세아니아 소재 선사로부터는 초대형 가스운반선(VLGC) 2척을 약 3,500억 원에 수주했다', 'f1d745ddb1027c85f03af3ed94223547c64bd2b7a23ac3532526d8b2f751b882', true, false),
  (115, 'S4', 4, '기술력을 바탕으로 한 고부가가치 선박 중심의 선별 수주 전략이 연이은 대형 계약으로 이어지고 있다', 'e00783a4665139585f22e2dde92ed6aae8a3dd4e26d3252818ecb03794f7834a', true, false),
  (116, 'S1', 1, '삼성전자가 미래 성장동력 확보를 위해 올 상반기 연구개발(R&D)과 시설투자에만 55조 원이 넘는 자금을 쏟아부었다.', 'de0e473be605413c22bfe86295a1358d7f21a830cf2472049ac49e647731284d', true, true),
  (116, 'S2', 2, '글로벌 경기와 통상 환경의 불확실성이 지속되는 상황에서도 인공지능(AI) 반도체와 첨단 공정, 차세대 디스플레이에 투자를 집중하며 기술 주도권 확보에 총력을 기울이는 모습이다.', 'd8d42f0f3516efae1b8ffbfcaa651a37788f6a26b348cd3c7e07e7e8c86c8eb1', true, false),
  (116, 'S3', 3, '14일 공시된 2026년 반기보고서에 따르면 올해 상반기 R&D 비용은 27조 3627억 원으로 집계됐다.', '2517e1062d07acf5127b5c81a566e30617987836c6fcf220dbb953cf59516ff9', true, false),
  (116, 'S4', 4, '지난해 상반기(18조 641억 원)보다 약 9조 3000억 원 늘어난 액수로 반기 기준 역대 최대 규모다.', '8237e26b7a58aec848729f9e0a84e01767e153b75a34a1de851df9f685d4d4cc', true, false),
  (116, 'S5', 5, '시설투자액 역시 28조 원을 기록하며 전년 동기(23조 1000억 원) 대비 4조 9000억 원 증가해 최대치를 갈아치웠다.', 'f266ebe682d0dea449279cc85f0c8c0366eb50421f38777a55233fa156fb63de', true, false),
  (116, 'S6', 6, '삼성전자(005930) 는 이 자금을 반도체(DS) 부문과 삼성디스플레이(SDC)의 첨단 공정 증설·전환, 중장기 성장을 위한 인프라 구축에 집중했다고 설명했다.', '41fb9a2d01ea30bc041e84a649ff665949b8705196bcc842c5a93946e66b9493', true, false),
  (116, 'S7', 7, '대규모 투자에 힘입어 주요 제품의 시장점유율도 일제히 상승했다.', '2d1372ae1ceae1b446971c9ab65c5e0849a878aa98c29bbc3ebee7d24fda806c', true, false),
  (116, 'S8', 8, '가장 두드러진 성과를 낸 분야는 D램이다.', 'b0a2c6ba24a772e8cf708e583af0d2f97032fba45793e575902f129e9fc839e2', true, false),
  (116, 'S9', 9, '삼성전자의 D램 시장점유율은 지난해 34.0%에서 올 상반기 39.4%로 5.4%포인트 뛰었다.', '8a2841f1721b9c3ad05211c808cfa8d769b71790c37c68c69d67dacee41c810d', true, false),
  (116, 'S10', 10, 'AI 서버용 메모리 수요 강세가 이어진 덕분이다.', '76db068dc975a4275a8994fce7a920e01164a82af04991f9208be2a6fa1cb259', true, false),
  (116, 'S11', 11, '스마트폰 점유율은 22.0%로 전년 동기 대비 2.8%포인트 상승했고, TV 점유율도 프리미엄 제품 판매 확대에 힘입어 30.6%를 기록했다.', 'e6dead9593187ff8ca853f2ab4a126e062bde4c901a89d23e21b44516cfac948', true, false),
  (116, 'S12', 12, '이 밖에도 스마트폰용 패널(46.5%)과 디지털 콕핏(13.9%) 점유율이 각각 3.2%포인트, 1.1%포인트 오르는 등 전 사업부에서 고른 성장세를 보였다.', 'b0dcc9254d49c0d96112310da1fa671889a41f888c51e0813807006e43c724fb', true, false),
  (117, 'S1', 1, '최 회장은 칩 가격 상승이 완제품 가격 인상으로 번지는 칩플레이션(반도체 가격 급등)에도 우려를 나타냈으며, AI 시대에는 한 명의 사용자가 10개 이상의 AI 에이전트를 활용하면서 메모리 수요가 기하급수적으로 늘어나는 구조적 변화가 나타나고 있다는 설명이다.', '25a1724cb177ee1d5c9d9e1929f42aa82a721f9d490b8362b4650e6f269fd8ce', true, false),
  (117, 'S2', 2, '한국에서도 부동산 거래 위축으로 지방재정의 핵심 세원이 약해지고 올해 상반기 취업자 증가폭이 당초 예상의 절반에도 미치지 못하면서 닮은 경고음이 나오는 상황이다.', '726a6d5abce147796a0f79ba4a152c573365c488dea06470862cefcde5cae719', true, false),
  (117, 'S3', 3, '또한 양 사는 공동 태스크포스(TF)를 구성해 연구개발부터 현장 실증, 사업화까지 속도를 내며 데이터센터를 넘어 현실 세계로 확장되는 피지컬 AI 산업의 표준을 겨냥하고 있다는 평가다.', 'b47e533d9a95b2b0feab61ff243cba081f163ad6d6b12da6a92df053c080ca38', true, false),
  (117, 'S4', 4, '최태원 “美 전공정 팹 검토…내년 수급 불균형 최악”', 'c2a656988289b701e10e3535381117be8d8064bfe9555ee10d45dee45c93cea2', true, false),
  (117, 'S5', 5, '- 핵심 요약: 최태원 SK그룹 회장이 미국 내 메모리 반도체 전공정 생산시설 건설 의향을 공식적으로 밝혔다.', '2c70133822cc0c946b9fbd885b8920a01463c7bc324adb51b24a1d2441e743a3', true, false),
  (117, 'S6', 6, '미국 경제방송 CNBC가 13일 공개한 인터뷰에서 최 회장은 추가 건설 계획을 묻는 질문에 기꺼이 할 의향은 있지만 적합한 부지를 찾는 것이 정말 어렵다고 말했다.', 'f326aa6e706c4af4a17d8a09f4ee3d4f128a2a82101ee8c72ac2320dd9d96ae2', true, false),
  (117, 'S7', 7, 'SK하이닉스(000660) 는 현재 인디애나주 웨스트라피엣에 38억 7000만 달러(약 5조 4000억 원)를 투입해 첨단 패키징 공장을 짓고 있다.', '6e687580a1e7c16e1bf8c2f3e1ffecb92dbaa7cbe8bbdd03640b963e44fd7bc9', true, false),
  (117, 'S8', 8, '다만 SK하이닉스는 타이완 TSMC와 미국 마이크론 등 경쟁사가 현지에서 겪는 공사비 급등과 인프라 병목을 고려해 전공정 투자를 신중하게 검토하고 있다.', '1cf64d012107314533df15d5b39828b54690ac437c10987e5ab52f686be78fcd', true, true),
  (117, 'S9', 9, '또한 SK하이닉스는 빅테크와의 협력을 단순 칩 판매에서 고객 맞춤형 HBM(고대역폭메모리) 중심의 장기 파트너십으로 재편하고 장기공급계약(LTA) 확대와 서비스형 메모리 도입으로 다운턴 리스크를 줄인다는 구상이다.', 'aa5cbb03a263528466a8b50607687810576a584ae2bc4daad8451be7d5f0ff7a', true, false),
  (117, 'S10', 10, '‘부동산 거품’ 잡으려다 내수 꺾인 中…韓도 고용부터 타격', 'c2d0d3554ca19f0ce792a10b4df2f02231892f7f098c078ae632d1b4f1700ded', true, false),
  (117, 'S11', 11, '- 핵심 요약: 중국의 첨단제조업이 부동산이 남긴 성장의 빈자리는 빠르게 메웠지만 일자리까지 대신하지는 못했다.', 'f0b8b769123dfa86f744ee6c3aeacd1c046538be91da0a88c2af589a606fe7f4', true, false),
  (117, 'S12', 12, '한국은행에 따르면 중국 첨단제조업의 생산유발계수는 3.6~3.8로 부동산·건설업(2.6)을 크게 웃돌았으나, 동일 규모 생산에 필요한 인력은 건설업이 제조업의 2.2배, 부동산업이 1.5배였다.', '1d04c2b68d2e32121e0f0d76e0d635e6f8eabae68746af93acfda58b5bbd5f89', true, false),
  (118, 'S1', 1, 'SK하이닉스의 지분 가치 상승으로 시가총액 3위에 등극한 SK스퀘어가 그룹 리밸런싱을 마무리하고, 반도체 소부장 및 AI 분야의 대규모 M&A와 신규 투자를 통해 종합 ICT 투자회사로의 본격적인 도약을 준비하고 있다.', '54567f67fad314a65adb4cfacb4e798ebaa31ca1cd131d930e362d14924bc678', true, true),
  (118, 'S2', 2, '자회사 SK하이닉스 덕에 기업가치·실적 ''껑충''', 'ab69772831381ba3ad6302a9ebc9f7beae6da63d640d73698d0e5ee136cc996a', true, false),
  (118, 'S3', 3, '시총 올해 들어 48조&rarr;151조', '25bfb7c7492efd436f4634164fda60234bedac99c4f6302124709e674b95b449', true, false),
  (118, 'S4', 4, '2022년 시가총액 61위의 회사가 3년 반 만인 14일 3위로 기록됐다.', '0d36febfc321e18168b703242839995d21f153a01a90718e0590fbdb06202940', true, false),
  (118, 'S5', 5, '한국에서 더 큰 회사는 삼성전자와 SK하이닉스밖에 없다.', '5bd01af6b58f817a4ea00506d41a26010ba8fc7181a7b4d552c269717d1b9a98', true, false),
  (118, 'S6', 6, '물론 주가가 오른 SK하이닉스의 지분 20%를 보유한 덕분이다.', '25072c7c27d95f5818813cbc335283bfe7f7b7c8d9a094139da9484b25fd52ff', true, false),
  (118, 'S7', 7, '하지만 시장과 주주들 사이에선 “이제는 덩치값을 해달라”는 목소리도 나온다.', '6b1e8512e75223875047499a8485cc236c3eda3e40cc4c41ff9356b1b40f7117', true, false),
  (118, 'S8', 8, 'SK그룹의 사업지주사인 SK스퀘어 얘기다.', 'd91566a4a067cd8f4a24dd3807b8917afefb300effcda387c073ff3216574993', true, false),
  (118, 'S9', 9, '불어난 몸집의 일등 공신은 지분 20.5%를 보유한 자회사 SK하이닉스라는 점은 부정할 수 없다.', 'cb50360b38080c6baa2cf61c32749aa4116ea7c798403d6e2d67410ec8118325', true, false),
  (118, 'S10', 10, '2023년 2조원이 넘는 영업손실을 기록한 SK스퀘어는 2024년 영업이익 3조9206억원으로 흑자 전환했고, 지난해엔 8조7974억원의 영업이익을 낸 배경이다.', '3b36f075cf9b7f223f2db654b3fd6afefa8ec5ebc65880d3bcbcf25c911379a3', true, false),
  (118, 'S11', 11, '올 상반기 영업이익은 27조5137억원으로 집계됐다.', 'a298c0add8964aeca5dd35ab4adea6d1dd6a4af788424ceff19fdd0d0c45a10c', true, false),
  (118, 'S12', 12, 'SK스퀘어 관계자는 “최대 자산인 SK하이닉스와의 시너지가 명확하고 수익 회수가 가능한 M&A로 ‘밸류업&rarr;리밸런싱&rarr;신규 재투자’로 이어지는 사모펀드(PEF)형 전문 투자회사의 선순환 모델을 구축한다는 구상”이라고 설명했다.', 'd147a37f564bd7ef088b4a90da40316ccf8485ccce74b34f6a708ffe2f8dc151', true, false),
  (119, 'S1', 1, '6분기 연속 20%대 영업이익률 달성…상반기 누적 매출 1조4847억원', 'b771f36347bd543da1ed62afad27658deab60a2a2c9d48a5a7a3cf4926772a4a', true, false),
  (119, 'S2', 2, '삼양식품 이 글로벌 시장에서의 ''불닭'' 흥행에 힘입어 2분기 해외 매출 6000억원을 처음 돌파하며 사상 최대 실적을 경신했다.', '47a4d0c6ff7fb9c623676de7f7126cb6b6a25d4a2cb16808d0770271e7b3d139', true, false),
  (119, 'S3', 3, '삼양식품은 올 2분기 연결 기준 매출액 7703억원, 영업이익 1762억원을 기록했다고 14일 공시했다.', 'bd8420a415cc2e4d77bb235dd4c26a9ed4bbf33fbcf80f7d2245c4af9a2df6dd', true, true),
  (119, 'S4', 4, '이는 전년 동기 대비 각각 39.3%, 46.7% 증가한 수치다.', '2993e54df44f255c8bd6b59918bb1acbb02dcaac41f179c2464722cc29f7d781', true, false),
  (119, 'S5', 5, '올 상반기 누적 기준으로는 매출 1조4847억원, 영업이익 3533억원을 달성해 전년 동기 대비 각각 37.2%, 39.0% 늘었다.', '1b250dc82b0fb8917db5d74c4fdbe633b74f6fe3944d607d35ea276d208de256', true, false),
  (119, 'S6', 6, '2분기 해외 매출은 전년 동기 대비 46.7% 증가한 6458억원을 기록하며 분기 기준 처음으로 6000억원을 넘어섰다.', '87165e78a021a24b47a0ed9c334f58ed87c97f84fd7e5385ef631b7183089662', true, false),
  (119, 'S7', 7, '지난 5월 말 누적 판매량 100억 개를 돌파한 불닭 브랜드의 인기가 이어지는 가운데, 밀양공장 등 국내 생산라인 효율화와 현지 유통망 확장이 실적을 뒷받침했다.', 'b22061cf4483b95c58cf77967046fc1aab0f44d7a21be4add5ca894001bf2a9f', true, false),
  (119, 'S8', 8, '해외 주요 법인 모두 두 자릿수 성장세를 나타냈다.', 'd2078098e4ed57247594829fe71b996490ae160b72f0e78bf3afa1d4c1b5eeec', true, false),
  (119, 'S9', 9, '미주 지역은 월마트 등 메인스트림 및 에스닉 채널 입점 확대와 멕시코 등 중미 지역 공략에 힘입어 전년 동기 대비 54% 증가한 2036억원의 매출을 올렸다.', '343bdd8807be28f62e671f0e06db96ca939a518162f5daa98d0bc917092e344d', true, false),
  (119, 'S10', 10, '유럽 법인은 독일과 프랑스 내 판매 호조로 61% 증가한 806억원을 거뒀으며, 중국 법인 역시 간식 채널 확대로 44% 늘어난 1810억원을 기록했다.', '9dca926a66a714995d9e2e46753a194723f1187426169054dafac398f366c901', true, false),
  (119, 'S11', 11, '2분기 영업이익률은 22.9%(약 23%)를 기록하며 지난해 1분기 이후 6분기 연속으로 20%대를 유지했다.', '6cfc7022d9be1ab0103a2e212d3e0133c3e643de15c91ddd5e2192c5d0eae6e9', true, false),
  (119, 'S12', 12, '고수익 권역 중심의 수출 확대와 생산 효율성 제고, 고환율 효과 등이 맞물린 결과다.', '8a885b91f397210bc9dad7e3b0eafa42c017b9ba7585a5d65a78c3cba8f5eb27', true, false),
  (120, 'S1', 1, '젠슨 황 엔비디아 최고경영자(CEO)의 장녀인 매디슨 황 엔비디아 옴니버스·로보틱스 제품 마케팅 수석 이사가 LG전자의 로보틱스 사업 핵심 거점을 찾습니다.', '9469874eaed48b2044239d7bf349f67e5e476b5477377e6c97b642ad4a602c56', true, true),
  (120, 'S2', 2, '구광모 LG그룹 회장과 황 CEO가 미국 엔비디아 본사에서 회동한 직후 엔비디아의 피지컬 인공지능(AI)·로보틱스 사업 핵심 인사가 LG전자를 찾으면서, 두 회사가 로보틱스 분야에서 구체적인 협력에 나설지 주목됩니다.', '767f27f6b9949be14d331dde29d0b2faed027bea0df9189cd9d6aec509c2f4cc', true, false),
  (120, 'S3', 3, '오늘(17일) 업계 등에 따르면 황 수석 이사는 내일(18일) 서울 서초구 양재 연구개발(R&D) 캠퍼스에 LG전자가 구축 중인 데이터팩토리를 방문합니다.', '874516d5fdd115f0c7b1094e1c7c596440c72c5a9656dab6c1bb72d2013c607d', true, false),
  (120, 'S4', 4, '데이터팩토리는 LG전자가 휴머노이드 로봇 지능화를 위한 핵심 인프라입니다.', '0eaaffbc59e418c5ab9302e5aca9c622d0f2a1df0889390752a19fb03df8833a', true, false),
  (120, 'S5', 5, '가정과 공장 등 현실과 유사한 환경에서 로봇이 동작 경험 데이터를 학습할 수 있도록 하는, 일종의 ‘로봇 훈련소’입니다.', 'b34d738fc71bd04497279b93234864d2ff1425303eb6909e92d81594f0f3211f', true, false),
  (120, 'S6', 6, '이번 방문은 황 수석 이사의 아버지인 황 CEO와 구 회장이 지난 13일 미국 캘리포니아주 샌타클래라 엔비디아 본사에서 만나 ‘전략적 사업협력을 위한 업무협약(MOU)’을 체결한 지 불과 며칠 만에 이뤄지는 것입니다.', '8c739fec0c3226d16d163b2aa9f67940717e055c7e17c589207574b00ddad38f', true, false),
  (120, 'S7', 7, 'MOU에 따라 LG전자는 내년 1분기 공개를 목표로 엔비디아 플랫폼을 활용한 이족보행 휴머노이드 로봇을 개발하고 있습니다.', '83556766a46f4d100f3ba80962866cf400d445a03a2c7ee42fd445b2f8932962', true, false),
  (120, 'S8', 8, '이 로봇에는 엔비디아의 로보틱스 칩 모듈 ‘젯슨 토르’가 탑재되며, 휴머노이드 파운데이션 모델 ‘아이작 그루트’와 로보틱스 안전 시스템 ‘헤일로스 포 로보틱스’ 등도 활용될 예정입니다.', 'b39c59924cdf9a66435d53f22d800e12643f00d365a443a33413cde92db3adfc', true, false),
  (120, 'S9', 9, '황 수석 이사는 2020년 엔비디아에 입사한 뒤 피지컬 AI 생태계 확장을 위한 제품 마케팅을 담당해 왔습니다.', '6858a963f70a96749bbe2cde513c4cdd716ec13ef52ae87d0c518d3ff31e258f', true, false),
  (120, 'S10', 10, '앞서 지난 4월에는 서울 여의도 LG트윈타워에서 류재철 LG전자 CEO와 만나 피지컬 AI 분야 협력 방안을 논의했습니다.', '206da9de688ee6ed9570ccf3c662144123d07f41510c99383df163a7de0c2948', true, false),
  (120, 'S11', 11, '지난 6월 황 CEO의 방한 당시 구 회장을 비롯한 국내 주요 기업 총수들과 가진 이른바 ‘2차 깐부 회동’에도 동행했습니다.', 'f115ecdec75c37e8b3ada686f015c712cb978e15cdd0b4d4edc9ed881e7cc485', true, false),
  (121, 'S1', 1, '비비고 만두·누들 등 ‘K푸드’ 생산', 'bcafeb0a6a97d44813d8d824f037479c21972fe679225822ef8c9f1615f08d18', true, false),
  (121, 'S2', 2, '韓 음식 ‘기본 틀’… 현지화 덧입혀', '20491f53885d2de9386322952af9d175de6e764a671c575772ab9ef49c889663', true, false),
  (121, 'S3', 3, '"비비고는 미국 내 한국 음식 카테고리에서 1등을 하는 브랜드입니다"', '62e8daaa295e9d9e6ea69f52a4b1b7ed6a15dfa6ab6d30282f665e4c38867529', true, false),
  (121, 'S4', 4, '미국 LA 시내에서 약 1시간 30분가량 떨어진 곳에 CJ제일제당의 보몬트 공장이 있다.', '93e3c98c24d58d4957a66b1fdf1aabe9b01b12853ca5c40b07578ba0dce68ce8', true, false),
  (121, 'S5', 5, '이곳은 2019년 설립 이후 비비고 만두와 볶음밥, K소스, 누들, 김스낵 등을 생산하고 있는데 만두 생산량만 하루 약 160t, 86만개 달한다.', 'a4f4e74eea2d6664640c6c2e0219a42a77956fb46914182a4dc9adc353165ed0', true, false),
  (121, 'S6', 6, '14일(현지시간) 보몬트 공장에서 만난 멜리사 톰슨 CJ슈완스 아시안식품 제조 담당 부사장은 "이곳에서는 1년에 약 6만t가량의 음식을 만들어 내고 있으며 미국 내에서 아시아 제품을 가장 많이 만들고 있다"고 강조했다.', 'f373b313fee15b98b7952a1e571a2e5393fdf6cd973e292c77afc799d957e4a3', true, false),
  (121, 'S7', 7, '미국 캘리포니아주 보몬트시에 있는 CJ제일제당 보몬트 공장 전경.', '8ac2e2f2975830f5de2e1c2fad636ba8d19bc81caa85d05fa22b43d89dee8f6c', true, false),
  (121, 'S8', 8, '특히 2019년 냉동식품 기업인 슈완스 인수를 기점으로 양사의 B2C 유통망 통합 시스템을 구축하면서 슈완스가 미국 전역에 갖춘 물류 시설과 유통망을 활용, 만두를 비롯한 비비고 K푸드는 현재 월마트와 크로거, 코스트코 등 주요 유통 채널을 포함한 약 8만여개의 매장에서 판매되고 있다.', '1b6da0d83a1742fd3d274e6400e497ebce5ab9cd647e981bd8631d75a680fcbf', true, false),
  (121, 'S9', 9, '보몬트 공장은 CJ제일제당이 미국에서 보유 중인 20개의 공장 중 핵심 시설로, 미국 시장을 공략하는 전초기지 역할을 수행하고 있다.', '075b50cad6444b94d4279fa9a1e1e29cd434c9301676f5669f741c1417cf414b', true, false),
  (121, 'S10', 10, 'CJ제일제당은 비비고 만두의 성공을 바탕으로 늘어나는 현지 수요에 대응하기 위해 내년 완공을 목표로 미국 사우스다코타주 수폴스에 부지 면적 57만5000㎡의 신공장을 건설하고 있다.', 'a126f702f45368db2c0ebb870ad216b06d60291552879aaffb0ba9e745d4bcd6', true, true),
  (121, 'S11', 11, '축구장 약 80개를 합친 규모로, 북미 최대 규모의 아시안 푸드 제조시설이 들어설 예정이다.', '3b6da1aeaa7cbe16c4d3f4f9feebe4ccf6a07b17d6892815f6d51c98229c88fc', true, false),
  (121, 'S12', 12, 'CJ제일제당은 북미 식품 사업 매출 중 80% 이상을 미국에서 거두고 있다.', '9afdb6a914ceb7cf6d7d54bb80f448f17eb7f3b003049783edf539ddcf15b4fd', true, false),
  (122, 'S1', 1, '와이지엔터테인먼트가 2분기 시장 기대를 웃도는 실적을 내놓으며 하반기 성장에 대한 기대감을 키우고 있다.', '9506bdef18e8605bdec7632acf4781c5b6615e5ac9a938716dbb9ece07f30d5a', true, false),
  (122, 'S2', 2, '교보증권은 최근 보고서에서 앨범과 공연뿐 아니라 굿즈 사업까지 성장세를 보이면서 하반기 실적 모멘텀이 한층 강해질 것 이라고 밝혔다.', 'd46148180454d194b760e8e4f682ff1a1f859184bddeac2f9aa412fa8e15383a', true, false),
  (122, 'S3', 3, '와이지엔터테인먼트의 2분기 연결 기준 매출액은 1278억원으로 지난해 같은 기간보다 27.2% 증가했다.', '813dc87c018df18955d0cd644342102e62ceb3bd486210d817907a6fd979d564', true, true),
  (122, 'S4', 4, '영업이익은 110억원으로 31.2% 늘었고 영업이익률은 8.6%를 기록했다.', 'e4e1d613e77f6ebd8fa310d8d7dcf35a7cce9e85861c80bd3a80c7be0671da02', true, false),
  (122, 'S5', 5, '영업이익은 시장 기대치인 88억원을 웃돌았다.', '68f6ea76a9d543c7a2e0916e9d44b773d41d15e6d02b18d0c6c573d46a342e1a', true, false),
  (122, 'S6', 6, '단순히 매출이 늘어난 것에 그치지 않고 이익 증가까지 이어졌다는 점에서 엔터테인먼트 사업의 수익 구조가 개선되고 있다는 평가가 나온다.', '253cde83311962710c0524d0faf0c703f7e1501f5e4d19af9ee1ec08707d3f12', true, false),
  (122, 'S7', 7, '2분기 실적에서 눈길을 끈 것은 굿즈 사업이다.', 'd56a1a0e5c12dda4089968409137bddbe19bd310b0a63d343dae8a730ea2d117', true, false),
  (122, 'S8', 8, 'MD·굿즈 매출은 282억원으로 지난해 같은 기간보다 46.9% 증가했고 전 분기보다도 37.6% 늘었다.', '082b58556fe094cf61ec1083d048e7a3084d210e1019e560093330f233f5692e', true, false),
  (122, 'S9', 9, '트레저 미니 4집이 약 106만장, 베이비몬스터 미니 3집이 약 81만장의 판매량을 기록하면서 앨범 매출 증가에 힘을 보탰다.', '19a9b101b6bf9043b2ff9bdbb87eb7136ac071fc2221caaa0ab2c0e38fcb4c16', true, false),
  (122, 'S10', 10, '1분기와 비교하면 앨범 매출은 감소했다.', 'b7453382995ca038b9ae316fdb49bdd4a6787b3cf53373402e37fa092f5d3270', true, false),
  (122, 'S11', 11, '1분기에는 블랙핑크 미니 3집이라는 대형 아티스트의 활동이 실적에 반영된 기저효과가 있었기 때문이다.', 'ef0723c92d5e17ed4f4339dd2bc23372dc8d946d94ae0b41c19d14f3ee86cd4a', true, false),
  (122, 'S12', 12, '1분기 블랙핑크 활동으로 앨범 매출이 크게 늘었다가 2분기에 감소한 것도 같은 이유다.', '7a703728fcd994228990df382131983eaa1c45f71e5db8ab082f8fd5a4f7e1e2', true, false),
  (123, 'S1', 1, '[스포츠서울 | 조선우 기자] 오리온이 중국·베트남·러시아 등 해외 법인의 성장에 힘입어 상반기 매출과 영업이익 모두 두 자릿수 증가를 기록했다.', 'f181fe07e83b767316c990e93285c1bca54f61feab04cb9b8763384452fb512f', true, false),
  (123, 'S2', 2, '오리온에 따르면 올해 상반기 연결 기준 매출이 전년 동기 대비 15.5% 증가한 1조8239억 원, 영업이익은 17.9% 늘어난 2980억 원을 기록했다.', '418e463f245e34a87865936e98a3bc85289d9c325e1c10803b137048a165fe2b', true, true),
  (123, 'S3', 3, '중동 전쟁 장기화로 에너지 비용과 물류비, 원부자재 가격 등이 상승한 가운데 현지화 제품 확대와 성장 채널 공략을 통해 해외 법인들이 실적을 견인했다.', '23cadeb94d1dba73f19ccd23d3e1011d6a08c6ff0638bf88a210a16c62f46931', true, false),
  (123, 'S4', 4, '중국 법인은 매출이 24.4% 증가한 7877억 원, 영업이익은 33.7% 늘어난 1447억 원을 기록했다.', '8e2a4a7828fbb60d876cf8470a51e4a7ac1c69c1e84f5edbe408807f3840e9ad', true, false),
  (123, 'S5', 5, '춘절 이후에도 판매량 증가세가 이어진 가운데 간식점 등 성장 채널 전용 제품과 감자스낵 판매 확대가 실적을 뒷받침했다.', '2b37e0e24d68237a04e96d17a771ee820e21b5f42a6788da92dc2342d8a8f287', true, false),
  (123, 'S6', 6, '베트남 법인도 ‘뗏’ 명절 이후 이어진 수요와 쌀과자 등 신제품, 여름 한정판 파이 출시 등에 힘입어 매출 2677억 원, 영업이익 410억 원을 기록하며 각각 15.9%, 15.2% 증가했다.', '773e0b3058fb03d89cae49945ae36e5f4b638d5038aa5b623db29a82865d1bca', true, false),
  (123, 'S7', 7, '러시아 법인은 초코파이를 비롯해 수박파이, 후레쉬파이, 참붕어빵, 초코송이, 젤리 등 제품군을 확대하며 매출 1955억 원, 영업이익 296억 원으로 각각 32.1%, 62.2% 성장했다.', 'd0aa9713cb7dddbb8d2469518db94b05d8bd82d8f19e4810277cea4d3e842581', true, false),
  (123, 'S8', 8, '반면 한국 법인은 매출이 1.7% 증가한 5834억 원을 기록했지만 제조원가와 판매관리비 상승으로 영업이익은 5.4% 감소한 897억 원에 그쳤다.', '01432e8266bc1a9aaa1652cc54a5669b220c77f84e02273a711baaee8f49ae66', true, false),
  (123, 'S9', 9, '오리온은 늘어난 수요에 대응하기 위해 해외 생산 기반 확대에도 나선다.', '83c39ae8f3eed22d10132c979945d533190ed1eee71981aa6be4947231f65b1a', true, false),
  (123, 'S10', 10, '한국 법인은 4600억 원을 투입해 2027년 하반기 완공을 목표로 진천통합센터를 건설하고 있다.', '036ed70183d887e9df20e37266180a9dfa03103316936b64a75493b2ac749b5b', true, false),
  (123, 'S11', 11, '러시아는 2400억 원을 투자해 트베리 신공장동을 짓고 있다.', '801c6a3bf648bfd7f6ae3da3586d69db7dbd5ac914b5a76928cc351f958294b6', true, false),
  (123, 'S12', 12, '오리온 관계자는 “국내외에 스낵, 파이, 젤리 신규 라인이 하반기에 본격 가동되고, 순차적으로 글로벌 생산시설이 확충되면 성장세는 가속화될 것”이라며 “이를 통해 매출 5조 원, 영업이익 1조 원 달성을 앞당길 것으로 기대한다”고 말했다.', 'd4b8b86e9d1467891ffd5b5df01b8c9bb89aa370b3ffa54e58544c67b38c826c', true, false),
  (124, 'S1', 1, '크래프톤 매출 1.29조·영업익 4109억', '8852d8b6ba91ce7bf4dc599007788a36e9aad21b90ee93f772207f00ab01b07b', true, false),
  (124, 'S2', 2, '넥슨 매출 늘었지만 영업익 17% 감소', '6006dbde2502fddfab77dc35ca9e25b2e04424fe35e71d1b0d46bcb45d6cdd67', true, false),
  (124, 'S3', 3, '넷마블도 영업익 21% 줄어…수익성 희비', 'b9c48cd871170a7be69621cde734515e71d5910d2b037e740575a73fbcbc5e84', true, false),
  (124, 'S4', 4, '넥슨이 2분기 국내 게임사 실적 1위 자리를 크래프톤에 내줬다.', '303f4bcf6b5d3f4ee0868c01991073793129041e3213091f66d05bfb5e9593e3', true, true),
  (124, 'S5', 5, '‘PUBG: 배틀그라운드’를 앞세운 크래프톤이 매출과 영업이익 모두 넥슨을 추월하면서 ‘3N+1K’(넥슨·넷마블·엔씨소프트·크래프톤)로 불리던 게임업계 구도도 ‘1K+3N’으로 재편되는 모습이다.', '5d66d294a2ef6def4df9c992c38201b2822431d1d1f8e7cb6c5de397414b5a7a', true, false),
  (124, 'S6', 6, '17일 게임업계에 따르면 크래프톤은 2분기 매출 1조2902억원, 영업이익 4109억원을 기록했다.', 'ac8589be6e7565a46d60366fe51cc9b7750343d858df15d6c38e6129c2bc3816', true, false),
  (124, 'S7', 7, '전년 동기보다 각각 94.9%, 67% 증가했다.', 'e116ab9ab0b307c43eb58b109e4f510bad7f4a79ad392e77f60a4b5accf2ccf0', true, false),
  (124, 'S8', 8, '매출은 2배 가까이 늘었고 영업이익도 1600억원 이상 증가했다.', '70bed154d62da44921582349642093de32e917a8c84014b23a9f47b5ad645500', true, false),
  (124, 'S9', 9, '넥슨은 같은 기간 매출 1211억엔(약 1조1390억원), 영업이익 313억엔(약 2943억원)을 기록했다.', 'd3d2e80f720f1dc1ff96929ca9986989b35b5e903fa05d5b6f0f438f5dfe636c', true, false),
  (124, 'S10', 10, '2분기만 놓고 보면 크래프톤이 매출과 영업이익에서 넥슨과 넷마블을 모두 앞섰다.', '3554033cfc542ea92fef946dbc887ef0930157ffc9bcda66d721a50db4f7f380', true, false),
  (124, 'S11', 11, '크래프톤은 전체 매출의 대부분을 해외에서 거두고 있다.', '48ced8b9cc183b91d9d6832e6ae22ad84fa7b97fe9bdbabc0a56585eb35b49f5', true, false),
  (124, 'S12', 12, '해외 매출 비중이 높은 크래프톤과 넷마블뿐 아니라 넥슨도 주요 IP의 글로벌 확장에 힘을 싣고 있다.', 'dfbf3e89f6ad9e743d7219eb41513cbfc9642cdb70be17e29aa4b2c60129238c', true, false),
  (125, 'S1', 1, '넷마블의 방치형 RPG ''스톤에이지 키우기''가 하나은행과 손잡고 게임과 금융을 결합한 제휴 이벤트를 선보인다.', 'b199c0db8bc165b2746e7fd2cf73e45fb540295d7cc7c9cfa89899b9a0d14963', true, true),
  (125, 'S2', 2, '넷마블은 모바일 방치형 RPG ''스톤에이지 키우기''에서 하나은행과 함께하는 제휴 이벤트를 오는 9월 30일까지 진행한다고 밝혔다.', '60a4b9842b67d216cbb00fbd678fdcd2216a33b0884427608651cffce8b6821b', true, false),
  (125, 'S3', 3, '이벤트는 하나은행 모바일 앱 ''하나원큐''의 ''놀이터'' 페이지에서 진행된다.', '41df096de36e36b6daf81998079c7d31ab80b20cfcaeb301c1c490e2ff581989', true, false),
  (125, 'S4', 4, '하나원큐 이용 등록을 마치고 ''돈통''을 보유한 만 14세 이상 고객이라면 참여할 수 있다.', '161d1b8c9b1da19469e8df7bc5e2693f0766f731fca9f9bde9b1540719037cc9', true, false),
  (125, 'S5', 5, '이용자는 이벤트 페이지에서 하나은행 캐릭터 ''별돌이''와 함께 공룡알을 찾는 방식으로 이벤트에 참여할 수 있다.', '66e6e391d3722dc1536de0463c92a5a37a62fbc5edfdb4d2a854d20d160ee291', true, false),
  (125, 'S6', 6, '참여 보상으로 ''스톤에이지 키우기''에서 사용할 수 있는 블루젬 2000개와 최대 5만원 상당의 하나원큐 랜덤 캐시를 받을 수 있다.', 'e663b2ae5c30e6f5c3cbb3c556a0d5d3d87161b5dc7fe34e0b79e019db1c7b3b', true, false),
  (125, 'S7', 7, '이벤트 참여는 1인당 한 차례로 제한된다.', '0c4c3445e6cd028bae4b6e7b96c3862a5461499341e3127e34b8d79f6c8ea29f', true, false),
  (125, 'S8', 8, '이번 협업은 게임사가 금융 플랫폼의 이용자 접점을 활용해 게임 아이템과 금융 서비스 혜택을 함께 제공하는 사례다.', 'c80066ea917bd4dd249cbd35b4cd0e9693a9e5b28da789c8757c0a8801b9c156', true, false),
  (125, 'S9', 9, '하나은행 역시 게임 이용자를 대상으로 한 계좌 기반 결제 혜택과 공동 프로모션 등으로 협력 범위를 확대할 계획이다.', '1f5b4e359bcab5a9fb013d383805acf185f6f0ae69187c119ef69ccdc3cfc9d5', true, false),
  (125, 'S10', 10, '지난 3월 출시된 ''스톤에이지 키우기''는 누적 이용자 2억명을 기록한 ''스톤에이지'' IP를 활용한 방치형 RPG다.', '09dc90e3dc036dd6c74c23a2a0b2fdea949c8a709f47f1cea95cfb717ec41b47', true, false),
  (125, 'S11', 11, '6명의 조련사와 18종의 펫을 조합해 최대 24기의 군단을 구성하고, 간편한 조작으로 전략적인 전투를 즐길 수 있도록 설계됐다.', 'be82ad669eacf3986860150ffa888e41de851046673a775bf2a8dae950c01b6c', true, false),
  (126, 'S1', 1, '더블유게임즈가 2분기에도 안정적인 이익 성장세를 이어갔다.', 'a7ac37538a3f31f4f3d56cb0dec87955762c75489cce5e62a82eb8640e5fc89b', true, false),
  (126, 'S2', 2, '하나증권은 최근 보고서에서 다만 환율과 해외 규제 비용 등의 부담을 고려하면 외형 성장에 비해 실적 개선 폭이 다소 아쉽다고 평가했다.', 'df5392432e7277331e035bfc160d8f79b80801739ee3a9f9cda79bc342f1d2bc', true, false),
  (126, 'S3', 3, '더블유게임즈는 2분기 연결 기준 매출액 2,106억원, 영업이익 701억원을 기록했다.', 'bb1947c86ba682da38f7554c9e1d9d6a2da837dd6f1cbdece1d1dfac9b48f5bc', true, false),
  (126, 'S4', 4, '지난해 같은 기간보다 매출은 22.5%, 영업이익은 29.0% 증가했다.', '403f3cf20aae039bdd8e85b8493112d08c8e1d507781bedfaf9eb591323bd9f3', true, false),
  (126, 'S5', 5, '전분기와 비교해도 매출은 2.8%, 영업이익은 2.3% 늘었다.', '0f9accaf32faad11037f5e7a81c9fdd281c9a9e4ba2314947db5a68f1f0e42f0', true, false),
  (126, 'S6', 6, '영업이익률은 33.3%로 높은 수익성을 유지했다.', '6dd898559a7f7107877bd6bc3905d29ad114ec15f8a78cbf9dfbf69482cea642', true, false),
  (126, 'S7', 7, '회사의 핵심 사업인 소셜카지노와 아이게이밍, 캐주얼 게임이 고르게 매출을 뒷받침하면서 외형 확대와 수익성 개선이 동시에 나타났다.', 'a32187c42db014428b540191e6a85569707de31612905288b6a9b967fb16986e', true, false),
  (126, 'S8', 8, '결제액 자체는 감소세가 이어졌지만 직접판매 방식인 DTC 매출 비중이 크게 높아진 것이 실적을 방어했다.', '7643ef97ddae2a022c96de00101db9bb116780d1bbe25406341a71460af2c5fc', true, true),
  (126, 'S9', 9, 'DTC 매출 비중은 47.5%까지 확대됐다.', 'd8492b5bed6ae6b56f3704ae874b02ce102a80fb972c79d02deedcb30e0cad3e', true, false),
  (126, 'S10', 10, '팍시게임즈의 AI 랩을 기반으로 출시된 신규 게임의 매출 비중이 81%까지 확대되면서 새로운 성장 가능성을 보여줬다.', '1e82a731a74d3ca78543188e1327fb6dbc6583b66aaea155c51c4b56d256ce7b', true, false),
  (126, 'S11', 11, '해외 규제에 따른 비용 증가도 수익성을 압박했다.', 'd8e75f556e066273e7973990b52d5a98a2601bddb26e96a0f81fdcf603c21405', true, false),
  (126, 'S12', 12, '다만 DTC 매출 확대를 통해 높은 이익률을 유지하고 있다는 점은 긍정적인 요소로 꼽았다.', '28693916802fa4336e11bf6618d1c8315bf9525aeefe094f5827009f888c1239', true, false),
  (127, 'S1', 1, '농심이 탄산음료 웰치스와 배틀그라운드의 여름 시즌 협업을 진행한다.', '2284673714f8fee06d41181b06a9c77c09f13331e130eae155537542a3f306ed', true, true),
  (127, 'S2', 2, 'PC방을 중심으로 게임 이용자들에게 친숙한 웰치스와 배틀그라운드의 시너지를 통해 소비자와의 접점을 확대한다는 계획이다.', '5496f9510f1b416553f182ce9d9558c5a7494c9130f60c5ceff85f7c84100b07', true, false),
  (127, 'S3', 3, '먼저 농심은 배틀그라운드 디자인을 적용한 ''웰치스 포도 PUBG 에디션''을 기간 한정으로 선보인다.', '002e9203c5e69881c2a691b4ba7a230d77becbb283b23816081f001b0d404a40', true, false),
  (127, 'S4', 4, '제품 패키지에 배틀그라운드 게임 디자인 요소를 적용해 게임 팬들에게 색다른 재미와 소장 가치를 더했다.', 'a1dd3489e6c3760cfb3fc21bdff92d46e56a0c0a2127383d6a76d631ede35fb1', true, false),
  (127, 'S5', 5, '해당 제품은 전국 유통점에서 구매할 수 있다.', '6c89922b8cfab5e9420331befb9330d940f5c549a880b5003a72b6bc385426df', true, false),
  (127, 'S6', 6, '협업을 기념한 한정판 ''웰치스 X PUBG 보급함'' 기획세트도 출시한다.', 'dc9ae9d6622f796277ca1b587be7e05c826b8e90fafa5dd3a7c47fa7f9a4fcdf', true, false),
  (127, 'S7', 7, '게임 속 ''보급함''을 모티브 로, 웰치스와 한정판 굿즈, 게임 아이템 쿠폰 등으로 구성했다.', '4d5d66148036f420e5fba1a2f6e3edda1f3a9c5a0fb59053917a35944f0ec8af', true, false),
  (127, 'S8', 8, '보급함 세트는 8월 14일 오전 11시부터 농심 자사몰 ''농심몰''에서 한정 판매한다.', 'a3fed10508b80896a560e90b730809955dbe75f3cd39d62dd5dcea7589c627d8', true, false),
  (127, 'S9', 9, '또 9월 초 ''웰치스배 배틀그라운드 대회''도 개최해 이용자와 크리에이터를 대상 으로 웰치스를 알릴 계획이다.', 'b5a79135e3e59dc56b39a71480af55c3701e1bd0dbc8ccd4af80a3574a6e72df', true, false),
  (127, 'S10', 10, '본지와 전화 통화한 농심 관계자는 "PC방 대표 음료 웰치스가 배틀그라운드와 함께 제품 구매부터 오프라인 체험, 게임 대회까지 브랜드를 재미있게 즐길 수 있는 다양한 프로그램을 준비했다"고 말했다.', '1f1d89e172b2c925690ca511eb71bddda0d43bd933c2aa4b237996843255b156', true, false),
  (128, 'S1', 1, '현대자동차·기아의 글로벌 친환경차 누적 판매량이 올해 말 1000만 대를 돌파할 전망이다.', 'f9cf2b842feb8d9f956be232c6ca966b6663cf97ecf56fc24fcd7c173c779c53', true, true),
  (128, 'S2', 2, '2009년 현대차 아반떼 하이브리드와 기아 포르테 하이브리드 출시 이후 약 18년 만이다.', 'dd93f15ffac4a40b53b1706c55076029ea5dda160fc9d98d6a38cbe265ba884d', true, false),
  (128, 'S3', 3, '전기차 캐즘(일시적 수요 정체) 국면에서도 하이브리드를 안전판으로 키우는 동시에 전기차 신차 공세를 병행한 투트랙 전략이 주효했다는 평가다.', '326f64d96c17083a9483760ca6a25c0fc7716629ce8e5cab23c77f7d82e4f949', true, false),
  (128, 'S4', 4, '17일 자동차 업계에 따르면 올해 상반기까지 현대차(005380) · 기아(000270) 의 친환경차 누적 판매량은 922만 9837대로 900만 대를 넘어섰다.', '49894e3c89eedbfbcbc23789644add44352db79ab3e1bdb8a34ca937244836a1', true, false),
  (128, 'S5', 5, '현대차(제네시스 포함)가 490만 4763대, 기아가 432만 5074대를 기록했다.', 'e8e6d0e3486167589848c8039e5a0cb4446bab032dfc98c130d3354707a760e9', true, false),
  (128, 'S6', 6, '유형별로는 하이브리드차가 562만 3312대, 전기차가 279만 4248대, 플러그인 하이브리드가 76만 2633대, 수소전기차가 4만 9644대를 차지했다.', '0fbd52f26dae34dfa4f427974d14a8ee1bf7cb7de6ea4260e16520ecab2d1035', true, false),
  (128, 'S7', 7, '하이브리드 부문에서는 현대차 투싼 하이브리드 판매량이 85만 4535대로 가장 많았고, 기아 니로 하이브리드(80만 5041대), 스포티지 하이브리드(65만 8800대), 쏘렌토 하이브리드(48만 4631대), 현대차 싼타페 하이브리드(43만 3872대)가 뒤를 이었다.', '7cf507160e34832b497b4b1923023689432ea063677b6299d90f1d233f605b2f', true, false),
  (128, 'S8', 8, '전기차 부문은 현대차 아이오닉 5(51만 1707대), 코나 일렉트릭(45만 1593대), 기아 니로 EV(33만 2640대), EV6(30만 9522대), EV3(19만 3187대) 순으로 집계됐다.', 'e4b9b5a92ed826aeafadce6d8cf5017226e1a89ba5cc627dc9d0919e3560ebca', true, false),
  (128, 'S9', 9, '판매 증가세는 매년 가팔라지고 있다.', '7653c91634a5e5d3130a2284f8adcabd86c00e0580146145f6d8ce539f300112', true, false),
  (128, 'S10', 10, '현대차·기아가 처음 친환경차를 선보인 2009년 연간 판매량은 6312대에 불과했다.', '89267677a4649210824c34d297b87ffc81c5e5c47f78b8094c6cce1555f76446', true, false),
  (128, 'S11', 11, '하지만 2016년 12만 8976대로 연간 10만 대 고지를 밟았고, 2022년에는 102만 196대로 100만 대를 넘어섰다.', 'f1ef714a8d137aa5dad35a314b83ecbef2f6d45237720d6f232cf92237df68b4', true, false),
  (128, 'S12', 12, '이 경우 역대 누적 판매량 1000만 대 달성도 무난할 것으로 관측된다.', 'a5768d52d70d54c5e6d4e9c7d6c2778e3aaff20a09b04e52c1c34de7ce9818af', true, false),
  (129, 'S1', 1, '美 인센티브 기아 2550달러·현대차 3650달러', 'd7c069c39eb9e0c31b8a3b86a968ba6d3d7f3e1a0207147769fcbb598c341402', true, false),
  (129, 'S2', 2, '판매가 대비 비중도 6.6% vs 9.0%', '418531bf4261e1185a9e5122a6107cb1858aba0e79a97761c83ab3e5166ac49a', true, false),
  (129, 'S3', 3, '재고일수 39일…현대차보다 14일 짧아', '4677fb351443e844b87a0fdb2113e679cdb715b131df385e814e473c5debac34', true, false),
  (129, 'S4', 4, '[헤럴드경제=정경수 기자] 기아가 올해 상반기 미국에서 현대차보다 차 한 대당 1100달러(약 150만원) 덜 깎아주고도 주요 차급에서 더 많이 팔았다.', 'f83518cfebf8ed06b49028a1551695262121c493426d864883f4877ca0abba0a', true, true),
  (129, 'S5', 5, '전체 판매량은 아직 현대차가 앞서지만 K4·K5·텔루라이드 등 대표 차종에서는 기아의 우위가 두드러진다.', '8b2f1edb3431202470aa89eb80db9f7f6161ea9196a8641dfbbfefbcafea6297', true, false),
  (129, 'S6', 6, '할인에 기대 판매를 늘리던 과거와 달리, 가격을 지키면서도 판매를 키우는 브랜드로 위상이 달라졌다는 평가다.', '06b2145fbc512287e672d485fecabc44375226a57b9e8860fc77bbd5ef348101', true, false),
  (129, 'S7', 7, '17일 한국투자증권과 자동차 시장조사·데이터 업체인 Autodata와 J.D.', '3ff29d7cb7c62ed2e8a03a81151bcac96efe9330ed7f20700502c474d5481779', true, false),
  (129, 'S8', 8, 'Power, GlobalData 등의 자료를 분석한 결과 올해 상반기 기아의 미국 시장 대당 평균 인센티브는 약 2550달러(360만원)로 집계됐다.', 'd924d3bcccade572571a6da4a8758c5e5ec1d767c3cf84afec6d0b2f9253f901', true, false),
  (129, 'S9', 9, '현대차는 제네시스를 포함해 약 3650달러(520만원)로, 기아보다 1100달러 높았다.', '9b30f56672ccf865495bc327925c5e3d3d91ca5ae41ee89942b07f843a418a8b', true, false),
  (129, 'S10', 10, '미국 완성차 업계 평균인 약 3300달러와 비교해도 기아의 인센티브는 20% 이상 낮은 수준이다.', 'a0930040d3c875a8a19b0f165fb47e6032d6d96dac2ec479b259942542cce14c', true, false),
  (129, 'S11', 11, '올해 상반기 미국 시장에서 기아 판매 증가율은 전년 동기 대비 3.4%로, 현대차의 2.7%를 웃돌았다.', '4a999e883e312e2246c8f85f404225460b7a2a8fc16c28eb6ee56e25a0f5cb8a', true, false),
  (129, 'S12', 12, '올해 상반기 미국 시장에서 기아의 평균 재고일수는 39일로 현대차의 53일보다 14일 짧았다.', '6d22157c7133c22d24a5695ca4395b1485fd1b2e8d9dc54be05ed7ac3d0eb731', true, false),
  (130, 'S1', 1, '투명우산 나눔, 누적 배포 160만개 육박', '407582f982ee49d6e04a16d69032e5ac67724c1d9149d19b3ec441ceb8e21412', true, false),
  (130, 'S2', 2, '시야 확보에 좋고 비상 호루라기도 부착', '8ff3f7dd32ae230e8f6a6d8a9df937d7140a6a8c03cf40eb83f14a21308a7ae8', true, false),
  (130, 'S3', 3, '비오는날 어린이 교통사고 30% 감소 효과', '6f747a5e3837863327801ccbf6b81b12f35d3ee44c0a97a2708214b404965865', true, false),
  (130, 'S4', 4, '환경·지역 위한 다양한 사회공헌 이어가', '9e696674d4c82728560b1325ab87a27e6e9d42be17a684f0a24b5f63a287e56e', true, false),
  (130, 'S5', 5, '현대모비스가 17년째 투명우산 나눔을 이어가며 어린이 보행안전의 대표 주자로 자리매김하고 있다.', 'a935168abf5e97091e73e3eeb88bbd34b29aac8ef8e9c4663b1a3d9022a468ec', true, true),
  (130, 'S6', 6, '자동차 부품 전문기업이 안전을 화두로 한 사회공헌을 십수 년간 지속하는 사례는 흔치 않은 가운데, 현대모비스는 교통안전을 넘어 생활 전반의 안전 문화를 뿌리내리는 데도 힘을 쏟고 있다는 평가다.', '4948da3d01074289a555eb4834839c150571628d34204ae5d15d1b195431da1d', true, false),
  (130, 'S7', 7, '17일 업계에 따르면 현대모비스는 2010년 어린이 교통안전 문제 해결을 목적으로 투명우산 나눔을 시작해 2019년부터는 전국 단위로 사업을 확대했다.', 'cf33adde3ce1b22cadb51d1d7826cf13598c4658773a8dfef6beb7e54f087ff9', true, false),
  (130, 'S8', 8, 'AS대리점과 협력사를 통한 나눔은 물론 개인 신청과 학교 공모, 지역사회 나눔 등으로 배포 경로를 꾸준히 넓혀온 결과, 우산을 전달받은 학교는 3400곳, 누적 배포량은 160만개에 이르며 매년 10만개 이상이 새롭게 나가고 있다.', '7ca7f6432c641e7e03dc1be25ef6476baa70a69e408ab0cf69451dc3c5caaf14', true, false),
  (130, 'S9', 9, '투명우산은 우산을 쓴 어린이의 시야를 가리지 않으면서도 야광 소재를 적용해 운전자가 아이들을 쉽게 알아볼 수 있도록 설계된 것이 특징이다.', '0ee0354bb741f33cf592fb61c0c60e2ee30ef25d19bc623544211f4af2d49de2', true, false),
  (130, 'S10', 10, '현대모비스에 따르면 이 나눔 활동으로 비 오는 날 어린이 교통사고를 30% 가까이 줄이는 효과가 확인됐다.', '2bb0d5bf9f53432631a761f3b3250b5eee5fed83355c3106ae735d3f00631f0a', true, false),
  (130, 'S11', 11, '현대모비스는 안전을 사회공헌의 핵심 가치로 삼아 도로 위 차량과 탑승자, 보행자를 위한 연구개발에 그치지 않고 안전한 일상 환경을 조성하는 데도 힘을 보태고 있다.', '76b47be2417cf039bc962c6279732d84142f098267d9899a7801b9f337fefc18', true, false),
  (130, 'S12', 12, '주니어 공학교실, 장애아동 가족여행 지원 등을 비롯해 임직원과 함께 소화전을 도색하는 봉사활동은 최근 누적 1000개를 돌파했다.', '040e136418437578c155d5c5e080099f6051e581784175e6cbf88e19790aba07', true, false),
  (131, 'S1', 1, '‘하이브 라틴 팝 그룹’ 산토스 브라보스(SANTOS BRAVOS)가 LA 크립토닷컴 아레나를 흔들어 놓으며 팬들의 떼창을 이끌었다.', '4ad6679538a5adff82381a6d820eb859b9752420011bcdee2d23afdbd338048b', true, true),
  (131, 'S2', 2, '라틴 아메리카를 중심으로 성장해 온 이들이 미국에서 열린 K-컬처 대표 페스티벌 주요 무대에서 글로벌 존재감을 선명히 각인함에 있어 그 의미가 남다르다.', '32d4ce113105cdcf9f40209064949df7e69938a656d835fd80797355ddd91779', true, false),
  (131, 'S3', 3, '산토스 브라보스는 지난 14일(현지시간) 열린 ‘KCON LA 2026’에 출연해 ‘엠카운트다운 스테이지(M COUNTDOWN STAGE)’와 아티스트 스테이지(ARTIST STAGE)를 오갔다.', '55f219d51086a9aca7b46155229104ddd57e6d237f1f866bc9184a55ef2794f4', true, false),
  (131, 'S4', 4, '약 50분간 이어진 단독 공연부터 방탄소년단(BTS) 헌정 무대까지, 이들의 다채로운 세트리스트와 강렬한 퍼포먼스가 큰 호응을 얻었다.', '5038888a47dc7d93cce805e8f32051f402856fadd101e1c01870055d6ad2c7d5', true, false),
  (131, 'S5', 5, '가장 주목받은 장면은 한국·일본 활동을 병행하는 하이브의 또 다른 글로벌 그룹 &TEAM(앤팀)과 함께한 방탄소년단 헌정 무대였다.', '50b26f9bada2a4cb1f74473dd837e3d4f1e7a4e057fabb0a8e3aa18ca0d63606', true, false),
  (131, 'S6', 6, '산토스 브라보스는 방탄소년단의 ‘Hooligan’을 자신들만의 라틴 팝 감각과 역동적인 퍼포먼스로 재해석했고, &TEAM은 ‘2.0’을 이어 선보이며 열기를 더했다.', '31c0bf57fb7e5e3b619685af7498a7b451da1ca514a712399c210124db3625e5', true, false),
  (131, 'S7', 7, '마지막에는 두 팀이 ‘Permission to Dance’를 함께 열창하며 공연의 분위기를 최고조로 끌어올렸다.', '95bf4f439fae6b1a6497753225c82a2e7bc7c56af4b6e3b55fc2ef8d0952c94c', true, false),
  (131, 'S8', 8, '이 스페셜 컬래버레이션은 하이브의 ‘멀티 홈, 멀티 장르’ 전략을 상징적으로 보여주는 보이그룹들이 ‘KCON’에서 만난 무대라는 점에서 의미를 더했다.', 'd602d194e8cf7e470849f5c9a4828aa97aa53dbb233f05b444f498c13659971c', true, false),
  (131, 'S9', 9, '각기 다른 언어와 문화권에서 출발한 두 팀은 자연스러운 호흡과 에너지로 무대를 완성했고, ‘Permission to Dance’가 전하는 긍정적인 메시지를 글로벌 음악팬들과 함께 나눴다.', 'ec6ffed4a4cee9ae6a6d80d65001833593eea4f0e2666c38ba0a6473c3b1c9fc', true, false),
  (131, 'S10', 10, '산토스 브라보스만의 정체성은 단독 무대에서 선명하게 드러났다.', 'f4a51ecf77b8a1da32122d44903c7e395edf25c2b5d4ff3e516c0e0ce9c087ca', true, false),
  (131, 'S11', 11, '이들은 첫 번째 EP ‘DUAL’의 더블 타이틀곡 중 하나인 ‘VELOCIDADE(벨로시다지)’에 역동적인 댄스 브레이크를 더해 현장을 뜨겁게 달궜다.', 'bc9d3da3f6e02e1ae621ff36d8e476b9baab5262708a294d74fc1c79d24c3fcb', true, false),
  (131, 'S12', 12, '포르투갈어로 된 곡임에도 관객들은 이 곡의 가사를 일제히 따라 불렀다.', 'fd97eb4e7ababdd7edd6fc22a18a5aacc6cc46727fe8834c205d7e84f3760c38', true, false),
  (132, 'S1', 1, '‘빌보드 200’ 정상 K-팝 25개 음반', '9be8542824d252a91465f81e98324a9a0237ef8b2dfdf0b7259104c7473d3d3b', true, false),
  (132, 'S2', 2, '최초는 2018년 BTS, 점유율은 JYP', '9b2f2df6b2b8ae00aa64777528fee5fb56ff624530e4e70ac83b6dcdbdd48655', true, false),
  (132, 'S3', 3, '[헤럴드경제=고승희 기자] 그룹 스트레이 키즈가 미국 빌보드 메인 앨범 차트에서 9연속 정상에 올랐다.', '48ec76eccc38aa9c33510820f11023e4995c02bf0b3dc5fbdd3a8ff308028f98', true, false),
  (132, 'S4', 4, '2018년 그룹 방탄소년단(BTS)이 이 차트 최정상에 깃발을 꽂은 이후 약 8년 만에 달성한 빌보드 차트에서도 새 역사를 작성했다.', '2312016dcb188c4f4a9791074eeca1e72db561a0751bdf8570c947c0fe23a5cb', true, false),
  (132, 'S5', 5, '17일 미국 빌보드에 따르면 스트레이 키즈의 미니 앨범 ‘디스 앤 댓(This & That)’이 오는 22일자 최신 차트에서 메인 앨범 판매량을 집계하는 ‘빌보드 200’ 1위에 올랐다.', 'e1ef021a26072bbbfbf8db2af52074c8efecdebbe56a7094e0dcd76925be0bf0', true, true),
  (132, 'S6', 6, '스트레이 키즈는 이번 1위로 통산 9번째 정상을 차지하며 K-팝 아티스트 중 최다 1위 선두 자리를 굳혔다.', '48fd329a3d66bbed68255a49ae6b13b165f90e2d8975a83b52a53d985e7a818d', true, false),
  (132, 'S7', 7, '전 세계 음악사에서도 19회를 기록한 비틀스(The Beatles)에 이어 롤링 스톤스(The Rolling Stones, 9회)와 타이를 이루는 기념비적 발자취다.', 'c505c8ad29b54a5b4b1954d4e21e210f388f1c7b7a53675e03ebc46fd2e6235a', true, false),
  (132, 'S8', 8, '현재까지 빌보드 200 정상에 오른 K-팝 그룹은 스트레이 키즈(9회)를 선두로, 방탄소년단 7회, 에이티즈(ATEEZ) 3회, 슈퍼엠(SuperM) 1회, 블랙핑크(BLACKPINK) 1회, 투모로우바이투게더(TOMORROW X TOGETHER) 1회, 뉴진스(NewJeans) 1회, 트와이스(TWICE) 1회, 애니메이션 영화 사운드트랙인 ‘케이팝 데몬 헌터스’ OST 1회 등 총 9개 팀과 프로젝트로 집계된다.', 'c5469ce858c3b1f0d7ed8512f971a36af9189a9990f84c6ae51e7cd206bd88de', true, false),
  (132, 'S9', 9, '총 25개의 K-팝 음반이 최정상에 올랐다.', '51eee6555a4179f06b77cba6b0463e0e548ab3a6d7473041f527e100895a6a14', true, false),
  (132, 'S10', 10, '2018~2026년 25개 1위 앨범 연대기…팝스타 정면 승부', '89687610385e6cc2e637ffe49bda2e297a8a7710213c9c6b1ac2ddcd4840fa21', true, false),
  (132, 'S11', 11, 'K-팝의 ‘빌보드 200’ 1위 역사는 쟁쟁한 팝스타들과의 치열한 첫 주 경쟁을 뚫고 축적된 결과물이다.', '01beb1283e4e3a7589e2effd2f03630bade15e1898d1fe7edfe30df862fec58f', true, false),
  (132, 'S12', 12, '이어 같은 해 9월엔 ‘러브 유어셀프 결 앤서(Love Yourself 結 Answer)’가 18만 5000 유닛을 획득하며 아리아나 그란데의 ‘스위트너(Sweetener)’를 밀어내고 2연속 1위를 차지했다.', '11d5370087675d2acb93af14c1654252bce7b617b2bc7e047299c25f8cb0a23a', true, false),
  (133, 'S1', 1, '[이데일리 신민준 기자] 아모레퍼시픽(090430)이 병의원 중심의 메디컬뷰티시장으로 사업 영역을 넓히고 있다.', 'aa1d2a3640e838e6cc3916d2ab7751f7631949efd79b9a362f3d73b9e633208f', true, false),
  (133, 'S2', 2, '아모레퍼시픽은 올해 들어 실적이 호조세를 보이고 있는 만큼 신성장동력인 메디컬 뷰티 사업을 통해 실적 개선에 속도를 낸다는 전략이다.', '00c1aa8a8cac05608b0a9ba623a3c12b6f0c1cf7de05ea65c5e9c2f10008447d', true, false),
  (133, 'S3', 3, '아모레퍼시픽은 피부미용 의료기기업체와 연이어 협업하며 화장품과 의료기술을 결합한 차세대 뷰티 솔루션 구축에 박차를 가하고 있다.', 'b309161ec21952c9cc63f515728be27b559343bd5a8dd1e850f44ac48e7963dd', true, false),
  (133, 'S4', 4, '17일 화장품업계에 따르면 아모레퍼시픽은 올해 2분기 매출 1조1759억원, 영업이익 1173억원을 기록했다.', 'f3da64f3cecd6781cba5a150ca3adbda1abb3b8dd760bb0f5c2148630b838946', true, false),
  (133, 'S5', 5, '매출과 영업이익은 각각 전년 동기 대비 17%, 59% 증가했다.', 'f9540a14fef71a05a1b7e13fe5a6f8be3e2c541d4307382e8469830a9fd292cd', true, false),
  (133, 'S6', 6, '국내외 사업이 모두 흥행한 결과로 분석된다.', 'ccedf25c32b5d45f6140151dfda1426fe763790076289b4ce88301904ee852e0', true, false),
  (133, 'S7', 7, '국내에서는 온라인·멀티브랜드숍(MBS) 채널 리더십 강화와 크로스보더 사업 확대가 실적 개선에 이바지했다.', '6405bcd9153c263de6155f2a431c68b5e4de27849587dd60d3884b6e386f71dc', true, false),
  (133, 'S8', 8, '국내 사업의 매출과 영업이익은 전년동기 대비 각각 10%, 48% 증가했다.', 'c8f73e4e404d39ed4c9a97028ce2e230b5d249f802f471c5fcf2e8feb0ce7b24', true, false),
  (133, 'S9', 9, '이를 위해 아모레퍼시픽은 화장품을 넘어 메디컬 뷰티로 사업 영역을 확대하고 있다.', '7666beff55d8d14d8ae791905695f871614388eee655667f5fb61ec32153f790', true, true),
  (133, 'S10', 10, '메디컬 뷰티(Medical Beauty)란 피부미용(에스테틱)에 의료적 이해와 병원 실무가 결합된 개념으로 병원에서 이뤄지는 △피부 시술·성형 후 관리 △의료미용기기 △상담·고객응대 등과 연관된 영역을 폭넓게 뜻한다.', '36e5ab96795776778778bbd22038e456f248b7f8ef35f75e924b249f23cc939f', true, false),
  (133, 'S11', 11, '아모레퍼시픽이 메디컬 뷰티 사업에서 주목하는 것은 단순한 의료기기 판매가 아니다.', 'd1300efc8b2365421024338c24d6cf1383b57b4a565739fd3d0e1437e110dd3d', true, false),
  (133, 'S12', 12, '이를 위해 의료기기 기업과의 협력을 확대하며 병·의원시장으로 까지 사업 접점을 넓히고 있다.', '5e178095025487ab4f657bd94ac17712966b5e4aa97325112c1e7f7c0ff80f6b', true, false),
  (134, 'S1', 1, '국내 K뷰티 시가총액 1위 기업 에이피알을 창업한 김병훈 대표(38·사진)가 “에이피알을 시가총액 100조원 규모 회사로 키워내겠다”고 밝혔다.', '4a8d5631d24f24308e22a0b287a7b3eea702fcac0ae4d963d07cea13c4acc2c4', true, true),
  (134, 'S2', 2, '17일 뷰티업계에 따르면 김 대표는 최근 미국 경제지 포브스와의 인터뷰에서 “저는 ‘모든 일은 결국 자신이 말하는 그대로 이뤄진다’는 말을 항상 좋아했다”며 이같이 밝혔다.', '2c30113f19ec9aa2cc6c462e5ae798dcd8a9278e28df86b5b1bdbd0fc55e670c', true, false),
  (134, 'S3', 3, '2014년 김 대표가 설립한 에이피알은 2024년 2월 유가증권시장에 상장했다.', 'd8ff917978c6b56cbbff812d5c658b1085a0ed46c31d0c3d8bc7f67050a9de6a', true, false),
  (134, 'S4', 4, '지난해 8월엔 아모레퍼시픽을 제치고 국내 화장품주 시총 1위에 올라섰다.', '7ca4edfc804ac2cdf959472e5079ecd4e8c8e3f04198294faee2ec58e12c3e27', true, false),
  (134, 'S5', 5, '현재 시총은 14조6000억원에 달한다.', '90b43224675b9e9a0fb1ec4122b457e95c69394041c20df5b4360d061dad9043', true, false),
  (134, 'S6', 6, '포브스가 추정한 김 대표의 순자산은 약 27억달러(약 3조8000억원)다.', '5ed742a9f044ddba4325473fe5ae1b8d428c9caaf5fd396c380d5237c979a30c', true, false),
  (134, 'S7', 7, '김 대표는 “에이피알은 업계의 규칙을 맹목적으로 따르지 않았다는 것”이라며 “한국 뷰티업계에서 시도되지 않은 소비자직접판매(D2C) 방식을 개척한 덕에 유통 혁신을 일으킬 수 있었다”고 했다.', '3b071a017c38117445baacebc63933004f3555a75515a5a494b7453892eb0c34', true, false),
  (134, 'S8', 8, '에이피알은 사업 초반부터 자사몰 기반 소비자와의 직접 접점을 늘리면서 유통 마진을 대폭 줄인 것으로 널리 알려져 있다.', 'd0b66bc749c7767116013611ef3a23f4d428f66a7ae86181e97048cbb4ee0f32', true, false),
  (134, 'S9', 9, '그는 뷰티 디바이스 시장에 뛰어든 것도 큰 도전이었다고 밝혔다.', 'af5fc5a360e91dea494bf5047086854fa189546654f8242c9422a9195ff581ae', true, false),
  (134, 'S10', 10, '김 대표는 에이피알의 뷰티 기기 브랜드 메디큐브 에이지알이 2021년 첫 제품인 ‘더마 EMS 샷’을 출시했을 당시를 회고하며 “디바이스 같은 고가의 제품에 대한 투자자들의 시각은 매우 회의적이었다”고 했다.', '41d362b114905252ce86acce27e97983cfdc43bb90fbec6670334c163fe5b94f', true, false),
  (134, 'S11', 11, '메디큐브 에이지알은 출시 후 1년 만에 국내 홈뷰티 시장 1위에 올랐다.', '28c39fc0265ba080da51c721a973fe52b4075add1172fbb3333328f1af9780b7', true, false),
  (134, 'S12', 12, '작년 기준 에이피알 전체 매출의 27%가 뷰티 디바이스에서 나왔다.', '7b65912de1577b8f9b499ad11a2a9bd41a5b7fabbb247d60d0aa60c064c6e2e4', true, false),
  (135, 'S1', 1, '양사 초등학생 자녀 초청해 승무원 진로교육', 'a6ec2fa27714771b346d4616f48a314e8deb8730300b34595443a5ae526a1aae', true, false),
  (135, 'S2', 2, '임직원 가족 간 유대 강화…통합 기반 마련', '66dd9d17881f51e18d5bc16377684a82f74cd38c7304e3bc3b900ab988b40f3f', true, false),
  (135, 'S3', 3, '13일 서울 강서구 오쇠동 아시아나항공 객실훈련원에서 ''오늘은 내가 승무원'' 진로 교육에 참가한 아시아나항공, 대한항공 직원 자녀들이 기념사진을 촬영하고 있다.(사진=아시아나항공 제공) *재판매 및 DB 금지', '1b93697a4829b681b91fefc018e924f6498d06470038358aba880f97a3da6ff1', true, false),
  (135, 'S4', 4, '[서울=뉴시스]김민성 기자 = 대한항공과 아시아나항공이 오는 12월 통합 출범을 앞두고, 임직원 가족을 매개로 한 밀착 교류를 통해 물리적 결합을 넘어선 진정한 ''화학적 융합''에 속도를 내고 있다.', '1a5594a47bd8428860e6cbfaa42ca74e6066c32083a8d2558bed38f855df1e45', true, true),
  (135, 'S5', 5, '아시아나항공은 13일과 14일 양일간 서울 오쇠동 본사에서 아시아나항공과 대한항공 양사 임직원 초등학생 자녀들을 초청해 ''오늘은 내가 승무원''을 주제로 견학 및 승무원 진로 교육을 실시했다고 14일 밝혔다.', '5de0190357b841417f00c7ce1f2d2d4c26d30de4fe648c0b5ef9450f03afbae8', true, false),
  (135, 'S6', 6, '이번 행사는 양사 통합을 앞두고 임직원 가족 간 정서적 유대감을 높이고 자연스러운 화학적 결합을 도모하기 위해 마련된 교류 프로그램이다.', '708d8c7d30152dcd18417bb995ce8589b653cfa74f3da6bd1dcd5ad0a421dd96', true, false),
  (135, 'S7', 7, '진로 교육에 참가한 양사 직원과 자녀들은 평소 일반인 출입이 제한되는 객실훈련원에서 승무원의 역할을 직접 경험했다.', '3639d098079bb9670844c3d039a39e1998c541a49ec741478cf032cd6e7f1e88', true, false),
  (135, 'S8', 8, '주요 프로그램은 ▲객실 승무원 체험 ▲안전 훈련 체험 ▲운항승무원 직업특강 등으로 구성됐다.', '45eaad0e1ec97546e3f005538f5321b1be2036640039fd84d9d2c32b15e10332', true, false),
  (135, 'S9', 9, '대한항공과 아시아나항공은 오는 12월 17일 통합 대한항공 출범을 앞두고 임직원들의 융합을 위해 다양한 노력을 하고 있다.', 'd7433bb49e4cc4103ed9b57a25fdd35a0a001e3ea1b0703cce7063ee08995b7c', true, false),
  (135, 'S10', 10, '이번 행사에 앞서 지난 1월에는 아시아나항공은 자사 임직원 뿐만 아니라 대한항공 임직원들의 자녀들을 초청해 ''Why?', '2d03b171027767f916578e68ae36d33dbaffc2977fc2f0b9b06f7d026d730a37', true, false),
  (135, 'S11', 11, '항공과학 탐험교실'' 프로그램을 개최하기도 했다.', 'e012fa7b4a0f419a00f1b12db8916dc2d6582db242098bc145e2793e07f41e3d', true, false),
  (135, 'S12', 12, '아시아나항공 관계자는 "이번 행사가 자녀들에게 부모 직업에 대한 자부심을 심어주는 계기가 되길 바란다"며 "앞으로도 일과 가정이 양립할 수 있는 가족친화적 기업문화를 조성하고, 통합을 앞두고 양사 구성원과 가족들이 서로 소통할 수 있는 교류 프로그램을 확대해 성공적인 통합 기틀을 마련하겠다"고 말했다.', '4f7e148a36017edcd741085ef4cece93f699cdd862209ddc0a076a5fad624a72', true, false),
  (136, 'S1', 1, '호반그룹은 최근 한진칼 지분을 20.15%까지 확보했다.', 'f644af42562e555062179284bdba00aa45ef4f5109cd9825cb1a0e92c77d7bab', true, false),
  (136, 'S2', 2, '최대주주인 조원태 한진그룹 회장 측 20.57%와 불과 0.42%p 차이다.', 'dc850d909fc7d00b3a0b3e1e3c4616ad0ea45c592d89c5a5300ae11ede344a9c', true, false),
  (136, 'S3', 3, '그런데도 호반은 2022년 지분 인수 이후 보유 목적을 ''단순투자''로 유지하고 있다.', '1b1c50c1df9c3c954d8f0792b29b10301c76a503912d146b70af079b91c73a15', true, false),
  (136, 'S4', 4, '반면 한화그룹은 지난 5월 한국항공우주산업(KAI) 지분이 5%를 넘자 ''경영참여''를 선언했고, 이후 지분을 15.89%까지 늘리며 공정거래위원회에 기업결합신고까지 마쳤다.', '2b974f554a2aa128d2d472b0cf7b4aea2c89bc8b42fa245765196487bf39e909', true, false),
  (136, 'S5', 5, '지분을 더 많이 확보한 호반은 경영에 거리를 뒀지만, 한화는 상대적으로 적은 지분으로 먼저 경영참여를 선언했다.', '15d2c05a9de3267458f4eb98a4b0f9bbc13e7a17361727d25e1205907214b74e', true, false),
  (136, 'S6', 6, '두 그룹의 엇갈린 행보는 지분율보다 지분을 통해 무엇을 얻으려 하느냐에서 비롯됐다는 평가가 나온다.', 'fc65af46cdbabdd869d4df6ed261bcca510e7515536caa6e6e740a1ae4ee5c71', true, false),
  (136, 'S7', 7, '16일 재계에 따르면 호반은 2022년 한진칼과 경영권 분쟁을 벌였던 사모펀드 KCGI의 지분을 인수하며 2대 주주가 됐다.', '3c54861f5cd5f63e785951b9ffe75bf74a2267f7de98e822bf6c3884896b717f', true, true),
  (136, 'S8', 8, '이후 계열사를 통해 주식을 꾸준히 사들여 지분율을 20.15%까지 높였다.', 'd5cea077d45964c3879f8eeb87d366709522cd1cf8cfad019150202e1da48409', true, false),
  (136, 'S9', 9, '호반건설이 11.50%, 호반호텔앤리조트가 8.34%를 보유하고 있고 호반산업과 ㈜호반도 일부 지분을 들고 있다.', '6ab330925613cdf59129ee9eb88cad3bef943d279fcf554e66639a80241c6589', true, false),
  (136, 'S10', 10, '최대주주인 조원태 한진그룹 회장 측과의 지분 격차는 0.42%포인트에 불과하지만 실제 경영권 구도는 다르다.', '4bfd2622b90c763e020c539a092cd191a497336b3e78b7a407c381e91da08698', true, false),
  (136, 'S11', 11, '''단순투자''를 유지해도 20%가 넘는 지분 자체가 적지 않은 영향력을 갖는다.', '8dc3e7f028b1c4330e9bc926d3b2825202194b222ec2d89a0ef6015b6be3ab45', true, false),
  (136, 'S12', 12, '한화그룹 지분이 5.09%로 올라선 지난 5월 보유 목적을 ''단순투자''에서 ''경영참여''로 전환했다.', 'a5733cc0f65078fc1e145623e79b795b32ab432dc60f25bd33d4f89d120bc6cf', true, false),
  (137, 'S1', 1, '[파이낸셜뉴스] HD현대가 유인 함정 중심이던 K-방산의 패러다임을 ''자율운항 무인 함정''으로 한단계 진화시키며 세계 최대 방산 시장인 미국 안방을 정조준한다.', '10b759ba44b2d64f11b4d10703e9b4a94a3d377581c172566a67fc71396ef81f', true, false),
  (137, 'S2', 2, 'HD현대는 미국의 인공지능(AI) 방산 혁신기업 ''안두릴(Anduril)''과 공동 개발 중인 차세대 무인수상정(USV) 시제함을 내년 초 미 해군 수뇌부 앞에서 전격 공개하며 초대형 방산 수출의 신호탄을 쏜다.', 'bbd647370445a2910e463c5756ea4eff92b62a5f9a8079baaf4b63c6ebd4a468', true, false),
  (137, 'S3', 3, '단순한 유인 함정 대체를 넘어, 민간 상선 시장에서 이미 입증된 ''AI 항해 자율화'' 초격차 기술력으로 고부가가치 무인 함대 시장의 선봉장이 되겠다는 포석이다.', 'dfe8dd2eb7a9a37b5a2ad852083c4cc042a2373d39d606a581facb443deea921', true, false),
  (137, 'S4', 4, '17일 업계에 따르면, HD현대는 내년 1~2월경 미국 연안에서 차세대 무인 함정의 첫 시연 행사를 개최한다.', '88c6be67891cbecd822f7645f9d5e61cd85b49466a767e13220df6d5f0a77daf', true, true),
  (137, 'S5', 5, '이번 행사에는 미 해군 장성을 비롯한 핵심 관계자들이 참석할 예정이며, 대한민국 해군 측 주요 인사 초청도 검토 중인 것으로 알려졌다.', '755ba889af22007cacc7a200e13197eb64d88a88fe6de4e870f4a6cb1eaf9b10', true, false),
  (137, 'S6', 6, '현재 HD현대중공업 울산조선소에서 건조에 박차를 가하고 있는 첫 시제함에는 한미 양국의 첨단 국방·조선 기술이 총망라된다.', 'e1bf1a3b3f51fb9b52aff471b568715b095e35496946d4b1ad240daf610e1745', true, false),
  (137, 'S7', 7, '안두릴의 AI 기반 자율 임무 수행 체계인 ''래티스''와 HD현대의 자율운항 기술이 핵심적으로 융합되는 것이 특징이다.', '28694ec74efcd55438ce9b5d8f678dda5d6782f0612cbe53582d128f0095fcb5', true, false),
  (137, 'S8', 8, '특히 HD현대는 단순한 자율운항을 뛰어넘어, 선박의 기관 운영까지 아우르는 ''완전 무인 항해 자율화''에 집중하고 있다.', 'a6dba0129118e0eea0180e6112d1a3906c40120c57589ba8eea7ff288d2c0ed6', true, false),
  (137, 'S9', 9, '자회사 아비커스가 대형 상선 500여척에 적용해 이미 기술적 검증을 마친 자율항해 솔루션이 그대로 탑재돼 경쟁사와 차별화된 높은 신뢰성을 자랑한다.', '997dd93f96c5fa7eacef8f5c11df6cf977ff3876f559530eec2e80fa93ea615c', true, false),
  (137, 'S10', 10, '이들의 최종 타깃은 천문학적인 국방 예산이 투입되는 미 해군의 대규모 무인 함정 사업이다.', '37880016a8836cead147dee74cc780731a74db9c93f91373c6cec3c2e8c52fe4', true, false),
  (137, 'S11', 11, '미 해군이 향후 전체 전력의 26%에 달하는 134척을 무인 체계로 확보하겠다고 선언한 만큼, 연평균 10% 이상 폭발적으로 성장 중인 무인수상정 시장은 K-조선의 확실한 미래 핵심 먹거리다.', '34ae9d7ead86e6b394d1e354e603e66430da08f0d112f8b20758d2a61175f1f9', true, false),
  (137, 'S12', 12, 'HD현대 관계자는 "미국 법인 설립 등 현지화 전략에 속도를 내는 한편, 최근 안두릴과의 협력을 무인수상정을 넘어 첨단 무인잠수정(UUV) 공동 개발 등 수중 플랫폼까지 폭넓게 확대하고 있다"며 "세계 최고의 중대형 무인 함정을 완성해 우리 해군의 인력 부족(인구절벽) 문제에 실질적인 대안을 제시하고, 한층 안전한 함정 근무 환경을 구축할 것"이라고 전했다.', 'cdc27e3d30e6f06d78d47c527ef515bddf6b0c2f40de9d934ad941ada6f4df6b', true, false),
  (138, 'S1', 1, '(서울=뉴스1) 신현우 기자 = 국내 대형 조선소의 평균 가동률이 100% 이상인 것으로 나타났다.', '0cffece9d2529ac7afdc7d3f50ceda54ef4259a39313cb89d90520075702bb56', true, true),
  (138, 'S2', 2, '이미 3년 치 일감을 확보해 ''풀가동 체제''를 유지하는 것이다.', '8d7ff0caff061fae5847c0f143f803ef4cb01495d8689a66869ec27b147e78b4', true, false),
  (138, 'S3', 3, '조선사들은 여기서 한발 더 나아가 생산 능력 자체를 키우기 위한 설비 투자에 속도를 내고 있다.', 'f88f707bd62a034ee9521becc32e0a68e42d716ece9e2296b175955b02579302', true, false),
  (138, 'S4', 4, '16일 각 사 반기보고서에 따르면 올해 상반기 기준 HD한국조선해양(009540)의 조선 부문 평균 가동률은 106.1%로 집계됐다.', '3fad70dd742091e62a605999fb50eb8e523dd64df0179cef32ae8fbf3cf0ff65', true, false),
  (138, 'S5', 5, '삼성중공업(010140)의 조선 부문 평균 가동률은 100.2%, 한화오션(042660)의 평균 가동률은 100.0% 수준이다.', 'b8d4024ce47f5ebbd765df2ed583ed2ebb9611d948e0f47995244902b5e1652d', true, false),
  (138, 'S6', 6, '대형 3사가 나란히 100% 선을 넘긴 것이다.', 'a3e6bee3a1dfe19f8315091019454910c32a5008cf8a72f43d7bee3f8867c810', true, false),
  (138, 'S7', 7, '평균 가동률이 100%를 웃돈다는 것은 정규 조업 시간만으로는 물량을 소화하지 못했다는 것으로, 휴일 근무나 야간 조업 등 추가 근무를 동원해 설비를 돌렸다는 의미다.', 'ee6602daba41eef999f038c00ad077183328420fce2947693bcaff3af3697675', true, false),
  (138, 'S8', 8, '사실상 초과 가동 상태에서 선박을 건조하고 있는 셈이다.', 'cb85fc0bb2b76a799c5e4e934e1c51185088e4b7dd07a22f4ff91bd2dcc78d58', true, false),
  (138, 'S9', 9, '이런 풀가동 체제는 수주 호황이 뒷받침하고 있다.', 'edfc61240743e2b430c1d54d8cefcdb39b97677eade0cc3284c75e7cbccdc126', true, false),
  (138, 'S10', 10, '국내 조선업계는 친환경·고부가가치 선박 수요 증가 등에 힘입어 향후 3년 치 일감을 확보한 상태로 알려졌다.', '394b82356fb7ac5c8e7af062411e35936db74ec119a4fd6c900a23906e1b397b', true, false),
  (138, 'S11', 11, 'HD한국조선해양은 최근 콘퍼런스콜에서 3년 6개월 치 일감을 확보 중이라고 설명했고, 다른 업체들도 비슷한 수준으로 전해졌다.', '91bba8107132fc8ea7088cd63ea4e3cd5c92574a36132c6e77cb121de49da1bb', true, false),
  (138, 'S12', 12, '조선업계 관계자는 "LNG 등 고부가가치 에너지 운반선 수요 급증과 함께 지정학적 리스크로 인한 영향으로 발주가 늘었다"며 "슈퍼사이클을 맞은 상황인데, 확보한 일감을 제때 인도하기 위해 최대한의 생산 체제를 유지해야 하는 상황"이라고 설명했다.', 'd32c278074447adc45e7e713b4393b6ef8f7d2d9e6a8cbc8b329ff2cf1b5fb5d', true, false),
  (139, 'S1', 1, '트럼프, 美 투자 외국 조선사 본국서 최대 2척 한시 허용', 'fe9a0b7568839a040eba297d731bd5437acace1dbc24b00586f69e0ef801c94c', true, false),
  (139, 'S2', 2, '한화오션 5.6%·핀칸티에리 3.2% 상승…오스탈 인수 추진엔 변수', '84866634187123529c99de0fee2c6abe5fa82221e7e8fc60d3277fca0db3eaa2', true, false),
  (139, 'S3', 3, '도널드 트럼프 미국 대통령이 자국 조선업에 대규모로 투자하는 외국 조선사에 미 해군 함정을 본국에서 건조할 수 있도록 길을 열면서 한화오션이 가장 유력한 수혜 후보로 떠올랐다.', 'b7adcead83e7267f60b275438903a8223d7018f95d733b84b3cdc5e93409a9dc', true, true),
  (139, 'S4', 4, '15일(이하 현지시각) 로이터통신에 따르면 트럼프 대통령은 미국 조선소에 상당한 투자를 하고 미국인 인력을 양성하는 외국 조선업체가 본국 조선소에서 미 해군 함정을 최대 2척까지 한시적으로 건조할 수 있도록 하는 내용의 국가안보각서에 지난 13일 서명했다.', 'a4cc7decc236c56ab0c08adcc933e9d03063c190524c0940b093a23df25e105a', true, false),
  (139, 'S5', 5, '이에 한화오션 주가는 14일 5.6% 상승했으며 이탈리아 핀칸티에리도 3.2% 올랐다고 로이터는 전했다.', 'fa708a0738fde3d8722c57973be0721400b952eb3f110c237dd1689b9ba3e3c2', true, false),
  (139, 'S6', 6, '이번 조치로 외국 조선소에서 미 해군 함정을 건조할 수 있는 길이 수십 년 만에 열렸다.', '66810be9d5ca1f6c7392082e878dc05c2b1843efe17bd9b27419939bfea85e04', true, false),
  (139, 'S7', 7, '해외 건조가 허용되는 선박은 수상전투함, 통합화물 보급 유조선, 로로선 등 3종류다.', '8df9b52230f679b4919ab857ef115fb5df2cefacb5fb8ebf2b2c58687077b111', true, false),
  (139, 'S8', 8, '로이터에 따르면 미국 내 조선소를 확보하고 대규모 투자를 약속한 한화가 이번 정책 변화의 선두 수혜자로 평가받고 있다.', '018daaaa304131b1e063627339302d8d10a5c9d9f61c039d2b9a796c5539094d', true, false),
  (139, 'S9', 9, '한화는 필리조선소 생산능력 확대에 50억달러(약 7조925억원)를 투자하겠다고 약속했다.', '014a9daccef825e8e426d48d9277d8d53923a648aaa6efbbccb1b64775124a11', true, false),
  (139, 'S10', 10, '한화와 함께 이번 정책의 주요 수혜 후보로 꼽히는 기업은 유럽 최대 조선업체인 이탈리아 핀칸티에리다.', '5909606db024206d8c90e8ca0d3a20a35b39e7145872cb15c5827cdeef224e7f', true, false),
  (139, 'S11', 11, '로이터는 한화, 핀칸티에리가 미국에서 가장 큰 외국계 조선소 기반을 확보하고 있어 이번 정책 변화의 직접적인 수혜 대상으로 부각됐다고 전했다.', '5d35d02d72d82f7c9e18d40b3444db1852d1608f91e7246ffd223908dab1ac95', true, false),
  (139, 'S12', 12, '트럼프 행정부의 구상은 해외 조선소에서 필요한 함정을 신속하게 확보하는 대신 미국에 투자하고 현지 인력을 육성하는 기업에만 예외를 제공해 장기적으로 미국의 자체 생산능력을 확대하는 방식이다.', 'd92b934772829a478cc62d294e7e6c9b0a8dc46181b4f111a7d4442014aa1c36', true, false),
  (140, 'S1', 1, '삼성중공업이 원유 운반선 2척을 추가 수주했다.', '6c354d562d41ac8801643b84720b845f43b30c9ef146002563772de044cc55f2', true, false),
  (140, 'S2', 2, '이로써 올해 상선 부문 수주 목표액을 조기에 채웠다.', 'e8d8bb376c146492c0b03417758884fff7a6b05ac358c6984bc7251a78bbafc3', true, false),
  (140, 'S3', 3, '삼성중공업은 유럽 지역 선사로부터 원유 운반선 2척을 2680억원에 수주했다고 3일 공시했다.', '6a3b0529b99408d0d87b7d0cdfd1deaff1cfd8eb40db5b2d1a5e9cd34e1fd67d', true, false),
  (140, 'S4', 4, '수주액은 계약일인 지난달 31일의 달러화 대비 원화 환율(1141.1원)을 적용한 금액이다.', '40753fa2d94897b6ab56e9316ae2678940d906231c653ac1666ed0995a8d717c', true, false),
  (140, 'S5', 5, '삼성중공업은 2029년 8월 말까지 선박을 인도할 계획이다.', '0268ef309ea6508a65423b489e5dde12386d8f2d9aa8980e69f99aa14e7613d2', true, false),
  (140, 'S6', 6, '삼성중공업은 원유 운반선 2척을 추가 수주하면서 올해 상선 부문에서 누적 34척, 58억달러 규모의 수주 실적을 기록했다.', '938872748d08bafa0505ddf6ea00690ef91416e272cd730c536caf4d184e7dcf', true, true),
  (140, 'S7', 7, '올해 수주 목표액(57억달러)을 넘어섰다.', '98ffc7d15916632b396fe72d53e2e725c464b5966cabe842247ec06407cac42f', true, false),
  (140, 'S8', 8, '선종별로는 LNG(액화천연가스) 운반선 14척(LNG-FSRU 1척 포함), 에탄 운반선 2척, 가스 운반선 4척, 컨테이너 운반선 2척, 원유 운반선 12척을 수주했다.', 'e88d9c03d2a84010d33d32803649899605feabb44e176b075bab81c60037a488', true, false),
  (140, 'S9', 9, '올 들어 해양 부문에서는 FLNG (부유식 LNG 생산·저장·하역 설비) 2기 등을 포함해 누적 102억달러의 수주 실적을 쌓았다.', '500cebe3dfc1833ff4870fabad9014670737537aee06f28a6af056b3d99e36b7', true, false),
  (140, 'S10', 10, '연간 해양 부문 수주 목표액(139억달러)의 73% 수준이다.', 'cc5563576ab577eb797798f8f509f1e18a9066cc611b1a5081d19cf8e5ee81d5', true, false),
  (140, 'S11', 11, '삼성중공업은 “LNG 운반선, 원유 운반선 등을 중심으로 발주세가 지속되면서 올해 상선 부문은 수주 가이던스를 조기에 달성했다”며 “향후 수익성 중심 선별 수주에 더욱 집중하고 글로벌 오퍼레이션(운영) 등을 통해 수요 변화에 유연하게 대응할 계획”이라고 했다.', '6e1150e88e14ad47b12fc20d864c3c4ede3ab859411ab6efcb526a1c6ac01ec9', true, false),
  (141, 'S1', 1, '한화에어로스페이스가 방사청과 K9 자주포의 탄착 정밀도를 높여주는 첨단 탄약기술을 개발한다.', '10dffd9b4fe98db3aac0c3a0720c2f9780e4917189cca41a59509ebf153420b7', true, false),
  (141, 'S2', 2, '한화에어로스페이스는 14일 2032년까지 1642억원을 투입해 K9 자주포용 155mm 탄약에 적용되는 ''탄도수정신관''을 개발하는 ''탄도수정신관 체계개발사업''의 우선협상대상자로 선정됐다고 밝혔다.', 'b3d8d93334f8ae0824244068c491a3a1332a47f6148e411316b24a7427d859c4', true, true),
  (141, 'S3', 3, '''탄도수정신관''은 기존 155mm 탄약을 정밀화·첨단화할 수 있는 핵심 부품이다.', '4cada7af13e42957615f700fcd9ae39bcd55ddc373ca759e3f6688c7baee6045', true, false),
  (141, 'S4', 4, '탄약 앞부분에 장착돼 발사 이후 GPS를 기반으로 탄의 궤적을 수정해 명중률을 높여준다.', '8b9965c4eaefb6ce5bced2f8665dd48d6d1273aaf66edabf46d403b0c172cd74', true, false),
  (141, 'S5', 5, '사정거리가 늘어날수록 정확도가 떨어지는 기존 탄약의 문제를 해결할 수 있고 기존 탄약에 적용된 구형 신관을 새로 개발될 탄도수정신관으로 교체해 사용하는 것도 가능해 활용도가 높은 기술이다.', '5231cc949622e776c6bf1deb08895f607fb4cb5b3454b26585ccfe043b020cd3', true, false),
  (141, 'S6', 6, '탄도수정신관을 적용할 경우 기존 K9의 탄착 오차 범위를 약 6분의 1 수준으로 줄일 수 있을 것으로 예상된다.', 'ca024cfc21d091f6967f9bc3f09468822cea7c1cb607eb7038291e7f2b41f122', true, false),
  (141, 'S7', 7, '탄착 오차가 줄어들면 최소한의 탄약으로 장거리 표적을 정밀 타격할 수 있다.', '2750f30539d038a661201f98dd2f7947a6941506cd33f986092501a95d78a9db', true, false),
  (141, 'S8', 8, '발사 횟수 감소로 K9 포신의 내구도를 보존할 수 있어 군수지원 부담도 줄어든다.', 'fad00bb1c5c9f510a3e423290e7cb17b309222f13ed3618baf5df9e5be102302', true, false),
  (141, 'S9', 9, '본지와 전화 통화한 한화에어로 관계자는 "탄도수정신관은 미래 화포체계 핵심 기술이다.', '86a5ba88ea9f31258f5c33f05f2ed8b529923a5076c035685e01e3add1f8bbac', true, false),
  (141, 'S10', 10, '첨단 방위 기술 국산화를 통해 자주국방과 K방산 수출 확대에 적극 기여할 것이다"고 밝혔다.', 'e388d1c1f911e241bb45cb7c5f6409a06fb761cfa937b428298a5bffed43fb35', true, false),
  (142, 'S1', 1, '2013년 ''시험평가실'' 신설, 체계종합에 필수적인 시험평가 역량 제고', '58524ca33f0325236e93bf9d7ae8d108f825a97f7b24b1de44b1838da0b4e991', true, false),
  (142, 'S2', 2, '유도무기 기술연구소 산하에 ''대지체계연구센터'', ''핵심 기술연구센터''', '27b4a6b587860f6dfb050c537438e789cd3b36c2b01067fba0adab3222575adb', true, false),
  (142, 'S3', 3, '''우주영상연구센터'', ''전투체계연구센터'' 등 전문 연구소 연이어 설립', 'a7d4efaadcffcb57cea1527720735c2a984579233b17d6c5683072ba32fc0111', true, false),
  (142, 'S4', 4, '우수 인재 확보·유지에 총력, 2013년 연구인력 중 석‧박사 비중 57%', 'cba83847e765d24969721fcb1c86f525454daa2e3cfa831ee746ed97d9f98458', true, false),
  (142, 'S5', 5, '[빅데이터뉴스 채명석 기자] 2006년 방위사업청 개청 이후 국내 무기체계 개발 환경은 전문화·계열화 대신 경쟁체제가 도입되는 등 대대적으로 변화하기 시작했다.', '073e407d6d166563ce9ff0c321f294a52b3c4ab98fd380bad42f5640d1b49679', true, false),
  (142, 'S6', 6, '수출에 대한 관심이 높아지면서, 업체 스스로 체계종합 수행 능력을 확보하는 것이 방위산업계의 주요 화두로 떠올랐다.', 'aad3105493408dfa8befc11cac050ae6a21ffa8bc76c18977a0f0bd18087dde2', true, false),
  (142, 'S7', 7, '하지만 체계설계와 시험평가 등 대부분의 체계종합은 지금까지 국방과학연구소(ADD)가 담당해 왔기 때문에 LIG넥스원을 비롯한 국내 주요 방위산업체의 경험과 기술력은 매우 부족했다.', 'ea1c3bcea926ef6464ddc38c550859f30da0ff0bad1ff7d4ada7032cd5850c95', true, false),
  (142, 'S8', 8, '따라서 선제적 체계종합 역량을 갖추기 위해 분야별 중점 사업에 대해 개발과정별 V모델을 적용한 체계설계를 실행했다.', 'e27e4a0a16e15cbcb277a8d0fdd06c584d1c8176226e33e9f2763f57946be5a0', true, false),
  (142, 'S9', 9, '2013년 1월에는 연구개발 단계별로 시험평가 절차를 수립하고 정비시험을 지원하는 ‘시험평가실’을 신설, 체계종합에 필수적인 시험평가 역량을 제고했다.', 'a8b288056e7f1e497a93863941e962715d9a91e28d5c06e8bb0d93cf4b9d08a9', true, false),
  (142, 'S10', 10, '분야별로 특화된 전문 연구소를 연이어 신설한 것도 변화된 무기체계 개발환경에 대한 대응책이었다.', '738768598c3f65ef8c9d0cd94ab10230dec961b4d7758c9562da560e5bc6fc54', true, false),
  (142, 'S11', 11, '2013년 8월 LIG넥스원은 연구개발본부 산하에 유도무기 기술연구소를 신설했다.', 'd8782cb02b747dd50e3f42e9f26898efcd34acb10007d967f24a9e78f56c7190', true, true),
  (142, 'S12', 12, 'R&D 분야에 필요한 석·박사 인력 채용을 확대하기 위해 캠퍼스 리쿠르팅(Campus Recruiting) 대상 학교를 대폭 늘렸다.', '477048caeddf5cb72194360c8ee7f6934619ad24d60e598199806bfa3b08dd8d', true, false),
  (143, 'S1', 1, '현대로템과 한국항공우주(KAI)가 한국형 전투기 KF-21에 탑재될 장거리 공대공 미사일 등 항공무장 기술 내재화를 위한 협력에 나선다.', 'f689a05b975a920facdc4a22986794348f073cb0292b20efa5c58ad27e91ce30', true, true),
  (143, 'S2', 2, '현대로템이 지난 12일 경남 사천 KAI 본사에서 ''항공무장 사업협력 업무협약(MOU)''을 체결했다고 13일 밝혔다.', 'f7209ffeb08f422755201a8891633bacddc106b7dc06fa9fe53a4b144012c237', true, false),
  (143, 'S3', 3, '양사가 보유한 핵심 역량을 바탕으로 항공무장 분야 기술협력과 상호 교류를 확대하고, 글로벌 시장에서의 경쟁력을 높이기 위해 마련된 협약이다.', 'ae6794f3bfce7e21086914c22ed9a06e9c4573e7c5d53bc0e62c15b56813c988', true, false),
  (143, 'S4', 4, '최근 글로벌 방산시장에서 항공기와 무장을 통합한 패키지형 수출이 확대되는 만큼 현대로템의 유도무기·추진기관 기술과 KAI의 항공기 기술을 결합한 토털 솔루션을 제시하겠다는 구상이다.', 'dc905f4277bef0a6c4e7f3e742d61af1576043ba089fcf0835311a428434897a', true, false),
  (143, 'S5', 5, '현대로템 관계자는 "이번 협약은 양사의 핵심 기술을 결합해 미래 항공무장 분야 경쟁력을 한층 강화하는 계기가 될 것"이라며 "양사의 전문성과 사업 역량을 바탕으로 국방력 강화와 자주국방 역량 제고에 기여하겠다"고 말했다.', 'f69a8fcc40563b4c464ad6055aa0f902235cbaed022770579d8654bec68d805a', true, false),
  (143, 'S6', 6, '앞서 지난 2월에는 한화에어로스페이스와 LIG D&A가 사우디아라비아에서 열린 세계방산전시회에서 각각 KAI와 항공무장 사업협력 MOU를 체결한 바 있다.', 'ec50c4fe66ccce733db2ba45c092c067e515d99360527d7a65f99e3587c4cad1', true, false),
  (143, 'S7', 7, 'KAI가 KF-21 체계 종합 업체인 만큼 주요 방산사 모두와 항공무장 협력관계를 맺은 셈이다.', 'cf5ad68177a7e9895d93dd13544eda5b80f65b22f2da215ff6b6ecf1f47780c2', true, false),
  (143, 'S8', 8, '현재 KF-21에는 유럽 MBDA의 장거리 공대공 미사일 ''미티어''가 장착돼 있다.', '04320cb872c67806c0fe21f112ad995653d144b299e6aeab4877b69e78939ea4', true, false),
  (144, 'S1', 1, '현대로템 무주군 적상면 일대 2034년까지 단계적 투입', '3df7fabc33c7dda7bbf4ebe679828d0dfca9515036e6f9551eb165a9b81879dc', true, false),
  (144, 'S2', 2, '무주군 산지조성, 조례 제정, SOC 확보 필수적', '773b8c002d1d22cbd5dda889e40f03a4933b4b341e29d6f54f659f4b8581ef2e', true, false),
  (144, 'S3', 3, '현대로템도 지역환원 사업과 추가 투자 이뤄져야', '0a375338bce6f8cfef932d9ddf133bd6fb7b4e18a5250aecd3c9f4860f9c2422', true, false),
  (144, 'S4', 4, '[무주=뉴시스] 김얼 기자 = 황인홍 무주군수가 현대로템 항공우주 종합생산기지 구축과 관련한 조감도 앞에서 본사 기자와 인터뷰를 하고 있다.', '80056c5d4b17f1b36fda3b3646ca3cc44fcc13bb307c3e3a5eecfaf035bae035', true, false),
  (144, 'S5', 5, '전북 무주군이 전북 굴지의 방위산업체 현대로템을 품으면서 우주항공도시로 도약을 준비하고 있다.', '72da13fe44844ff2f0ef59220623c3081aadba6f3f5f7fbe7bf30cd5583b5896', true, false),
  (144, 'S6', 6, '이제 막 첫발을 뗀 무주군은 현대로템의 투자를 앞세워 향후 우주산업의메카로 우뚝서겠다는 원대한 포부도 드러내고 있는 상황이다.', '0ff0654ad5b0ead3435d2e7d338335a3be8cdc1f1bc87a30d145654f39b7fca0', true, false),
  (144, 'S7', 7, '전북에 터를 둔 방산은 거의 전무한 상황이다.', 'b3f8cb0de55f4488ac559ed2049a91d861f145914c75db3984de3002f477b9b6', true, false),
  (144, 'S8', 8, '[무주=뉴시스]최정규 기자 = 현대로템은 최근 전북 무주에 항공우주 생산기지를 만들겠다며 투자를 선언했다.', '2f2186938e535ff975305efbe369aafbb83330fa45ae2dbdc45ff11c019ff7f7', true, true),
  (144, 'S9', 9, '현대로템은 무주군 일원 축구장 107개 규모의 76만330㎡(약 23만평) 부지에 올해부터 2034년까지 약 3000억원을 단계적으로 투자할 계획이다.', 'ebf225122db1a0421aa29ef674c668a47bad3ea82c14f4cbf0fa8579c9d2561e', true, false),
  (144, 'S10', 10, '구축될 시설은 ▲초음속 덕티드 램제트 엔진 ▲극초음속 이중램제트 엔진 ▲우주발사체용 메탄엔진을 생산하는 종합 항공우주 생산기지다.', 'ec95bbf2f6143e7503af275ccd45f78664f7fd6a4cf5ae81602664e1974d8640', true, false),
  (144, 'S11', 11, '연구개발, 시제품 제작, 시험·검증, 양산까지 전 과정을 수행하는 고부가가치 연구개발(R&D) 중심 시설로 조성될 예정이다.', '1280828a7c4a842a370eb9fd981d1c38f6c2c0a68c4159111bb40f5d58570432', true, false),
  (144, 'S12', 12, '특히 우주발사체용 메탄엔진 생산에 들어가는 부품은 약 160여개로 알려졌다.', '5bed85032050941f1c3b30b1d638827fc2f9ae83207c02ebdfa53f7408da2f54', true, false),
  (145, 'S1', 1, '3대 메가프로젝트를 반영한 미래 전기 수요와 원자력발전소 추가 신설 여부 등 수요를 충족시킬 방안에 대한 논의가 다음 주부터 다시 속도를 낸다.', '0591bdd44b873c371e99c67bcc42a30419b34af090d65eade83f187555b35224', true, false),
  (145, 'S2', 2, '4차 토론회에서는 ''전기국가''로 전환을 위한 에너지 정책, 5차에서는 2040년까지 전력수요와 재생에너지 보급 전망이 논의될 예정이다.', '1b01dd986c3ac3015b1e7c762590578ea87c813fb27e1325632d2fe6703b387d', true, false),
  (145, 'S3', 3, '12차 전기본 수립 총괄위원회는 지난 4월 3차 토론회에서 이미 전력수요 전망을 내놓은 바 있다.', '6911b4c29f8a0655722c56ed5fcb57d76d0d80158716fcf36f920ebfa372e5cd', true, false),
  (145, 'S4', 4, '지난 4월 22일 서울 양천구 한국방송회관에서 열린 12차 전력수급기본계획 대국민 정책 토론회에서 수요계획소위원회 위원장인 허진 이화여대 교수가 수요전망 종합발표를 하고 있다.', '24302a1b3290567871063cf25e1e2b6b392d3d14f9d3c989f4e608fb3f224594', true, false),
  (145, 'S5', 5, '(서울=연합뉴스) 이재영 기자 = 3대 메가프로젝트를 반영한 미래 전기 수요와 원자력발전소 추가 신설 여부 등 수요를 충족시킬 방안에 대한 논의가 다음 주부터 다시 속도를 낸다.', '2020cafc9093db1da37c15151f8a0bb8d5b81fb71326e04e18b43dc8c838b5b5', true, false),
  (145, 'S6', 6, '차기 전력수급기본계획(전기본) 수립을 위한 대국민 토론회가 4개월 만에 이어지는 것인데, 정부가 10월까지 전기본을 마련하겠다고 공언한 터라 논의가 단시간에 요식으로만 이뤄질 수 있다는 우려가 크다.', '7221fc399e7c7998b67d502d7ea5ec12bf721746ce43b8be03278f6235b5e380', true, false),
  (145, 'S7', 7, '기후에너지환경부는 20일 서울 영등포구 국회의원회관에서 제12차 전기본을 수립하기 위한 4차 대국민 토론회와 5차 토론회를 연이어 연다고 15일 밝혔다.', 'd0f35dd9edce24a7b29b5b905bb8ce3e4767367b8380e1737a8c38be5f76ad39', true, false),
  (145, 'S8', 8, '이번에 전망을 다시 내놓는 것은 앞서 전망 발표 후 호남 반도체 산업단지 조성 등 3대 메가프로젝트 추진이 결정됐기 때문이다.', '3f8dd6dccf04d5840b16aeab39206e6a2052069413f4895fcb1bd13a9d4c316e', true, false),
  (145, 'S9', 9, '앞서 전기본 수립 총괄위는 2040년 연중 최대 전력 수요가 131.8GW(기가와트·기준 시나리오) 또는 138.2GW(상향 시나리오)에 달하고 연간 전력 소비량(목표수요)은 657.6TWh(테라와트시·기준 시나리오)나 694.1TWh(상향 시나리오)에 이를 것으로 전망했다.', '1d5231b0351e086e9ea789ba3b320b46a1e922aa4c8570ae1d75f7d222a53ee5', true, false),
  (145, 'S10', 10, '정부가 용인·호남 반도체 산단과 인공지능 데이터센터(AIDC) 등 때문에 ''확정적으로 늘어날 전력 수요''만 2040년까지 30GW, 잠재 수요에 수송과 난방을 전기화하는 데 필요한 양까지 고려하면 50GW 이상이 더 필요하다고 한 만큼 전기본 수립 총괄위가 내놓을 새 전력 수요 전망은 기존보다 대폭 늘어날 것으로 보인다.', '35250b277744e542e698d4d4b733bd80038559aff30f1ed666fb32a59b293afd', true, true),
  (145, 'S11', 11, '정부가 내놓은 반도체 산단과 AIDC를 위한 추가 전력 수요의 구체적인 근거는 제시되지 않은 상황에서 어느 정도까지를 ''확정된 전력 수요''로 보고 12차 전기본에 반영할지가 이번 토론회의 관건이다.', '5c00371a9f000305bc9d49ddd4254a94ac9589825092bcc65745c3165e3476b4', true, false),
  (145, 'S12', 12, '석탄화력발전 폐지와 전력시장 개편은 발전소와 발전공기업 노동자 삶에 직접적인 영향을 주고 송·변전 계획은 전력망이 지날 지역에 영향을 크게 끼치는 등 신규 원전뿐 아니라 모든 주제가 에너지 분야를 넘어 전(全) 사회적 쟁점인데 두 달 정도 논의가 충분한지에 대한 의구심이 나온다.', '9f32dd7f63a68c6f71163dfaa3e4639b6f932e8b6e0c207efd98544da95439ea', true, false),
  (146, 'S1', 1, '[서울파이낸스 박시형 기자] 국내 정유사들의 실적 성장이 높아진 정제 마진에 힘입어 한동안 이어질 것으로 보인다.', '000541691df55bf37d328c6fc3e842ae1c9509235d119b858893900a1c0cf385', true, false),
  (146, 'S2', 2, '17일 증권업계에 따르면 이진명·김명주 신한투자증권 연구원은 최근 ''전쟁보다 긴 호황'' 제목의 정유 부문 보고서에서 "정유 업황 강세가 예상보다 길어질 전망"이라며 "높아진 정제마진과 현금 흐름을 바탕으로 이익 확대를 지속할 것"이라고 전망했다.', '29053e0c41f7f43023645a0af38f7e5d802d75c6d84717096f1cce64328edb77', true, false),
  (146, 'S3', 3, '정제마진은 원유와 정유 제품 간 가격 차에서 생기는 수익을 뜻한다.', '5b37bef78718da2fea1a908ef535178bf5683a45cfec691ce1c092181b00c421', true, false),
  (146, 'S4', 4, '정유 제품 수요가 높았던 데다 러시아 정유 공장 피격과 중국 내 생산 감소, 6~8월 성수기가 맞물리며 공급이 부족해져 제품 가격이 올랐고, 정제마진도 함께 커졌다.', 'b552cf2692a4c62f72359b3d6d79319435d5c885a27912f44c146f4f5b3f618c', true, false),
  (146, 'S5', 5, '2분기 싱가포르 복합정제마진은 배럴당 평균 24.7달러로, 업계 손익분기점으로 통하는 4~5달러의 다섯 배 수준이었다.', 'e475fcf748a87e6a32c8f98c8a5d7121214fe2a69cb85a338098fccd1f6577d2', true, false),
  (146, 'S6', 6, '지난달 미국의 정제마진은 배럴당 63달러로 역대 최고치를 기록했다.', 'eb36d1dece05f08a458cdb360073ed960d90caf58778479ee17075b71572d94d', true, false),
  (146, 'S7', 7, '이에 힘입어 정유 4사(SK이노베이션·GS칼텍스·에쓰오일·HD현대오일뱅크)의 상반기 합산 매출은 120조6345억원, 영업이익은 14조7906억원이다.', 'ebb15daf68757a5fdb642ca1499ce4da88a7636c308f72053154d6d3b78b4eb3', true, true),
  (146, 'S8', 8, '대한석유협회와 한국석유공사에 따르면 올 상반기 석유제품 수출량은 주요 품목 수출 제한 영향으로 전년 동기보다 7.5% 줄어든 2억2623만배럴이었다.', '1b92f33cba621b1e747851fd3df6fbc9905d627d9e186158aac98e1f280ed324', true, false),
  (146, 'S9', 9, '원유도입액 대비 석유제품 수출액 비율은 68.1%로 지난해 상반기(54%)와 하반기(60.7%)를 크게 웃돌며 반기 기준 최고치를 새로 썼다.', '41c49aea4b916b7debe7e2d475684b29a9eed33ba984d2bb7e2a07b3023b0306', true, false),
  (146, 'S10', 10, '증권가는 정제마진이 커진 만큼 정유사가 제품 생산을 늘릴 것으로 본다.', '0c838eb0375493d727c1ba8373730715aebc2b9ce03cf756a2a51fd0419696c5', true, false),
  (146, 'S11', 11, '에쓰오일 주가는 지난 14일 14만7600원으로 마감해 이 목표주가까지 11.8%의 상승 여력이 남아 있다.', 'eda2627e23bc9f631d5e7f82de42c7dc9f9ea22a5e3b3a8e25e0172bdabfca78', true, false),
  (146, 'S12', 12, '정부는 석유제품에 최고가격제를 시행 중이며, 이에 따른 정유사 손실을 재정으로 보전하기로 하고 손실액 산정 절차를 진행하고 있다.', '352e8f145da2031702885a7791015910e2feaeaa832ab3415ad847c317304151', true, false),
  (147, 'S1', 1, 'GS가 정유사업 호황에 힘입어 2분기 시장 예상을 크게 웃도는 실적을 거둔 데 이어 인공지능(AI) 데이터센터 사업을 새로운 성장동력으로 내세우고 있다.', 'bf9ca7454f969cd92eee97925cfd2fe9b1bd6b402bf8af4325b29d8f1aed0607', true, false),
  (147, 'S2', 2, '유진투자증권은 최근 보고서에서 GS가 땅과 물, 전력을 모두 확보한 가운데 대규모 AIDC 사업을 추진하고 있어 중장기 성장성이 커지고 있다고 밝혔다.', 'e4f223f2ace27b2b9bd1757631ff28f1abb40dcfb9d79ce19b3501c0bde85194', true, false),
  (147, 'S3', 3, 'GS의 2분기 매출액은 7조4000억원으로 전분기보다 8%, 지난해 같은 기간보다 25% 증가했다.', '46f22cd636fe638d79aaf44bbb85752111f5d901e66232c9c4666becc32d83a7', true, false),
  (147, 'S4', 4, '영업이익은 1조7000억원으로 36% 늘었고, 지배주주순이익은 1조6000억원으로 2683% 급증했다.', 'dbb94752f85702c6d2223bb75e3aac11249eec43a002241e76e201f968b9d96b', true, false),
  (147, 'S5', 5, '당초 시장의 기대를 크게 넘어선 실적이다.', 'f6507796aedce66c44f1a0b2fe90e71ec92a3dd7394b2ebaaf0b86f3edfa6039', true, false),
  (147, 'S6', 6, 'GS는 자회사 GS AI인프라를 통해 강원 동해에 대규모 AI 데이터센터(AIDC)를 조성하는 사업을 추진하고 있다.', '53bc201ce1cfb87c29c0ac34189fa15376691e534d58021ed1d0a96f331feb30', true, false),
  (147, 'S7', 7, '1단계 규모만 1.2GW이며 장기적으로는 총 2.4GW까지 확대한다는 계획이다.', '550e3a36811eec1ec88d2a82faabdd0c121323e282bc19e6a4574649c3cc8ea8', true, false),
  (147, 'S8', 8, '1.2GW 데이터센터 구축에 필요한 투자비는 그래픽처리장치(GPU)를 제외하고 약 15조원으로 추정된다.', 'fe129a6c312ae0acfa71c6d807e8cfc5ca1f5969c810e1dfbb793fe381134739', true, false),
  (147, 'S9', 9, '북평산업단지의 상당 부분이 아직 미분양 상태여서 데이터센터 건립에 필요한 부지와 기반시설을 확보하기 상대적으로 수월한 것으로 보인다.', 'd97f3ccf275b55da142b756aead4276b73ccfa446830b7619d03ed682fcd4837', true, false),
  (147, 'S10', 10, '1.2GW 전체를 한꺼번에 착공하기보다 150MW 단위 등 단계적으로 사업을 진행할 가능성이 높다.', '71cf72c49c2d0e07ad2932596df5908db98d5f2959bddeff633fc4b69973b9cb', true, false),
  (147, 'S11', 11, '유진투자증권은 2.4GW 규모의 데이터센터 구축이 완료되면 지배주주순이익이 최소 20% 이상 증가할 가능성이 있다.', 'fef8146d5b711dffe6ce1e47316dca071ef014572beedd84407413303795fef5', true, true),
  (147, 'S12', 12, '정유사업의 강력한 현금창출력에 더해 AI 데이터센터라는 새로운 성장축까지 확보하면서 GS의 투자 매력도 커지고 있다.', '142a64324c950df8ed8a2e33dd2892143b81ffb8e5588bd5b56acceb2422a56c', true, false),
  (148, 'S1', 1, 'SK이노베이션이 테라파워의 차세대 비경수형 소형모듈원자로 ''나트륨''의 글로벌 사업 확대와 한국형 사업 모델 적용 추진에 협력한다.', 'd24228f148e4f9d80a57144052bb4c0f2639febafd4f26f0c79d3d575e48de5d', true, false),
  (148, 'S2', 2, 'SK이노베이션은 14일 서울 모처에서 추형욱 SK이노베이션 대표이사, 크리스 르베크 테라파워 CEO가 만나 나트륨 SMR 사업 협력과 차세대 SMR의 글로벌 시장 진출을 위한 합의서를 체결했다고 밝혔다.', 'eca3c9ce64e83b96511b2100a9296f752c5b5c03e681fdb115fc22bb6a744a3d', true, true),
  (148, 'S3', 3, '이번 합의서에 따라 SK이노베이션은 테라파워가 미국 와이오밍주에서 추진 중인 나트륨 SMR 프로젝트 ''케머러 1호기''와 후속 상용 프로젝트에 대한 참여를 확대할 계획이다.', '90d60f5bda371204e032d026df5d43fe9e319d7c9897a0c45c83e10b3793f76b', true, false),
  (148, 'S4', 4, '(서울=연합뉴스) 추형욱(앞줄 오른쪽) SK이노베이션 대표이사, 크리스 르베크 테라파워 CEO가 14일 서울 종로구 선혜원에서 SMR 사업협력 주요 조건 합의서를 체결하고 최태원(뒷줄 오른쪽부터) SK그룹 회장, 김정관 산업부장관, 빌 게이츠 테라파워 이사회 의장과 함께 기념 촬영을 하고 있다.', 'e218e37bbf840fedf9913966d590f001fb9bd93dbf7318ef5d30ad9b19f8b118', true, false),
  (148, 'S5', 5, '2026.8.14 [SK이노베이션 제공.', '7227cc2d10d33b4b29f6ebd41a8ab8245d7776601071288096c3d3f0a0510a82', true, false),
  (148, 'S6', 6, '(서울=연합뉴스) 김민지 기자 = SK이노베이션이 테라파워의 차세대 비경수형 소형모듈원자로(SMR) ''나트륨''의 글로벌 사업 확대와 한국형 사업 모델 적용 추진에 협력한다.', 'f0091ef12073a76843f302716e1f7b7402409cda6b0b70955e4401d2922ec9b8', true, false),
  (148, 'S7', 7, '케머러 1호기 SMR 프로젝트는 지난 3월 미국 원자력규제위원회(NRC)로부터 미국 최초의 상업용 첨단원자로 건설 허가를 받은 뒤 사업을 본격 진행 중이다.', '99885150217b15569dfe102989ea3cb601fae08a3486e4eeb67d33fa9844b769', true, false),
  (148, 'S8', 8, 'SK이노베이션은 미국 실증사업 참여를 통해 차세대 원전의 설계·건설·운영 경험을 확보하고 이를 한국과 미국을 비롯한 베트남·인도네시아·말레이시아 등 아시아 시장에서의 SMR 프로젝트 개발과 운영사업 확대에 활용한다는 방침이다.', 'f46d0c814f84748d665aa322b50b1df7817ccb6029fa7be2f862f8d10ba7bb79', true, false),
  (148, 'S9', 9, '또한 양사는 SMR 글로벌 프로젝트 공동 발굴에 협력하고 한국형 나트륨 SMR 사업모델인 ''K-나트륨''의 추진 방향을 단계적으로 구체화해 나갈 계획이다.', '3495c48ed6ed10c763b43a8abeb6b6a5b862fc8943b1deda374fa732b7b43126', true, false),
  (148, 'S10', 10, '이날 합의서 체결 이후 이어진 만찬 자리에는 최태원 SK그룹 회장과 빌 게이츠 테라파워 이사회 의장이 참석해 AI 데이터센터 확산에 따른 전력 수요 대응과 차세대 원전 산업의 발전 방향, 한미 원자력 협력 가능성 등을 논의했다.', 'b7e70c88fdcaabc9197e76257130d0db7ff4f30957eb10d583bf61c38bb8b4c1', true, false),
  (148, 'S11', 11, '나트륨 SMR은 테라파워가 개발한 4세대 소듐냉각고속로(SFR) 기반 SMR로, AI 데이터센터와 반도체·산업단지 등 대규모 전력 수요처에 최적의 미래형 에너지 설루션으로 주목받고 있다.', '9319a0c6d80b9793b8c3a95f2dab59cabb71676d24d8649fe1b038f319c5176d', true, false),
  (148, 'S12', 12, 'SK하이닉스의 AI 반도체, SK텔레콤의 데이터센터와 AI 인프라, SK이노베이션의 LNG·전력·SMR, SK온의 에너지저장장치(ESS) 배터리를 활용해 AI 데이터센터에 필요한 반도체·데이터센터·전력·저장장치 공급망을 구축한다는 전략이다.', '0415f816fcf76ce6d0d6056fbe753facd266f4ce444d4412f4ae7b3afead5467', true, false),
  (149, 'S1', 1, '신세계백화점은 늘어난 출생아 수와 자녀에게 아낌 없이 투자하는 소비 경향을 반영해 역대 최대 규모의 아동 장르 행사를 연다고 17일 밝혔다.', '6ed3af9a841c4d27b536368f3f10ed1cfc61adc9612fe57dc1901b06852a1caf', true, false),
  (149, 'S2', 2, '신세계백화점은 오는 30일까지 전 점포에서 ''베이비페어''를 열고 유모차와 카시트, 아기띠, 유·아동 패션 등 출산·육아에 필요한 상품을 한데 모아 선보인다.', '6ec3f29d3b7b1cc6f0e8c9118dfbbd15e42a63e44df04303a7fe43cb6206e9ac', true, false),
  (149, 'S3', 3, '아동 브랜드 50여개가 참여해 인기 상품을 최대 40% 할인한다.', 'd10c5004b3554bf23d2510159a436723d7d91ff017a56f7d4b1253971e767932', true, true),
  (149, 'S4', 4, '(서울=연합뉴스) 정수연 기자 = 신세계백화점은 늘어난 출생아 수와 자녀에게 아낌 없이 투자하는 소비 경향을 반영해 역대 최대 규모의 아동 장르 행사를 연다고 17일 밝혔다.', '01a505aab0cdcb8b04864f3abebcf8c9b4ea06403ea53c1d6b3dab896a34768f', true, false),
  (149, 'S5', 5, '대표 상품으로 브라이텍스의 프리미엄 카시트, 싸이벡스의 유모차, 프리미엄 아기띠 브랜드 아티포페의 신제품이 있다.', 'a68dd79ca69096619d0ca7cdc4f8545fd237e92121179d304a063d1ac6578d42', true, false),
  (149, 'S6', 6, '사회관계망서비스(SNS)에서 인기를 끌고 있는 키즈 브랜드의 릴레이 팝업도 열린다.', 'd59233925e7242a53c7f613b60c9faf82260d5fdb087b317164704853622bb2c', true, false),
  (149, 'S7', 7, '부모와 아이가 함께 착용할 수 있는 주얼리 브랜드 루미플래닛은 강남점에서 이달 20일까지 행사를 진행한다.', 'c922f68087c9980c802c5c31f177bfd59e3dd7e6c8b70d43f00843f0086ceb47', true, false),
  (149, 'S8', 8, '유모차 브랜드 실버크로스는 센텀시티에서 20일까지, 키즈 완구 브랜드 노리터프로젝트는 대구신세계에서 23일까지 팝업을 연다.', '281f28e69b32cbd04d922731aeed4b3a347c8e15f57cc666740b5ddfaff2e83e', true, false),
  (149, 'S9', 9, '가족 여행객을 겨냥해 오는 10월 출항하는 ''디즈니 크루즈'' 여행 상품도 판매한다.', '08313c6afcc9bc2fdb49f222be372ae6c2b7e2992138b9ab04f611740f6c59ca', true, false),
  (149, 'S10', 10, '행사 기간 신백멤버스 가입 고객이 제휴카드로 아동 패션·잡화 장르에서 일정 금액 이상 구매하면 상품권을 증정한다.', '5198c815971e7f3b07ffde0e5d4ff232f9cc9aef7ea33e468422d7c51bc994b6', true, false),
  (149, 'S11', 11, '선현우 신세계백화점 패션담당은 "출생아 수가 증가하면서 유·아동 시장에도 새로운 활력이 나타날 것으로 기대하고 있다고 말했다.', 'c4b0072ffa08beba5e3147f1fc9b4fff9ccd98a9134802d2b50eb186e761f4f9', true, false),
  (150, 'S1', 1, '롯데렌탈이 렌터카 시장에서 점유율을 넓히는 동시에 수익성까지 개선하면서 실적 성장세를 이어가고 있다.', '31cad91d20906f8139487cce4ed073f7e0f03284aecadc9f56123df7b3e42ecd', true, true),
  (150, 'S2', 2, '대신증권은 최근 보고서에서 장·단기 렌탈 사업의 경쟁력 강화와 중고차 렌탈 비중 확대가 롯데렌탈의 이익 구조를 개선하는 핵심 요인으로 작용하고 있다고 밝혔다.', 'a6d7aec0cd0ee62397d7c298d08aa323b14e717110c9d2a595b55aaf27a0bb86', true, false),
  (150, 'S3', 3, '롯데렌탈은 자동차를 빌려주는 렌터카 사업을 중심으로 다양한 모빌리티 서비스를 제공하고 있다.', '29eb903067d43cff4b979fc332c1b85a6b4632c086f2fe3367b162c58e839d3d', true, false),
  (150, 'S4', 4, '자동차를 일정 기간 빌리는 장기렌터카와 필요한 기간만 이용하는 단기렌터카가 주요 사업이다.', '95f301967dfbb38209b15527ccc7fbc0f5e09526ff7fbd527d15c90da9405017', true, false),
  (150, 'S5', 5, '최근에는 중고차를 활용한 렌탈 사업도 확대하면서 수익성을 높이는 데 힘을 쏟고 있다.', '02223f6ad4ebc2840eed8c71a68aea56e8013dcff20ccf5a09178c59b66a97d3', true, false),
  (150, 'S6', 6, '올해 들어 롯데렌탈의 실적에서 눈에 띄는 변화는 매출보다 이익의 증가 속도가 빨라지고 있다는 점이다.', '2e4930e1d956b5678d8b26cc36da607bf46be598cef0f7544cef0bad94eb3745', true, false),
  (150, 'S7', 7, '단순히 차량을 더 많이 빌려주는 데 그치지 않고 수익성이 높은 사업의 비중을 높이면서 돈을 버는 구조 자체가 개선되고 있다는 평가다.', 'ad03d825562881e7ef8a177e45c37dda1334cc278e4c1622ae67328cba01d218', true, false),
  (150, 'S8', 8, '롯데렌탈의 올해 2분기 매출은 7657억원으로 지난해 같은 기간보다 2.3% 증가했다.', '6963f3d18bba02aeb567f7e5f85403a1e18a6ef0d3fecee9ebf3c19e283f393d', true, false),
  (150, 'S9', 9, '직전 분기와 비교하면 4.8% 늘었다.', 'fc72fd334dde33b4a2356d74de7f40f5608a1950ec0de33011b06585cc411d90', true, false),
  (150, 'S10', 10, '영업이익은 846억4000만원으로 지난해 같은 기간보다 9.6%, 전 분기보다 1.2% 증가했다.', '879b0b11aa9cf9907a1748e1493fea566e9b500b5625a463069bd3deec068192', true, false),
  (150, 'S11', 11, '영업이익은 시장 전망치인 868억원에는 다소 못 미쳤다.', '1e32111bf554dd484590e771cc2401074b765ebefd2b3b0d68252edc30fbe594', true, false),
  (150, 'S12', 12, '롯데렌탈은 장·단기 렌탈 점유율 확대와 중고차 활용을 통해 이익률을 끌어올리는 방향으로 사업 구조를 바꾸고 있다.', '9f3ea91c41a87afa1472842fdeb1d64536ebe7a82c6b4e55a00eb2d3425ae3a9', true, false),
  (151, 'S1', 1, '(서울=뉴스1) 양새롬 기자 = 포스코인터내셔널(047050)이 국가보훈부와 함께 추진하는 국외 독립운동사적지 포스아트(PosART) 안내판 설치 사업을 올해부터 멕시코와 미국, 네덜란드로 확대한다고 16일 밝혔다.', '1bd1e195d516f4954ed6e2f3928d46e0f21c76bb032dc795f8cd8c9712fa32e1', true, false),
  (151, 'S2', 2, '지난해 중국·몽골·뉴질랜드 등 3개국에 안내판 64개를 설치한 데 이어 내년 3월까지 이들 3개국에 신규 설치와 기존 안내판 교체를 포함해 총 111개를 순차적으로 설치한다.', 'fcea41f8e745c3f4dd02e576a3698f92e0aa04f16c978b1ec44a26d4c13e6662', true, true),
  (151, 'S3', 3, '이번 사업은 임직원의 자발적인 기부로 운영되는 포스코1%나눔재단 사업의 하나다.', '6b34101e1a3fccec296ac824fb45bc206cf5e21527f5c7d148c0ae508c5f7359', true, false),
  (151, 'S4', 4, '해외 독립운동사적지의 역사적 가치를 보존하고 재외동포와 현지 방문객에게 독립운동의 역사와 의미를 알리는 것이 목적이다.', '0f66d2645864cf31e4bd7b85877848e5ef85b2c274a1f8b86892848ecd8a9140', true, false),
  (151, 'S5', 5, '해외 사적지는 국내보다 기후와 관리 여건이 다양한 만큼 장기간 외부에 노출되는 안내판의 내구성이 중요하다.', '06acd4de5754641d38684584ad72aa97b11042c460c6de6cfe3e36e0321e0570', true, false),
  (151, 'S6', 6, '포스아트는 철강 소재의 내구성과 고해상도 인쇄 기술을 결합해 이런 환경에 적합하다는 평가다.', '8e376a6c260b861b54a5bab1170dfbfd8223ad5ca3989f79f59badf63324bbdd', true, false),
  (151, 'S7', 7, '포스아트는 철강재에 잉크젯 프린팅 기술을 접목한 고해상도 컬러강판이다.', 'e082e4e28501e9cab1bcd21217b18f20a88508ab890f3231c490bad822281f47', true, false),
  (151, 'S8', 8, '기존 프린트강판보다 4배 이상 높은 해상도로 정밀한 디자인을 구현할 수 있으며 내구성과 내식성이 뛰어나 다양한 기후 환경에서도 장기간 품질을 유지할 수 있다.', 'ecbb8b3eb5204e72fca12916364f2b2c50b6d06d42a14c31fd2f96685090f3c2', true, false),
  (151, 'S9', 9, '포스코인터내셔널은 광복절인 지난 15일(현지 시각) 주멕시코대한민국대사관과 함께 멕시코 메리다 대한인국민회 지방회관의 재개관식을 열었다.', '1da562a11c7d761bd245908a10ddab4b7f21f9e90a459c0f385b6d2404a508f9', true, false),
  (151, 'S10', 10, '현재 한국이민사박물관으로 운영되고 있는 이곳의 재개관에 맞춰 건물 입구 현판과 안내판 등을 포스아트로 교체해 안내 환경을 정비했다.', '915af93fe86a9210f135628064649ed85fa6b2251e98085ac5069bb866b47439', true, false),
  (151, 'S11', 11, '오는 9월에는 네덜란드 헤이그 이준 열사 기념관의 입구 현판을 교체한다.', '2d1ea6bb83f3d56e58ea807d0ab89eb8afc0163f06022b8d2ae306c1500df180', true, false),
  (151, 'S12', 12, '올해 말부터 내년 3월까지는 미국 로스앤젤레스 흥사단소에 신규 안내판 107개를 설치할 예정이다.', 'bca378bb4df8ab360625a0ea9f9a80a54990a7695c52e3497545d65850a7d1e4', true, false),
  (152, 'S1', 1, '‘보내오네’ 출시부터 당근과 연동까지', '91a7728394715f1be8bb59373892fccc2352c5608a4acc11146acdba46c67589', true, false),
  (152, 'S2', 2, '[데일리한국 안세진 기자] CJ대한통운이 개인 간 거래(C2C) 택배 시장을 새로운 성장동력으로 삼고 관련 서비스 확장과 전략적 협력에 속도를 내고 있다.', 'ca2bf22931fd9cfa2d0032d34001815b5d60ea7655ffadcb5215518c378f0053', true, true),
  (152, 'S3', 3, '늘어나는 개인 간 거래 수요를 흡수해 물류 시장에서의 주도권을 더욱 강화하겠다는 구상이다.', 'c7820f36ed3becbdad9ae878c7cda26231b4c3940e27083910f1ddb3c14d89a1', true, false),
  (152, 'S4', 4, '16일 업계에 따르면 CJ대한통운은 최근 C2C 수요 선점을 위한 서비스를 잇달아 선보이고 있다.', '3e7a97853be5515e3ae61e423b183586f77e18e3866f13c2ea15fd2c11e5b257', true, false),
  (152, 'S5', 5, '개인 간 배송 전용 브랜드 ‘보내오네’가 대표적이다.', '3808420a02b73b7ed86c32fb411ba87e89fb6c7c28e8c9942a1a732aad8ac8f1', true, false),
  (152, 'S6', 6, '지난 4월 출시한 보내오네는 물품을 받는 데 초점이 맞춰졌던 기존 배송 서비스에서 벗어나, 누구나 쉽고 간편하게 물건을 보낼 수 있는 환경을 조성하는 데 초점을 맞췄다.', 'b3458bd7f60a75a809a92584976e816d72f032bf6950242d190229ae309740cc', true, false),
  (152, 'S7', 7, '소비자가 통합 배송 브랜드 ‘오네(O-NE)’ 앱을 통해 방문 접수를 신청한 뒤 물건을 문 앞에 두면 수거부터 최종 배송까지 전 과정을 실시간으로 확인할 수 있다.', '1092ea0a5457e28f841ddb733ffbc79ff4acaffc72450cea3f48f582c6529306', true, false),
  (152, 'S8', 8, '지역 생활 플랫폼인 당근과의 전략적 제휴도 C2C 사업 확장의 주요 축으로 꼽힌다.', 'fa4cc46386fb08afaf5cb624369ec04af7699929dbd66f06d40ab4977096fbc2', true, false),
  (152, 'S9', 9, 'CJ대한통운은 지난해 9월 당근과 체결한 업무협약을 바탕으로 올해 3월부터 당근의 ‘바로구매’ 서비스 전국 배송을 전담하고 있다.', 'ff01736aae3e9e91b1b581aabe207ca8e617b13ce32b95b002d97abaeef48c40', true, false),
  (152, 'S10', 10, '바로구매는 상품 검색과 결제, 배송, 대금 정산까지 원스톱으로 처리할 수 있는 서비스다.', '96069d1ea7aca7e884a122fe3261731878cc575c317cd1747529cca10e6178d2', true, false),
  (152, 'S11', 11, 'CJ대한통운은 C2C 거래가 일상화되면서 개인택배 수요가 확대되고 있는 만큼, 관련 서비스와 플랫폼 협력을 통해 추가 물량을 확보한다는 전략이다.', '5ea69e9ab0392f1913961e633d372ffb0b258ee95cac8bee1ab33a1b913f7cd0', true, false),
  (152, 'S12', 12, '이어 “당근과의 협력을 강화하고 모바일 앱을 고도화하는 등 고객이 더욱 쉽고 편리하게 이용할 수 있도록 개인택배 서비스를 확대해 나갈 것”이라고 덧붙였다.', 'cd05fdd9d3b5156c7a93d8a29f591cfa2f8d50a6b222778854e262f35ad557ae', true, false),
  (153, 'S1', 1, '2030년까지 29조… 11조 유동성 확보', 'e0495dd8efc732ff6b8b021c8347357eeb9ffdf46c05771a990e5d96df6773e7', true, false),
  (153, 'S2', 2, '성장전략 유지 위해선 현금창출력 관건', '83a7e9ec9a8c119431211f1307b202f93c119b22ce1c5cfa6e6b78042a798801', true, false),
  (153, 'S3', 3, '벌크 등 영역확장… 매출 다변화 추진', '9433e9b13458faa48250b5a3926dee6dec7dfcd11f14adc78d37d1bf2e3f73e9', true, false),
  (153, 'S4', 4, 'HMM이 올해 상반기에만 선박 확보에 2조원이 넘는 자금을 투입하며 선대 확충에 속도를 내고 있다.', '107b610aedbd09c4a5888803ae9fcd4c6b56212da2092f407059b78a26e46994', true, false),
  (153, 'S5', 5, '오는 2030년까지 선대와 항만·물류 인프라 등에 약 29조원을 투자하는 중장기 성장 전략이 본격적인 집행 단계에 들어선 모습이다.', '003499a22ea48a7268ad404dee0b2f9374f86cea4be6a8cc153a18f25add046d', true, false),
  (153, 'S6', 6, '다만 해운업황의 변동성이 큰 상황에서 대규모 투자가 장기간 이어지는 만큼 안정적인 현금창출력을 확보하는 것이 주요 과제로 꼽힌다.', '0a7a43af64e46c2a619a8ba94f5436a0441c2749e681b071cbfffa355cb37293', true, false),
  (153, 'S7', 7, '17일 금융감독원에 따르면 HMM은 올해 상반기 선박 확보에 2조2577억원을 투자했다.', 'c3d54967e4f4dbd94418f1a3a886f8c3fe3e58531b6563c84ec15341651b68ab', true, true),
  (153, 'S8', 8, '지난해 같은 기간 6550억원과 비교하면 약 245% 증가한 규모다.', '9fbfb3dc50d69b1e3446b6b6969a7d2c71b6f62e984d4cc55baec3fc7371a881', true, false),
  (153, 'S9', 9, '올해 상반기 영업이익 6232억원의 약 3.6배에 해당한다.', '4a50c4bde06992b2315074499910aab38de1906dcb1e063fbd7f583d815e47cf', true, false),
  (153, 'S10', 10, '대규모 선박 투자는 HMM이 추진하는 중장기 성장 전략의 핵심이다.', '7f66d380c96fe3ce73c8811c7e1c4e97ce75a60e8dd04ca166e7bd99a784e763', true, false),
  (153, 'S11', 11, 'HMM은 오는 2030년까지 선대와 항만·물류 인프라 등에 약 29조원을 투입해 사업 경쟁력을 강화할 계획이다.', 'c3e8d1ea72a65094e513f7c01f9c4563ba4c43969e0ed37e76e1e32f2f044217', true, false),
  (153, 'S12', 12, '컨테이너선은 현재 73척에서 2030년 166척으로, 벌크선은 50척에서 110척으로 각각 확대한다는 목표다.', '82bda43ce0e74fab72f68e091496e90b94849b0f79443d796db9f5c4707a1044', true, false),
  (154, 'S1', 1, '현대글로비스는 한국도로공사와 협력해 화물차 안전운전 문화 정착을 지원하는 ''화물차 기사님 안전을 드림'' 캠페인을 오는 11월까지 진행한다고 13일 밝혔다.', 'd846f6b44fe2220c697b45f7fda5ee22fdef7d16d528a218fa066865ddf68ebb', true, true),
  (154, 'S2', 2, '아울러 지난 11일 현대글로비스는 경기 안성시 고삼호수휴게소에서 화물차 기사들에게 앞좌석 햇빛 가리개, 발포비타민, 화물차 반사띠 등 여름철 사고 예방을 위한 안전용품을 배포했다.', '1d761ff7b4f18539b7c713eab6639a2287bcb160c7745280458fec09cc21b706', true, false),
  (154, 'S3', 3, '화물차 라운지에는 미니 냉장고와 얼음·생수, 졸음 예방용 산소캔도 기부했고, 현장 건강 체크 부스도 운영했다.', '714aadf11f43aaed5c682e2ade7109445b5eb785c108869319a822be6c12a314', true, false),
  (154, 'S4', 4, '(서울=연합뉴스) 임성호 기자 = 현대글로비스는 한국도로공사와 협력해 화물차 안전운전 문화 정착을 지원하는 ''화물차 기사님 안전을 드림'' 캠페인을 오는 11월까지 진행한다고 13일 밝혔다.', '12ba5cd4f8be221fabca6999825751f3c472cf627065a12b23c2e6ab6b2b2ccf', true, false),
  (154, 'S5', 5, '현대글로비스는 전국 화물차 라운지와 휴게소 등 20여개 거점을 확보하고 약 1만5천명의 화물차 기사를 대상으로 한 프로그램을 30회에 걸쳐 운영할 계획이다.', '2a7beb573c65eeb37e1cf967737f98e727f47d19b4c5f3ce58072857ac89873d', true, false),
  (154, 'S6', 6, '프로그램은 교통안전 교육과 현장 의견 수렴, 운전자 건강 기초 검진 및 상담 서비스, 계절별 안전용품 제공 등으로 구성된다.', 'eeb7db15062fe4006c2cfc7a2bd655a466e153484ad0fd5c27a5849a8922f8fa', true, false),
  (154, 'S7', 7, '현대글로비스 관계자는 "지난 10년간 진행한 사회공헌 프로그램을 더욱 발전시켜 안전하고 건강한 물류 현장을 위해 노력하겠다"고 말했다.', '216e99122a48e1285afb7d8cab76a023fdc4b8d01df8fb6a64cfc36127928a1c', true, false),
  (155, 'S1', 1, 'KB금융그룹은 17일 "자연 관련 위험과 기회를 금융 의사결정에 체계적으로 반영하겠다"고 밝혔다.', 'db38bbd41789cef7f380da1b501ac57fa295023630c85e24cebf9da93af8decb', true, true),
  (155, 'S2', 2, 'KB금융은 이번 보고서에서 자연자본 위험과 익스포저가 모두 높아서 우선 관리가 필요한 핵심 산업군으로 소재, 임의 소비재, 산업재 등을 꼽았다.', 'ca432b8845ce1afac3815460b7dc733f2b2521716306f7ad87aa8b2d03078a06', true, false),
  (155, 'S3', 3, '이어 "3개 핵심 산업군의 상시 모니터링을 통해 포트폴리오의 자연자본 위험 관리 체계를 지속해 강화하고 있다"고 했다.', 'e37dcb4d1493cbc1d4251d39d5f52932775bae118deada97ea3d669392d7f122', true, false),
  (155, 'S4', 4, '(서울=연합뉴스) 한지훈 기자 = KB금융그룹은 17일 "자연 관련 위험과 기회를 금융 의사결정에 체계적으로 반영하겠다"고 밝혔다.', 'cd74a0e215f6a56504c6feba8d24a671650331dcbd1e15b44df97edc147dd667', true, false),
  (155, 'S5', 5, 'KB금융[105560]은 이날 ''2025 KB금융그룹 자연자본 공시 보고서-자연과 금융의 연결''을 발간하고, "생산적 금융을 통해 산업의 지속 가능한 전환을 지원하겠다"며 이같이 말했다.', '1c074ac812c37bb17b5a6128f0d390bce308a35785a44562e3800061bd0191e2', true, false),
  (155, 'S6', 6, 'KB금융은 또 "포용금융을 통해 청년·지역사회·중소기업이 자연과 함께 성장할 수 있도록 금융의 역할을 확대하겠다"고 강조했다.', '4d6314d9c0373c386ad4f8b4071517782fe2748bb1570fe044ed6576b3064d18', true, false),
  (155, 'S7', 7, '자연자본은 토지, 물, 생물다양성 등 경제 활동의 필수 기반을 의미한다.', '362b6e3804009230415d617319dab5714749c0a38b879c0cc61bc3e0244d9829', true, false),
  (155, 'S8', 8, 'KB금융은 작년 말 기준 환경 부문 상품·투자·대출 등 20조8천억원 규모의 ESG 금융상품을 관리·운용했다고 소개했다.', '26b395bbaa67a45e1215ff4f2a6024be7017efb927fb158deb26fed05402c3bc', true, false),
  (155, 'S9', 9, '이를 2030년까지 25조원으로 확대하는 것이 목표다.', '6c7339f59599c68f5d3bd4b230ebbfbaed47e8c388e3d8812ada19ac0c46e584', true, false),
  (156, 'S1', 1, '[이데일리 김세연 기자] 5대 금융지주(KB·신한·하나·우리·NH농협)가 상반기 기준 역대 최대 순이익 기록을 갈아치운 데 이어 직원들의 상반기 평균 급여도 일제히 지난해보다 올랐다.', 'c139a450fd54e296ce54d4aa207c83a03cc1418464695d1c7550def2c5856e96', true, false),
  (156, 'S2', 2, '특히 주요 금융지주 가운데 직원 1인당 평균 월급이 2000만원을 넘어선 곳도 나왔다.', 'e7be65e29b0ad85bbfa3ac1ff5a556795504f54cfabf7f2a63e49af949dc0950', true, false),
  (156, 'S3', 3, '18일 금융감독원 전자공시시스템에 공시한 5대 금융지주의 반기보고서에 따르면 올해 상반기 직원 1인당 평균 급여액이 가장 높은 곳은 KB금융(105560)지주로 1억2100만원이었다.', '2457cfe68f9a5844b3352590505d2cd589850a773a74d72a6bc9dfbd107c4141', true, false),
  (156, 'S4', 4, '상반기 기준 KB금융지주의 직원 1인당 평균 급여액은 지난해 1억1200만원에서 올해 1억2100만원으로 900만원(8.0%) 늘었다.', '64e23da73efd67cf5f57cc93fcee985b1568a3aeb53942ad0f1dfdd1bd122829', true, false),
  (156, 'S5', 5, '이를 6개월로 단순 환산하면 직원 1명당 월평균 2000만원이 넘는 급여를 받은 셈이다.', '78196a023c3aa66273011483c887318832b3fb52fee67d78ac13f15d4df66f18', true, false),
  (156, 'S6', 6, '우리금융지주(316140)와 하나금융지주(086790)도 상반기에만 직원 1명당 평균 1억원 넘는 급여를 지급했다.', '7486e05c1155662181d1a43014d446c607388fd1d1aba8da1702141e1c107fed', true, false),
  (156, 'S7', 7, '우리금융지주의 직원 1인당 평균 급여액은 1억1000만원으로 지난해 상반기 1억500만원보다 500만원 늘었다.', 'dd1df2b7b29b896756af70c6a7eb2a0a9363d8787b77705d12f04821d3741b7b', true, false),
  (156, 'S8', 8, '월평균으로 환산하면 약 1833만원이다.', 'e342890d24517dbdea88f6c2743a5b59d8e94a54a826e0f4daf76cd0aee1fd8a', true, false),
  (156, 'S9', 9, '하나금융지주는 지난해 상반기 9500만원에서 올해 1억600만원으로 1100만원 증가했다.', '7f4dcebd967197003436e17b7560988389e155a7be7afd625dc690702c4e3af6', true, false),
  (156, 'S10', 10, '5대 금융지주 가운데 증가액이 가장 컸다.', '0ad80b571389deb6d4206f1813b9b2d5da691b223abe2f81cf279ad672a3f349', true, false),
  (156, 'S11', 11, '신한지주(055550)의 직원 1인당 평균 급여액은 9700만원으로 지난해 상반기 9200만원보다 500만원 늘었다.', 'c5f04eb22f24d60b304a83fb9f1f4b1703dbbd69b934335b954dfe49dbdf1e49', true, true),
  (156, 'S12', 12, '반기보고서에 기재되는 1인 평균 급여액은 해당 기간 직원들에게 지급된 급여 총액을 평균 인원 등을 기준으로 산출한 수치로 기본급뿐 아니라 상여금과 성과급 등이 포함된다.', 'e2fa78eaee72c77561556722fabae50cc5b1b784442ca5dbbd725deab83668b9', true, false),
  (157, 'S1', 1, '1만1700여명 참여·탄소 6만8000㎏ 감축 효과…환경단체에 2000만원 기부', 'b7f473c1487db4b7df3598644948e15eb806cfd28dcfe1e066494e0b1d037fd6', true, false),
  (157, 'S2', 2, '키움증권 걸음 기부 캠페인 ‘키움과맑음 시즌3’에 참여해 7월 한 달 동안 가장 많은 걸음을 기부한 직원들이 서울 여의도 키움증권 본사에서 기념촬영을 하고 있다.', '0e12a5e536873dd1bb25bf96bb51b2ba3fcf7387ba029b185f2730f3341ab8ba', true, false),
  (157, 'S3', 3, '(왼쪽부터) 임상옥 자금세탁불공정방지팀 팀장, 구효정 기업금융심사팀 과장, 김호준 채널기획팀 과장.(사진=키움증권 제공) *재판매 및 DB 금지', 'e2ab2271aa3a64450dc94d16d24832f768a77a1fe9c54dafcd3001ca24d49ddc', true, false),
  (157, 'S4', 4, '[서울=뉴시스]송혜리 기자 = 키움증권은 걸음 기부 캠페인 ''키움과맑음 시즌3''을 성료했다고 10일 밝혔다.', '27aa4c19b3dceda252dbeced14323e680cf3af11b2662ce18b9c5f3c4ce47e27', true, false),
  (157, 'S5', 5, '키움과맑음 시즌3는 지난 7월 한 달간 키움증권 전 임직원이 일상 속 걷기를 통해 탄소 중립과 온실가스 감축을 실천하는 활동이다.', '6674c0f119b773f5165fd070d622dbe03c6fb54aa6cbfeebae3b02617abb7bff', true, false),
  (157, 'S6', 6, '걸음 기부 플랫폼 ''빅워크 애플리케이션''을 통해 하루 동안 걸은 걸음을 기부하는 방식이다.', '4392d663eeccc24b50ecc939146dde13e8be18133ec48046077b1b97de05c8ef', true, false),
  (157, 'S7', 7, '이번 캠페인은 임직원뿐만 아니라 일반 시민도 함께 참여해 의미를 더했다.', '5b438bb763600d02f1cf8949f27759e8f777a428f6a7c91a2cc01304689ba2e4', true, false),
  (157, 'S8', 8, '이번 캠페인 기간 동안 총 1만1728명이 걸음 기부에 동참했다.', 'f96dc01e980b7bfb3964bf8ddab2a5d686e4c2c626edbc72f1d92632d4cde2f2', true, false),
  (157, 'S9', 9, '하루 평균 기부된 걸음 수는 2388만보였다.', '844456306e79cc647dc0d02d0c52fdd2e4dc3eabaca41d2f708e59c68b32d3d6', true, false),
  (157, 'S10', 10, '이 기간 기부된 걸음은 총 7억4028만보에 달한다.', 'b3784a3ed1a2b78a797e8f1a845c3eee002a730ffc2991e86bf5af4867578fc2', true, false),
  (157, 'S11', 11, '거리로 환산하면 51만8221㎞에 이르는 수치다.', '4c9cb996d3a646fb18395b662de5a728a877507c193c2bb7dafc964c7cf305f1', true, false),
  (157, 'S12', 12, '목표 달성에 따라 키움증권은 사회적협동조합 ‘한강’에 2000만원을 기부할 예정이다.', 'c68d89b8f5069eb741947579ac3524a84d67a7ae1640a4b2042d4cc58476f789', true, true)
on conflict do nothing;

