  (14, 18, 'draft', 'binding_contract', 'binding_contract', array['096770']::text[], array['096770']::text[], 'SK이노베이션이 테라파워와 나트륨 SMR 사업 협력 주요 조건 합의서를 체결했으며, 합의서에는 미국 케머러 1호기와 후속 상용 프로젝트 참여 확대가 포함됐다.', 'SK이노베이션, 테라파워와 나트륨 SMR 협력 합의서 체결', 'SK이노베이션, 테라파워와 나트륨 SMR 협력 합의서 체결', '14일 서울에서 두 대표가 만났어요.', 'SK와 SK이노베이션은 총 2억5000만달러를 공동 투자했어요.', '케머러 1호기와 후속 상용 프로젝트 참여를 확대할 계획이에요.', '[{"term":"소형모듈원자로(SMR)","easyText":"원자력으로 전기를 만드는 작은 발전 시설","sourceIds":["S3"],"treatment":"explained"},{"term":"SMR","easyText":"소형모듈원자로를 줄여 부르는 말","sourceIds":["S3","S4","S6","S7"],"treatment":"explained"},{"term":"나트륨 SMR","easyText":"나트륨을 활용하는 작은 원자력 발전 시설","sourceIds":["S4","S6","S7"],"treatment":"explained"},{"term":"사업협력 주요 조건 합의서","easyText":"사업을 함께하기로 정한 중요한 약속 문서","sourceIds":["S4"],"treatment":"explained"},{"term":"최고경영자(CEO)","easyText":"회사의 일을 가장 책임지는 사람","sourceIds":["S4"],"treatment":"explained"},{"term":"공동 투자","easyText":"여러 곳이 돈을 함께 넣는 투자","sourceIds":["S5"],"treatment":"explained"},{"term":"2대 주주","easyText":"회사 주식을 두 번째로 많이 가진 사람이나 회사","sourceIds":["S5"],"treatment":"explained"},{"term":"실증로","easyText":"새 원자로 기술이 실제로 작동하는지 시험하는 시설","sourceIds":["S6"],"treatment":"explained"},{"term":"상용 프로젝트","easyText":"제품이나 서비스를 실제로 팔기 위한 사업","sourceIds":["S6","S7"],"treatment":"explained"},{"term":"공급망","easyText":"제품을 만들고 옮기는 데 필요한 회사와 과정","sourceIds":["S6"],"treatment":"explained"},{"term":"글로벌 프로젝트 공동 발굴","easyText":"세계 여러 곳의 사업을 함께 찾아내는 일","sourceIds":["S6"],"treatment":"explained"}]'::jsonb, true, true, true, true, true, true, true, true, true, true, true, true, 1, '2026-08-15T09:35:37.676+00:00', '2026-08-15T10:41:01.675+00:00', '2026-08-15T10:41:01.57114+00:00', 'meeting_date_place', 'joint_investment_total', 'project_participation_plan', 'contracted_business', 'event_education', '사업 협력 합의는 회사의 사업 참여와 계약에 연결될 수 있어요.', true, true, true, true),
