  (20, 24, 'draft', 'material_operational_risk', 'material_operational_risk', array['005380']::text[], array['005380']::text[], '현대차 노조의 파업으로 4만대가 넘는 생산 차질이 발생한 가운데, 현대차와 노조는 18일 오후 2시 본교섭을 재개하기로 했다.', '현대차 노동조합, 18일 오후 2시 본교섭 재개하기로', '현대차 노동조합, 18일 오후 2시 본교섭 재개하기로', '올해 파업으로 4만대 넘는 생산 차질이 났어요.', '노조는 18일까지 매일 4∼6시간 파업해요.', '하반기 신차 출시를 통한 실적 반등이 필요해요.', '[{"term":"파업","easyText":"일하는 사람들이 요구를 알리려고 일을 멈추는 행동","sourceIds":["S3","S4","S6"],"treatment":"explained"},{"term":"파업 수위","easyText":"파업을 얼마나 오래 또는 강하게 할지의 정도","sourceIds":["S3"],"treatment":"explained"},{"term":"노동조합","easyText":"일하는 사람들이 권리를 지키려고 만든 모임","sourceIds":["S3"],"treatment":"explained"},{"term":"사측","easyText":"회사를 운영하는 쪽","sourceIds":["S3"],"treatment":"explained"},{"term":"교섭","easyText":"회사와 노동자가 조건을 의논하는 일","sourceIds":["S3","S4"],"treatment":"explained"},{"term":"본교섭","easyText":"회사와 노동자가 공식적으로 하는 협상","sourceIds":["S3"],"treatment":"explained"},{"term":"생산 차질","easyText":"제품을 계획대로 만들지 못하는 상황","sourceIds":["S4"],"treatment":"explained"},{"term":"하반기","easyText":"한 해의 뒤쪽 절반","sourceIds":["S4"],"treatment":"explained"},{"term":"신차 출시","easyText":"새 자동차를 시장에 내놓는 일","sourceIds":["S4"],"treatment":"explained"},{"term":"실적 반등","easyText":"사업 결과가 다시 좋아지는 것","sourceIds":["S4"],"treatment":"explained"},{"term":"노조","easyText":"일하는 사람들이 함께 만든 모임","sourceIds":["S6"],"treatment":"explained"}]'::jsonb, true, true, true, true, true, true, true, true, true, true, true, true, 2, '2026-08-15T09:35:37.676+00:00', '2026-08-15T10:41:03.646+00:00', '2026-08-15T12:01:03.718116+00:00', 'production_disruption', 'strike_schedule', 'h2_rebound_need', 'operational_continuity', 'event_education', '생산 차질은 차량을 만들고 팔 수 있는 수와 연결될 수 있어요.', true, true, true, true),
  (21, 25, 'draft', 'merger_or_ownership', 'merger_or_ownership', array['089860']::text[], array['089860']::text[], '호텔롯데와 부산롯데호텔이 보유한 롯데렌탈 지분 61.17%를 미국계 사모펀드 TPG에 매각했다.', '롯데렌탈, 호텔롯데·부산롯데호텔 보유 지분 61.17%를 TPG에 매각', '롯데렌탈, 호텔롯데·부산롯데호텔 보유 지분 61.17%를 TPG에 매각', '롯데렌탈은 국내 렌터카 1위 업체예요.', 'TPG는 인수 대금 전액을 자체 펀드로 조달할 것으로 알려졌어요.', 'TPG는 미국계 사모펀드예요.', '[{"term":"렌터카","easyText":"차를 빌려주는 서비스","sourceIds":["S2"],"treatment":"explained"},{"term":"사모펀드","easyText":"몇몇 사람의 돈을 모아 회사에 투자하는 곳","sourceIds":["S2"],"treatment":"explained"},{"term":"PEF","easyText":"사모펀드를 영어로 줄여 부르는 말","sourceIds":["S2"],"treatment":"explained"},{"term":"TPG","easyText":"롯데렌탈의 몫을 산 미국계 투자 회사","sourceIds":["S2","S4","S5"],"treatment":"explained"},{"term":"투자은행","easyText":"회사의 큰 거래와 돈 마련을 돕는 회사","sourceIds":["S4"],"treatment":"explained"},{"term":"IB","easyText":"투자은행을 영어로 줄여 부르는 말","sourceIds":["S4"],"treatment":"explained"},{"term":"지분","easyText":"회사의 전체 주식 중 누군가가 가진 몫","sourceIds":["S4"],"treatment":"explained"},{"term":"매각","easyText":"가지고 있던 것을 다른 곳에 파는 일","sourceIds":["S4"],"treatment":"explained"},{"term":"인수 대금","easyText":"지분을 사면서 내는 돈","sourceIds":["S5"],"treatment":"explained"},{"term":"펀드","easyText":"투자에 쓰려고 모아 둔 돈","sourceIds":["S5"],"treatment":"explained"},{"term":"조달","easyText":"필요한 돈을 마련하는 일","sourceIds":["S5"],"treatment":"explained"}]'::jsonb, true, true, true, true, true, true, true, true, true, true, true, true, 1, '2026-08-15T09:35:37.676+00:00', '2026-08-15T10:41:04.004+00:00', '2026-08-15T10:41:03.936226+00:00', 'rental_car_rank', 'acquisition_funding', 'buyer_type', 'ownership_and_credit', 'event_education', '지분 매각은 회사의 소유 구조와 중요한 결정 방식에 연결될 수 있어요.', true, true, true, true),
  (22, 26, 'draft', 'material_operational_risk', 'material_operational_risk', array['329180']::text[], array['329180']::text[], 'HD현대중공업 노동조합이 임금·단체협약 교섭 난항으로 중앙노동위원회에 노동 쟁의 조정을 신청했고, 25일부터 27일까지 파업 찬반 투표를 진행할 예정이다.', 'HD현대중공업 노조, 중앙노동위원회에 노동 쟁의 조정 신청', 'HD현대중공업 노조, 중앙노동위원회에 노동 쟁의 조정 신청', '노동 쟁의 조정 신청일은 14일이에요.', '25~27일 파업 찬반 투표가 예정됐어요.', '6월 상견례 뒤 15차례 교섭했지만 의견 차이를 못 좁혔어요.', '[{"term":"노동조합","easyText":"일하는 사람들이 근무 조건을 함께 의논하는 모임","sourceIds":["S2"],"treatment":"explained"},{"term":"임금·단체협약","easyText":"월급과 일터 규칙을 함께 정한 약속","sourceIds":["S2"],"treatment":"explained"},{"term":"교섭","easyText":"회사와 일하는 사람들이 조건을 의논하는 일","sourceIds":["S2","S6"],"treatment":"explained"},{"term":"중앙노동위원회","easyText":"일터에서 생긴 다툼을 다루는 기관","sourceIds":["S3","S4"],"treatment":"explained"},{"term":"노동 쟁의 조정","easyText":"일터 다툼을 풀 방법을 찾는 절차","sourceIds":["S3"],"treatment":"explained"},{"term":"조정 중지","easyText":"다툼을 풀려는 절차를 멈추는 결정","sourceIds":["S4"],"treatment":"explained"},{"term":"노사","easyText":"회사와 일하는 사람들","sourceIds":["S4","S6"],"treatment":"explained"},{"term":"파업 찬반 투표","easyText":"파업을 할지 말지 묻는 투표","sourceIds":["S4","S5"],"treatment":"explained"},{"term":"과반 찬성","easyText":"절반보다 많은 사람이 찬성하는 것","sourceIds":["S4"],"treatment":"explained"},{"term":"합법적인 파업권","easyText":"법에 맞게 일을 멈출 수 있는 권리","sourceIds":["S4"],"treatment":"explained"},{"term":"조합원","easyText":"일하는 사람들 모임에 가입한 사람","sourceIds":["S5"],"treatment":"explained"},{"term":"상견례","easyText":"교섭을 시작하며 서로 인사하는 자리","sourceIds":["S6"],"treatment":"explained"},{"term":"기본급","easyText":"월급의 기본이 되는 금액","sourceIds":["S7"],"treatment":"explained"},{"term":"상여금","easyText":"월급과 따로 받는 보너스","sourceIds":["S7"],"treatment":"explained"},{"term":"요구안","easyText":"상대에게 이루어 달라고 내놓은 내용","sourceIds":["S7"],"treatment":"explained"},{"term":"영업이익","easyText":"사업으로 번 돈에서 운영 비용을 뺀 금액","sourceIds":["S8"],"treatment":"explained"},{"term":"성과 공유","easyText":"일의 결과로 얻은 것을 함께 나누는 것","sourceIds":["S8"],"treatment":"explained"},{"term":"통상임금 산입","easyText":"평소 받는