  (23, 27, 'draft', 'regulatory_decision', 'regulatory_decision', array['042660']::text[], array['042660']::text[], '미국 대통령이 13일(현지 시간) 외국 조선소에서 군함을 2척까지 건조하는 방안을 조건부로 허용하는 각서에 서명했다. 한화오션과 한화시스템 컨소시엄은 2024년 미국 필라델피아 필리조선소 지분 100%를 인수했고, 기사에서는 한화가 이 조건에 부합한다고 전했다.', '한화오션·한화시스템, 미국 군함 건조 조건에 부합', '한화오션·한화시스템, 미국 군함 건조 조건에 부합', '조건을 지키면 외국 조선소에서 군함 2척까지 지을 수 있어요.', '한화오션·한화시스템은 필리조선소 지분 100%를 인수했어요.', '이후 모든 선박을 만들고 고칠 때 미국 내 공급망을 써야 해요.', '[{"term":"조선소","easyText":"배를 만들고 고치는 곳","sourceIds":["S4","S6","S7","S8","S9"],"treatment":"explained"},{"term":"군함","easyText":"나라의 군대가 쓰는 배","sourceIds":["S4"],"treatment":"explained"},{"term":"건조","easyText":"배를 새로 만드는 일","sourceIds":["S4","S9"],"treatment":"explained"},{"term":"조건부로 허용","easyText":"정해진 조건을 지키면 할 수 있게 함","sourceIds":["S4"],"treatment":"explained"},{"term":"각서","easyText":"약속이나 계획을 적은 문서","sourceIds":["S6"],"treatment":"explained"},{"term":"조선산업 기반 재건","easyText":"배 만드는 산업의 바탕을 다시 세우는 일","sourceIds":["S6"],"treatment":"explained"},{"term":"소유권","easyText":"무언가를 가질 수 있는 권리","sourceIds":["S6"],"treatment":"explained"},{"term":"과반 지분","easyText":"회사 주식의 절반보다 많은 몫","sourceIds":["S6"],"treatment":"explained"},{"term":"외국 조선업체","easyText":"다른 나라에서 배를 만드는 회사","sourceIds":["S6"],"treatment":"explained"},{"term":"인수","easyText":"다른 회사나 재산을 넘겨받는 일","sourceIds":["S7","S8"],"treatment":"explained"},{"term":"컨소시엄","easyText":"여러 회사가 함께 만든 모임","sourceIds":["S8"],"treatment":"explained"},{"term":"지분","easyText":"회사 전체에서 가진 주식의 몫","sourceIds":["S6","S8"],"treatment":"explained"},{"term":"유지·보수","easyText":"고장 없이 쓰도록 관리하고 고치는 일","sourceIds":["S9"],"treatment":"explained"},{"term":"공급망","easyText":"제품을 만들고 옮기는 데 이어진 회사와 과정","sourceIds":["S9"],"treatment":"explained"}]'::jsonb, true, true, true, true, true, true, true, true, true, true, true, true, 1, '2026-08-15T09:35:37.676+00:00', '2026-08-15T10:41:04.65+00:00', '2026-08-15T10:41:04.591006+00:00', 'warship_build_limit', 'shipyard_stake_acquired', 'us_supply_chain', 'regulatory_