  (25, 29, 'draft', 'merger_or_ownership', 'merger_or_ownership', array['180640']::text[], array['180640']::text[], '한진그룹 공익법인이 한진칼 지분을 사들이고 이명희 고문이 일부를 매각한 뒤, 한진칼이 공시한 조원태 회장 등 특수관계자 지분은 31.15%로 6280주(0.01%) 늘었다.', '한진칼, 특수관계자 지분 31.15%로 늘어', '한진칼, 특수관계자 지분 31.15%로 늘어', '특수관계자 지분은 2079만6274주예요.', '한진그룹 공익법인이 한진칼 지분을 샀어요.', '이명희 고문은 일부 지분을 매각했어요.', '[{"term":"지분","easyText":"회사에서 차지하는 몫","sourceIds":["S3","S4","S6","S9"],"treatment":"explained"},{"term":"매각","easyText":"가지고 있던 몫을 파는 일","sourceIds":["S3","S4"],"treatment":"explained"},{"term":"공익법인","easyText":"좋은 일을 위해 만든 단체","sourceIds":["S3"],"treatment":"explained"},{"term":"지주사","easyText":"다른 회사의 몫을 가진 회사","sourceIds":["S3"],"treatment":"explained"},{"term":"특수관계자","easyText":"회사와 특별한 관계인 사람","sourceIds":["S6"],"treatment":"explained"},{"term":"공시","easyText":"회사 정보를 공식적으로 알리는 일","sourceIds":["S6"],"treatment":"explained"}]'::jsonb, true, true, true, true, true, true, true, true, true, true, true, true, 2, '2026-08-15T09:35:37.676+00:00', '2026-08-15T10:41:53.817+00:00', '2026-08-15T10:41:53.743531+00:00', 'stake_shares', 'foundation_purchase', 'advisor_sale', 'ownership_and_credit', 'event_education', '지분을 가진 사람이나 단체의 변화는 회사의 중요한 결정과 연결될 수 있어요.', true, true, true, true),
